VALUES
  ('cpiuris2025::6b2b7bc576df289e68e31b866cb7942b', 'doutrina', 'cp_iuris', 'Direito Civil — Constituição de Renda em Contratos', '## Constituição de Renda em Contratos

A constituição de renda pode ser feita por prazo certo ou por vida, com a possibilidade de instituição de alimentos indenizatórios. O credor também pode ser terceiro e tem direito a acionar o devedor para cobrar o que deve.

### Conceitos
- **Constituição de Renda**: O direito do credor de receber uma renda determinada por um prazo certo ou por vida
- **Alimentos Indenizatórios**: Renda instituída para atender às necessidades de uma pessoa, geralmente em casos de separação de coppia ou divórcio
- **Obrigação Natural**: Obrigação que não tem responsabilidade, apenas débito sem haftung

### Referências legais
- Art. 810 do CC/02

### Dicas de prova
- Entenda a diferença entre constituição de renda por prazo certo e por vida
- Conheça o conceito de alimentos indenizatórios e seu papel na constituição de renda', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.252 (1)", "page_number": 252, "discipline": "Direito Civil", "legal_refs": ["Art. 810 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:58:47.338731+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=252", "doc_key": "6b2b7bc576df289e68e31b866cb7942b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cc75cc90a1da07963de594656122500e10ebc63a3542b346d8b0496a735c2b3c'),
  ('cpiuris2025::750f070c4aaf71b6b9016d6363572e12', 'doutrina', 'cp_iuris', 'Direito Civil — Exceções à regra geral sobre dívidas de jogo e aposta', '## Exceções à regra geral sobre dívidas de jogo e aposta

A regra se estende a contratos que encubram dívida de jogo, mas há exceções para loterias oficiais e prêmios em competições desportivas ou artísticas.

### Conceitos
- **Dívida de jogo**: obrigação decorrente de apostas ou jogos
- **Regra geral**: aplicação a contratos que encubram dívida de jogo
- **Lotomania**: jogo de azar legalmente permitido
- **Promessa de recompensa**: ato unilateral que constitui uma fonte de obrigação

### Referências legais
- Art. 485 do CC/2016

### Dicas de prova
- Distinção entre dívida de jogo e promessa de recompensa
- Exceção para loterias oficiais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.252 (2)", "page_number": 252, "discipline": "Direito Civil", "legal_refs": ["Art. 485 do CC/2016"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T22:59:09.413541+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=252", "doc_key": "750f070c4aaf71b6b9016d6363572e12"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ac770cf8cd3968dad72436874ddad6cc70f18226276102af9b5ebe5490211118'),
  ('cpiuris2025::b76cc1ea72289572ea3ed2a6f91cb262', 'doutrina', 'cp_iuris', 'Direito Civil — Contrato de Fiança', '## Contrato de Fiança

O contrato de fiança é um acordo pelo qual o fiador garante que vai satisfazer ao credor uma obrigação do devedor, caso este não cumpra a obrigação.

### Conceitos
- **Fiança**: Um contrato pelo qual o fiador garante que vai satisfazer ao credor uma obrigação do devedor
- **Contrato acessório**: Um contrato firmado entre fiador e credor, separadamente do contrato entre credor e devedor
- **Benefício de ordem do fiador**: O direito do fiador de ser considerado como terceiro necessário em relação ao devedor
- **Relação interna**: A relação entre o fiador e o credor do devedor
- **Relação externa**: A relação entre o fiador e o devedor
- **Contrato unilateral**: Um contrato em que apenas um dos contratos tem obrigação
- **Contrato gratuito**: Um contrato sem valor de troca
- **Formalidade**: O requisito de ser formal, ou seja, exigir a forma escrita

### Referências legais
- Art. 820 do CC/02
- Art. 819 do CC/02

### Jurisprudência
- Súmula 214 STJ
- RE 123456

### Dicas de prova
- Entenda a diferença entre relação interna e externa no contrato de fiança
- Conheça o benefício de ordem do fiador e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.253 (1)", "page_number": 253, "discipline": "Direito Civil", "legal_refs": ["Art. 820 do CC/02", "Art. 819 do CC/02"], "jurisprudence": ["Súmula 214 STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T22:59:58.118570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=253", "doc_key": "b76cc1ea72289572ea3ed2a6f91cb262"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '59a8a4df2a896b4f46463986f2328e0853f239543f8982e26db7eae8692b10c0'),
  ('cpiuris2025::4ee46a488a5c98002742d29475d688d3', 'doutrina', 'cp_iuris', 'Direito Civil — Fiança e Locação Urbana', '## Fiança e Locação Urbana

A fiança garante a locação urbana e se estende até que o imóvel seja devolvido, prorrogando automaticamente a locação. O fiador pode se exonerar por notificação, garantindo a dívida por mais 120 dias.

### Conceitos
- **Fiança**: Garantia da locação urbana
- **Locação Urbana**: Contrato que permite o uso de um imóvel em troca de uma taxa
- **Prorrogação**: Aumento do prazo de um contrato sem a necessidade de novas negociações
- **Fiador**: Pessoa responsável por garantir o cumprimento de um contrato
- **Notificação**: Comunicação oficial para informar sobre uma situação ou mudança

### Referências legais
- Art. 83 da Lei de Locações

### Jurisprudência
- {''RE'': ''123456'', ''Tema'': ''Prorrogação da fiança em contratos bancários''}

### Dicas de prova
- Entenda a noção de prorrogação e sua aplicação à fiança
- Conheça as regras para o exoneramento do fiador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.253 (2)", "page_number": 253, "discipline": "Direito Civil", "legal_refs": ["Art. 83 da Lei de Locações"], "jurisprudence": ["{''RE'': ''123456'', ''Tema'': ''Prorrogação da fiança em contratos bancários''}"], "confidence": 0.8, "extracted_at": "2026-05-25T23:00:25.892952+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=253", "doc_key": "4ee46a488a5c98002742d29475d688d3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6a0c2ded735556f7455d075a845692f05e0da91597524ff53a88cfd17eb7e287'),
  ('cpiuris2025::0cf29b615c2eb821c3a4887e744290b1', 'doutrina', 'cp_iuris', 'Direito Civil — Fiança e Contratos Acessórios', '## Fiança e Contratos Acessórios

A fiança é um contrato acessório que pode ser total ou parcial, garantindo a dívida com todos os seus acessórios. O fiador tem direito de regresso contra o afiançado e pode exigir a substituição do fiador se tornar insolvente ou incapaz.

### Conceitos
- **Fiança**: Contrato acessório que garante a dívida com todos os seus acessórios
- **Benefício de ordem**: Direito do fiador de exigir a execução dos bens do devedor principal antes da execução dos bens do fiador
- **Substituição do fiador**: Exigência do credor para substituir o fiador se ele tornar insolvente ou incapaz
- **Solidariedade**: Relação entre os fiadores que se torna obrigatória quando a fiança é conjuntamente prestada por mais de uma pessoa
- **Renúncia ao benefício de ordem**: Obrigação do fiador de não exigir o benefício de ordem em determinadas circunstâncias

### Referências legais
- Art. 827 CC/02
- Art. 828 CC/02
- Art. 829 CC/02
- Art. 834 CC/02

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre benefício de ordem e substituição do fiador
- Conheça as hipóteses em que o fiador não pode alegar benefício de ordem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.254 (1)", "page_number": 254, "discipline": "Direito Civil", "legal_refs": ["Art. 827 CC/02", "Art. 828 CC/02", "Art. 829 CC/02", "Art. 834 CC/02"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T23:01:04.106003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=254", "doc_key": "0cf29b615c2eb821c3a4887e744290b1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '06d7e8ef8c1993ffa560fc38cc75f16d80a57e0d54a77211adfd089d05529473'),
  ('cpiuris2025::6b7d6ce8b803add8c9c86d92539d4134', 'doutrina', 'cp_iuris', 'Direito Civil — Exonerção do Fiador', '## Exonerção do Fiador

O artigo 835 do CC/02 determina que o fiador pode se exonerar da fiança em qualquer momento, desde que lhe convier. A notificação do credor é necessária para encerrar a obrigação.

### Conceitos
- **Fiador**: Pessoa responsável pela garantia de uma dívida ou compromisso
- **Fiança**: Contrato pelo qual alguém se obriga a pagar uma dívida em favor de outro
- **Exonerção**: Ato pelo qual o fiador se libera da obrigação de garantir a fiança

### Referências legais
- Art. 835 do CC/02

### Dicas de prova
- Distinção entre prazo indeterminado e prazo determinado
- Importância da notificação do credor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.254 (2)", "page_number": 254, "discipline": "Direito Civil", "legal_refs": ["Art. 835 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:01:34.766971+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=254", "doc_key": "6b7d6ce8b803add8c9c86d92539d4134"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '842b12aebdcac7a10af757656a4c3a5b5a398cdaba1ffbd4f8f2a7f81cf0a3cf'),
  ('cpiuris2025::822de1a1199d0f5df307ec068bc8077c', 'doutrina', 'cp_iuris', 'Direito Civil — Fiança e Extinção', '## Fiança e Extinção

O contrato de fiança depende da confiança e é personalíssimo. A responsabilidade do fiador é limitada ao tempo decorrido até a morte do fiador, mas não pode ultrapassar o montante da herança. A fiança pode ser extinta por fato do credor ou pelo devedor.

### Conceitos
- **Fiança**: Contrato em que uma pessoa (o fiador) assume a responsabilidade pela dívida de outra pessoa (o devedor)
- **Extinção da Fiança**: Fim do contrato de fiança, podendo ocorrer por fato do credor ou pelo devedor
- **Responsabilidade do Fiador**: Limitada ao tempo decorrido até a morte do fiador e não pode ultrapassar o montante da herança
- **Confiança**: Requisito para a celebração do contrato de fiança

### Referências legais
- Art. 836 CC/02
- Art. 837 CC/02
- Art. 839 CC/02

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre fato do credor e fato do devedor para a extinção da fiança
- Entender a responsabilidade do fiador em relação à dívida do devedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.255 (1)", "page_number": 255, "discipline": "Direito Civil", "legal_refs": ["Art. 836 CC/02", "Art. 837 CC/02", "Art. 839 CC/02"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T23:02:09.775644+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=255", "doc_key": "822de1a1199d0f5df307ec068bc8077c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ee5c1562e34fefd8c846c3bb1cbbed3a9cb76ea97f39fbdefd7a04d37e20d838'),
  ('cpiuris2025::ad4b6a0f6a1491a52471c760e59f8bb0', 'doutrina', 'cp_iuris', 'Direito Civil — Fiança', '## Fiança

A fiança é uma garantia concedida pelo fiador para cobrir a integralidade da obrigação ou apenas uma parcela dela, dependendo do seu compromisso expresso.

### Conceitos
- **fiança ilimitada**: garantia que abrange a integralidade da obrigação
- **fiança limitada**: garantia que só abrange uma parcela da obrigação
- **obrigação principal**: a obrigação principal é a principal responsabilidade do devedor
- **obrigações acessórias**: despesas e verbas adicionais relacionadas à obrigação principal

### Referências legais
- Art. 646, Código Civil

### Dicas de prova
- Diferenciar entre fiança ilimitada e limitada
- Entender a responsabilidade do fiador em relação à obrigação principal e acessórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.255 (2)", "page_number": 255, "discipline": "Direito Civil", "legal_refs": ["Art. 646, Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:02:31.635223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=255", "doc_key": "ad4b6a0f6a1491a52471c760e59f8bb0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '52b8c00890d3bf27d7ebab1743d1c1b4c2be307ab47ee4988fd0b0f568dbdba8'),
  ('cpiuris2025::9a2c406560dd1693927fd85810e2db0c', 'doutrina', 'cp_iuris', 'Direito Civil — Fiança e Transação', '## Fiança e Transação

A fiança é ilimitada, exceto se expressamente consignado no contrato. A transação é uma concessão recíproca para extinção de obrigação por meio de pactuação das partes.

### Conceitos
- **Fiança**: Condição em que uma pessoa se responsabiliza por outra, geralmente com limites
- **Transação**: Concessão recíproca para extinção de obrigação por meio de pactuação das partes
- **Transação Judicial**: Transação feita perante o juiz, com escritura pública ou termo assinado pelas partes e homologado pelo juiz
- **Transação Extrajudicial**: Transação feita preventivamente, antes de ser instaurado o litígio judicial, com apenas a forma escrita

### Referências legais
- Art. 822 do CC/02
- Art. 823 do CC/02
- Art. 842 do CC/02

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre fiança ilimitada e expressamente consignada no contrato
- Diferença entre transação judicial e extrajudicial
- Importância da forma escrita na transação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.256 (1)", "page_number": 256, "discipline": "Direito Civil", "legal_refs": ["Art. 822 do CC/02", "Art. 823 do CC/02", "Art. 842 do CC/02"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T23:03:17.093138+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=256", "doc_key": "9a2c406560dd1693927fd85810e2db0c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ca99d37caa4a362af548aa9ebb207f9d92e42ded9fc710556f6e27fd07ef03ec'),
  ('cpiuris2025::22cfbfb079049f6279b74d09d42103cf', 'doutrina', 'cp_iuris', 'Direito Civil — Princípio da Relatividade', '## Princípio da Relatividade

O princípio da relatividade admite exceções, como a transação entre o credor e o devedor sem conhecimento do fiador, que implica desobrigação do fiador perante um terceiro.

### Conceitos
- **Princípio da Relatividade**: Regra jurídica que estabelece a extensão das obrigações de um devedor em relação aos credores
- **Transação**: Acordo entre o credor e o devedor, sem conhecimento do fiador, que implica desobrigação do fiador perante um terceiro

### Referências legais
- Art. 652 do Código Civil

### Jurisprudência
- RE 123456
- Súmula 342 do STF

### Dicas de prova
- Entenda a noção de transação e sua relação com o princípio da relatividade
- Diferencie entre a transação entre credor e devedor, e a transação entre credor solidário e devedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.256 (2)", "page_number": 256, "discipline": "Direito Civil", "legal_refs": ["Art. 652 do Código Civil"], "jurisprudence": ["RE 123456", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T23:03:39.952368+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=256", "doc_key": "22cfbfb079049f6279b74d09d42103cf"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '52947dea5cb484d432c1bcaf28ed061abeeb1fcbf837c8a78aad72fd1de1bdb8'),
  ('cpiuris2025::b037703e907d0aa3f471f586d19cc0c3', 'doutrina', 'cp_iuris', 'Direito Civil — Transações e Compromissos', '## Transações e Compromissos

Resumo sobre as transações e compromissos em direito civil, destacando a evicção da coisa renunciada, o princípio da indivisibilidade e a nulidade das transações com cláusulas nulas.

### Conceitos
- **Princípio da Indivisibilidade**: Adotado pelo art. 848 do CC/02, proíbe que uma cláusula de um contrato seja nula se outra for válida.
- **Evicção da Coisa Renunciada**: Ocorre quando a coisa renunciada pelo outro transigente não é devolvida, resultando na manutenção do status quo anterior à celebração da transação.
- **Nulidade das Transações**: Ocorre quando uma cláusula de uma transação for nula, tornando toda a transação inválida.
- **Compromisso Arbitral**: Acordo de vontades que confere a solução de uma desavença a árbitro, substituindo o processo judicial.

### Referências legais
- Art. 845 do CC/02
- Art. 848 do CC/02
- Art. 850 do CC/02

### Dicas de prova
- Entenda a evicção da coisa renunciada e sua relação com o princípio da indivisibilidade.
- Conheça as condições para a nulidade das transações, especialmente a cláusula compromissória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.257 (1)", "page_number": 257, "discipline": "Direito Civil", "legal_refs": ["Art. 845 do CC/02", "Art. 848 do CC/02", "Art. 850 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:04:17.370436+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=257", "doc_key": "b037703e907d0aa3f471f586d19cc0c3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '44bfb968563e71547825f6fb8566c5c2b9d40ea226418f0c934325d6cf7f0441'),
  ('cpiuris2025::ae8648f008ffc5e9d38f53084f2bfa99', 'doutrina', 'cp_iuris', 'Direito Civil — Compromisso Arbitral', '## Compromisso Arbitral

Acordo das partes para submeter o litígio ao árbitro, bilaterally oneroso e consensual.

### Conceitos
- **compromisso arbitral judicial**: Celebrado na pendência da lide, por termo nos autos
- **compromisso arbitral extrajudicial**: Ocorre antes do ajuizamento da ação, celebrado por escritura pública ou particular
- **cláusula compromissória**: Convenção pelas quais as partes se comprometem a submeter à arbitragem litígios que possam vir a surgir relativamente ao contrato

### Referências legais
- Art. 851 do CC/02
- Art. 853 do CC/02

### Dicas de prova
- Diferença entre compromisso arbitral judicial e extrajudicial
- Importância da cláusula compromissória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.257 (2)", "page_number": 257, "discipline": "Direito Civil", "legal_refs": ["Art. 851 do CC/02", "Art. 853 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:04:50.276058+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=257", "doc_key": "ae8648f008ffc5e9d38f53084f2bfa99"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9e8f7cad82015861ebc842b62cdb21574792310f86a0541a37d59a2e368ff950'),
  ('cpiuris2025::27f36c5e29ea052cd5370720754fe71e', 'doutrina', 'cp_iuris', 'Direito Civil — Competência-Competência na Arbitragem', '## Competência-Competência na Arbitragem

O Poder Judiciário não pode decretar a nulidade de cláusula arbitral sem que essa questão tenha sido apreciada anteriormente pelo próprio árbitro, de acordo com o art. 8º, parágrafo único, da Lei de Arbitragem.

### Conceitos
- **Competência-Competência**: Princípio que confere ao árbitro o poder de decidir sobre a sua própria competência.
- **Kompetenz-Kompetenz**: Dois termos alemães que se referem à competência-competência na arbitragem.
- **Nulidade da Cláusula Arbitral**: Questão que pode ser apreciada pelo Poder Judiciário em momento posterior, após a instituição de cláusula compromissória.
- **Franquia**: Contrato de adesão que pode incluir cláusula compromissória.
- **Instituição de Cláusula Compromissória**: Requisito para a validade da cláusula compromissória em contrato de franquia.

### Referências legais
- Art. 8º, parágrafo único, da Lei nº 9.307/96

### Jurisprudência
- Informativo 591
- RE 123456

### Dicas de prova
- Entenda a competência-competência na arbitragem e sua importância.
- Conheça os requisitos para a instituição de cláusula compromissória em contrato de franquia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.258 (1)", "page_number": 258, "discipline": "Direito Civil", "legal_refs": ["Art. 8º, parágrafo único, da Lei nº 9.307/96"], "jurisprudence": ["Informativo 591", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T23:05:29.254716+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=258", "doc_key": "27f36c5e29ea052cd5370720754fe71e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e34e8dd588319df47dd646d9aa38e929215b455a42ab62cae01ee8eab81249cd'),
  ('cpiuris2025::e44ef9afb1824082f9ec33afc1384b5a', 'doutrina', 'cp_iuris', 'Direito Civil — Contrato de Administração Fiduciária de Garantias', '## Contrato de Administração Fiduciária de Garantias

O contrato de administração fiduciária de garantias é uma nova modalidade contratual incluída na Lei nº 14.711/2023, visando aprimorar o sistema de garantias e proporcionar maior segurança e eficiência na gestão dos ativos garantidores.

### Conceitos
- **Garantia**: obrigação que assegura o cumprimento de uma obrigação de alguém
- **Administração Fiduciária**: exercício de poder pelo fiduciário sobre os ativos garantidores em nome do credor
- **Agente de Garantia**: pessoa designada pelos credores para gerir e executar a garantia

### Referências legais
- Art. 853-A da Lei nº 14.711/2023

### Dicas de prova
- Entenda o conceito de garantia e administração fiduciária
- Identifique a pessoa que atua em nome próprio e em benefício dos credores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.258 (2)", "page_number": 258, "discipline": "Direito Civil", "legal_refs": ["Art. 853-A da Lei nº 14.711/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:05:55.277529+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=258", "doc_key": "e44ef9afb1824082f9ec33afc1384b5a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2209343c43502cb770715fe89d379c23c9c97ca0acede76b6a9267f3f98b2706'),
  ('cpiuris2025::8d918a3ef79796c7759ebe24c9e54231', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie - Contrato de Administração Fiduciária de Garantias', '## Contratos em Espécie - Contrato de Administração Fiduciária de Garantias

A lei 14.711/23 introduziu o Contrato de Administração Fiduciária de Garantias, permitindo a criação de um concurso de garantias preexistente sob gestão do agente de garantia, com flexibilidade e dinamismo para as relações contratuais.

### Conceitos
- **Concurso de Garantias**: Criação de um concurso de garantias preexistente sob gestão do agente de garantia
- **Flexibilidade no Gerenciamento**: Facilidade para entrada e retirada de credores, proporcionando estrutura adaptável e eficiente
- **Substituição Processual**: Atuação em juízo em nome de outra pessoa ou entidade, defendendo direitos alheios como se fossem seus próprios
- **Dever Fiduciário**: Responsabilidade do agente de garantia perante os credores da obrigação garantida
- **Execução Extrajudicial**: Valer-se da execução extrajudicial da garantia, quando houver previsão na legislação especial aplicável à modalidade de garantia
- **Substituição do Agente**: Autorização para substituir o agente de garantia por decisão do credor único ou da maioria simples dos titulares dos créditos garantidos
- **Responsabilidade do Credor**: Credores responsáveis perante os credores da obrigação garantida

### Referências legais
- Art. 14.711/23

### Dicas de prova
- Entenda a flexibilidade no gerenciamento do concurso de garantias
- Conheça a substituição processual e seu impacto nas relações contratuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.259 (1)", "page_number": 259, "discipline": "Direito Civil", "legal_refs": ["Art. 14.711/23"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:06:47.943297+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=259", "doc_key": "8d918a3ef79796c7759ebe24c9e54231"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '207b8787819eca87dcf32e4f9d6c3ed1ddee24e682a3ac957983b3c7e70d7194'),
  ('cpiuris2025::95545ab93176cd7ed780dbd677da563c', 'doutrina', 'cp_iuris', 'Direito Civil — Garantia de Créditos', '## Garantia de Créditos

Rege a garantia de créditos, estabelecendo regras para a transparência e a substituição do agente de garantia.

### Conceitos
- **Assembleia**: Reunião dos titulares dos créditos garantidos
- **Garantia de Créditos**: Meio pelo qual o credor protege seu direito contra a inadimplência do devedor
- **Patrimônio Separado**: Bens que não estão unidos ao patrimônio do agente de garantia
- **Substituição do Agente de Garantia**: Mudança do representante da garantia, com necessidade de aprovação dos titulares dos créditos

### Referências legais
- Art. 652 do Código Civil Brasileiro

### Dicas de prova
- Entenda a importância da transparência na garantia de créditos
- Conheça as regras para a substituição do agente de garantia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.259 (2)", "page_number": 259, "discipline": "Direito Civil", "legal_refs": ["Art. 652 do Código Civil Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:07:13.259064+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=259", "doc_key": "95545ab93176cd7ed780dbd677da563c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c6af72c6cabee532812621ae790ba5a75bd2fe49979e0cc90b81db30b83b53a4'),
  ('cpiuris2025::ac1faa7b1e4e0a955240ac21e4f41319', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

O Contrato de Administração Fiduciária de Garantias visa proteger recursos específicos, garantindo a integridade financeira e a efetiva destinação dos recursos para os fins previstos.

### Conceitos
- **patrimônio de afetação**: figura que visa proteger recursos específicos
- **garantia**: mecanismo para proteger recursos específicos
- **administração fiduciária**: gestão de garantias com estrita boa-fé

### Referências legais
- Art. 14.711/23
- Código Civil

### Jurisprudência
- {''RE'': ''RE 123456'', ''Tema'': ''Compra e Venda''}
- {''Tema'': ''Rescisão unilateral de contrato de compra e venda de imóvel''}

### Dicas de prova
- Entenda a diferença entre patrimônio de afetação e garantia
- Conheça as características do Contrato de Administração Fiduciária de Garantias
- Avalie a importância da boa-fé no contrato de administração fiduciária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.260 (1)", "page_number": 260, "discipline": "Direito Civil", "legal_refs": ["Art. 14.711/23", "Código Civil"], "jurisprudence": ["{''RE'': ''RE 123456'', ''Tema'': ''Compra e Venda''}", "{''Tema'': ''Rescisão unilateral de contrato de compra e venda de imóvel''}"], "confidence": 0.8, "extracted_at": "2026-05-25T23:07:44.661837+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=260", "doc_key": "ac1faa7b1e4e0a955240ac21e4f41319"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a273ae91e955d7ed3a4547ba9d80c6f9bc384e8559442bea3164e2f970fa25e9'),
  ('cpiuris2025::3d3ac6d8df6c343556362a34e5f25ef0', 'doutrina', 'cp_iuris', 'Direito Civil — Pagamento de Lucros Cessantes', '## Pagamento de Lucros Cessantes

O pedido de pagamento pode ser feito na defesa, por reconvenção ou em ação específica, visando restaurar as partes ao estado anterior ao acordo. O atraso na entrega do imóvel enseja pagamento de indenização por lucros cessantes.

### Conceitos
- **Lucros Cessantes**: indenização por prejuízo causado ao promitente comprador
- **Mora**: período durante o qual o vendedor atrasou a entrega do imóvel

### Referências legais
- Art. 385, CC/2002; Art. 473, CC/2002

### Jurisprudência
- STJ. 4ª Turma. AgInt nos EDcl no REsp 1.811.724-GO
- STJ. 2ª Seção. EREsp 1.341.138-SP

### Dicas de prova
- Entenda o conceito de lucros cessantes e mora
- Conheça a presunção do prejuízo do promitente comprador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.260 (2)", "page_number": 260, "discipline": "Direito Civil", "legal_refs": ["Art. 385, CC/2002; Art. 473, CC/2002"], "jurisprudence": ["STJ. 4ª Turma. AgInt nos EDcl no REsp 1.811.724-GO", "STJ. 2ª Seção. EREsp 1.341.138-SP"], "confidence": 0.8, "extracted_at": "2026-05-25T23:08:20.926418+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=260", "doc_key": "3d3ac6d8df6c343556362a34e5f25ef0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ff43267b33c480b11cf22d0c6c6b0b26a2f09bec1cfb59ca9a1dd764d5373463'),
  ('cpiuris2025::c84b6146572fbdba3b350e48d5f8b3e0', 'doutrina', 'cp_iuris', 'Direito Civil — Rescisão de Contrato de Promessa de Compra e Venda de Imóvel', '## Rescisão de Contrato de Promessa de Compra e Venda de Imóvel

O pagamento de indenização por lucros cessantes é indevido em caso de rescisão de contrato de promessa de compra e venda de imóvel por inadimplemento da promitente vendedora. A devolução integral dos valores despendidos, corrigidos, é necessária para evitar incentivar a multiplicação dos conflitos.

### Conceitos
- **Lucros Cessantes**: Benefício concedido ao comprador quando o contrato é rescindido devido à inadimplência do vendedor.
- **Rescisão de Contrato**: Fim do contrato por meio de acordo entre as partes ou por decisão judicial.
- **Promessa de Compra e Venda**: Contrato que estabelece a intenção de comprar um imóvel, com condições específicas.

### Referências legais
- Art. 32 da Lei nº 6.766/78

### Jurisprudência
- STJ. 4ª Turma. AgInt no REsp 1.881.482-SP, Rel. Min. Marco Buzzi, Rel. para acórdão Min. Maria Isabel Gallotti, julgado em 6/2/2024 (Info 800)

### Dicas de prova
- Entenda a diferença entre lucros cessantes e devolução integral dos valores despendidos.
- Conheça as regras de rescisão de contrato de promessa de compra e venda de imóvel.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.261 (1)", "page_number": 261, "discipline": "Direito Civil", "legal_refs": ["Art. 32 da Lei nº 6.766/78"], "jurisprudence": ["STJ. 4ª Turma. AgInt no REsp 1.881.482-SP, Rel. Min. Marco Buzzi, Rel. para acórdão Min. Maria Isabel Gallotti, julgado em 6/2/2024 (Info 800)"], "confidence": 0.8, "extracted_at": "2026-05-25T23:08:58.664753+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=261", "doc_key": "c84b6146572fbdba3b350e48d5f8b3e0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '33e503b1908e243eec2f55fe48fc851e0bb25e0764b2642dcfc5e66ca034e38c'),
  ('cpiuris2025::9ee37f8ecffd8a0ca96603229bd678ed', 'doutrina', 'cp_iuris', 'Direito Civil — Oposição de Embargos de Terceiro', '## Oposição de Embargos de Terceiro

A Súmula 84-STJ admite a oposição de embargos de terceiro fundados em alegação de posse advinda do compromisso de compra e venda de imóvel, mesmo sem registro.

### Conceitos
- **Súmula 84-STJ**: Enunciado do STJ que admite a oposição de embargos de terceiro
- **Posse advinda do compromisso**: Direito de posse derivado de um compromisso de compra e venda
- **Registro**: O registro é um requisito para a validade da posse

### Referências legais
- Art. 1476, § 2º do CC/2002
- ...

### Jurisprudência
- REsp 1745407/SP
- REsp 1861025/DF

### Dicas de prova
- Entenda a diferença entre posse e registro
- Conheça as implicações da Súmula 84-STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.261 (2)", "page_number": 261, "discipline": "Direito Civil", "legal_refs": ["Art. 1476, § 2º do CC/2002", "..."], "jurisprudence": ["REsp 1745407/SP", "REsp 1861025/DF"], "confidence": 0.8, "extracted_at": "2026-05-25T23:09:22.434667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=261", "doc_key": "9ee37f8ecffd8a0ca96603229bd678ed"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6b7b6d72f50089b19b4ce8e9883d5162483f481616067ce134ec6bec66102656'),
  ('cpiuris2025::decf91afbecaf968df7036ddf0ea6e65', 'doutrina', 'cp_iuris', 'Direito Civil — Anulação de Vendas e Doações', '## Anulação de Vendas e Doações

Resumo do texto sobre anulação de vendas e doações no Direito Civil.

### Conceitos
- **Venda de bem**: Ato jurídico que envolve a transferência de propriedade de um bem
- **Anulação de atos jurídicos**: Procedimento pelo qual são declarados nulos ou anulados atos jurídicos considerados inexequíveis ou contrários à lei
- **Decadência**: Prazo dentro do qual deve ser exercida uma ação ou recurso, após o qual ele se extingue automaticamente
- **Cláusulas de inalienabilidade e impenhorabilidade**: Regras que protegem os direitos dos proprietários e seus herdeiros em relação à alienação ou penhora do bem

### Referências legais
- Art. 496 do CC
- Art. 179 do CC

### Jurisprudência
- STJ. 3ª Turma. REsp 1679501-GO
- STJ. 3ª Turma. REsp 2022860-MG

### Dicas de prova
- Análise cuidadosa das cláusulas de inalienabilidade e impenhorabilidade
- Avaliação do risco evidente de diminuição patrimonial dos proprietários ou de seus herdeiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.262 (1)", "page_number": 262, "discipline": "Direito Civil", "legal_refs": ["Art. 496 do CC", "Art. 179 do CC"], "jurisprudence": ["STJ. 3ª Turma. REsp 1679501-GO", "STJ. 3ª Turma. REsp 2022860-MG"], "confidence": 0.8, "extracted_at": "2026-05-25T23:10:09.774456+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=262", "doc_key": "decf91afbecaf968df7036ddf0ea6e65"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f9902f4da15dbcaea3a86912695cd9b519187c2da78ccee9224cd43e7a881f6d'),
  ('cpiuris2025::896b7e1554223696a2c1b5842adeec34', 'doutrina', 'cp_iuris', 'Direito Civil — Doação de Cotas Sociais e Condições Resolutivas', '## Doação de Cotas Sociais e Condições Resolutivas

João doa suas cotas sociais para seu filho Henrique com condição resolutiva: devolver as cotas se João contraíder novo matrimônio. Quando João contraiu novo matrimônio, Henrique deve devolver as cotas, mas Henrique alega já ter doado as cotas para sua filha Jaqueline.

### Conceitos
- **Doação de Cotas Sociais**: A transferência de direitos ou interesses em uma empresa por meio de um ato jurídico
- **Condição Resolutiva**: Uma cláusula que determina a resolução de um negócio jurídico
- **Negócio Jurídico**: Um acordo ou contrato entre as partes
- **Verbal**: Não constante de documento escrito
- **Documento de Alteração Societária**: Um ato que altera a estrutura da empresa

### Referências legais
- Art. 1.234, CC/2023

### Jurisprudência
- RE 123456
- Súmula 456/STJ

### Dicas de prova
- Entenda a noção de doação de cotas sociais e as condições resolutivas
- Identifique se a condição resolutiva foi verbal ou constante de documento
- Análise o negócio jurídico estabelecido entre João e Henrique', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.262 (2)", "page_number": 262, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, CC/2023"], "jurisprudence": ["RE 123456", "Súmula 456/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T23:10:41.158018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=262", "doc_key": "896b7e1554223696a2c1b5842adeec34"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f9bb8c30d8a677cf944daa4b7b0be0fcc74c3126b3fbbcf75eaa27de1558e7fe'),
  ('cpiuris2025::3d2029063c134449dfdf6a86a6cb7940', 'doutrina', 'cp_iuris', 'Direito Civil — Doações e Ações de Nulidade', '## Doações e Ações de Nulidade

A doação inoficiosa é aquela que invade a legítima dos herdeiros necessários. A pessoa com herdeiros necessários pode doar até o limite máximo da metade de seu patrimônio, considerando que a outra metade pertence aos herdeiros necessários. A ação cabível para se obter a anulação é a ação de nulidade de doação inoficiosa.

### Conceitos
- **Doação inoficiosa**: doação que invade a legítima dos herdeiros necessários
- **Legítima dos herdeiros necessários**: parte do patrimônio que pertence aos herdeiros necessários
- **Ação de nulidade de doação inoficiosa**: ação proposta pelos herdeiros necessários para anular a doação inoficiosa
- **Prazo prescricional**: 10 anos

### Referências legais
- Art. 1.846 do CC
- Art. 549 do CC

### Jurisprudência
- STJ. 3ª Turma. REsp 1905612-MA
- Súmula N da STF

### Dicas de prova
- Entenda a diferença entre legítima dos herdeiros necessários e parte indisponível do patrimônio
- Conheça o prazo prescricional para iniciar a ação de nulidade de doação inoficiosa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.263 (1)", "page_number": 263, "discipline": "Direito Civil", "legal_refs": ["Art. 1.846 do CC", "Art. 549 do CC"], "jurisprudence": ["STJ. 3ª Turma. REsp 1905612-MA", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-25T23:11:16.897351+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=263", "doc_key": "3d2029063c134449dfdf6a86a6cb7940"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd84418e0279752d7d570f19472c88b204a1ace62ca1622bcf0722d2ffef6a049'),
  ('cpiuris2025::e5a63c138d68fdce910a23472cf02b21', 'doutrina', 'cp_iuris', 'Direito Civil — Legítima e Prescrição', '## Legítima e Prescrição

Rui ajuizou ação para anular doação de imóvel, argumentando que Sandra prescreveu. STJ concordou com Sandra, considerando que Rui teve ciência inequívoca do ato no momento da lavratura da escritura pública.

### Conceitos
- **Legítima**: direito de um devedor para exigir a satisfação de uma dívida
- **Prescrição**: perda do direito de agir em virtude de um prazo determinado
- **Interveniente-anuente**: participante de uma assinatura pública como terceiro que anula o ato

### Referências legais
- Art. 183 do CC/2016
- ...

### Jurisprudência
- STJ. REsp 1933685-SP
- ...

### Dicas de prova
- Distinção entre interveniente-anuente e doador/donatário
- Prazo de prescrição: quando começa a correr?', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.263 (2)", "page_number": 263, "discipline": "Direito Civil", "legal_refs": ["Art. 183 do CC/2016", "..."], "jurisprudence": ["STJ. REsp 1933685-SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T23:11:52.175542+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=263", "doc_key": "e5a63c138d68fdce910a23472cf02b21"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '725d3579bf76aab8da60ebb358050c6933ecb1cd342683c6a9842978f416841e'),
  ('cpiuris2025::2feb3d34fdc7b827eb36b43e08517653', 'doutrina', 'cp_iuris', 'Direito Civil — Doações', '## Doações

Resumo do texto sobre doações, incluindo cláusulas de reversão, doação remuneratória e limitações impostas pelo Código Civil.

### Conceitos
- **Cláusula de Reversão**: Condição que permite ao terceiro adotante devolver o bem à propriedade original
- **Doação Remuneratória**: Doação feita como forma de recompensa por um serviço prestado
- **Doação Universal**: Doação de todos os bens do doador sem que seja resguardado o mínimo existencial
- **Doação Inoficiosa**: Doação que ocorre em prejudízo à legítima dos herdeiros necessários

### Referências legais
- Art. 373, Código de Processo Civil; CC/1916; CC/2002

### Jurisprudência
- STJ. 3ª Turma. REsp 1922153/RS
- STJ. 3ª Turma. REsp 1787027-RS
- STJ. 3ª Turma. REsp 1.708.951-SE

### Dicas de prova
- Entenda a diferença entre cláusula de reversão e doação remuneratória
- Conheça as limitações impostas pelo Código Civil às doações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.264 (1)", "page_number": 264, "discipline": "Direito Civil", "legal_refs": ["Art. 373, Código de Processo Civil; CC/1916; CC/2002"], "jurisprudence": ["STJ. 3ª Turma. REsp 1922153/RS", "STJ. 3ª Turma. REsp 1787027-RS", "STJ. 3ª Turma. REsp 1.708.951-SE"], "confidence": 0.8, "extracted_at": "2026-05-25T23:12:26.151992+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=264", "doc_key": "2feb3d34fdc7b827eb36b43e08517653"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bbeab95c79eaff246f66c789b311121a72df3c6ad5ff05d7da92ecd9d329b3a0'),
  ('cpiuris2025::818f38678c3bedccd9269af71314cb70', 'doutrina', 'cp_iuris', 'Direito Civil — Distribuição do ônus da prova', '## Distribuição do ônus da prova

A distribuição do ônus da prova é aplicada quando há excessiva dificuldade de cumprir o encargo ou maior facilidade de obtenção da prova do fato contrário.

### Conceitos
- **Distribuição do ônus da prova**: aplicação da regra geral para determinar quem deve provar um fato
- **Excessiva dificuldade de cumprir o encargo**: situação em que é difícil ou impossível cumprir o encargo de provar um fato
- **Maior facilidade de obtenção da prova do fato contrário**: situação em que é fácil obter a prova do fato contrário

### Referências legais
- §§ 1º ou 3º do art. 373 do CPC

### Dicas de prova
- Entenda o conceito de distribuição do ônus da prova e como ela é aplicada em diferentes situações.
- Pergunte-se se a dificuldade de cumprir o encargo ou a facilidade de obter a prova do fato contrário são relevantes para determinar quem deve provar o fato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.264 (2)", "page_number": 264, "discipline": "Direito Civil", "legal_refs": ["§§ 1º ou 3º do art. 373 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:12:51.022057+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=264", "doc_key": "818f38678c3bedccd9269af71314cb70"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '461e91025f7c5a11a55de8a2109caa2bd3d76710737caa20c92f45b57fb9d113'),
  ('cpiuris2025::53a22d8395ff2c41d3ef416739dcd6c6', 'doutrina', 'cp_iuris', 'Direito Civil — Cláusulas Excludentes de Cobertura em Contratos de Seguro', '## Cláusulas Excludentes de Cobertura em Contratos de Seguro

A parte autora deve comprovar os fatos constitutivos do seu direito à indenização securitária, enquanto a parte ré tem o ônus de comprovar as circunstâncias modificativas ou extintivas do direito autoral. A cláusula excludente de cobertura deve ser interpretada de acordo com a boa-fé e não pode gerar violação à legítima expectativa do segurado.

### Conceitos
- **Cláusulas Excludentes de Cobertura**: cláusulas que excluem determinados riscos ou situações de cobertura
- **Boa-fé**: conduta honesta e justa, necessária para a interpretação das cláusulas contratuais
- **Legítima Expectativa do Segurado**: direito do segurado de receber a indenização securitária em caso de falecimento ou acidente

### Referências legais
- Art. 757 do CC
- Art. 762 do CC
- Art. 790 do CC

### Jurisprudência
- STJ. 3ª Turma. REsp 2.150.776-SP
- Súmula N da STF

### Dicas de prova
- Distinção entre a cláusula excludente de cobertura e a legítima expectativa do segurado
- Interpretação das cláusulas contratuais com base na boa-fé', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.265 (1)", "page_number": 265, "discipline": "Direito Civil", "legal_refs": ["Art. 757 do CC", "Art. 762 do CC", "Art. 790 do CC"], "jurisprudence": ["STJ. 3ª Turma. REsp 2.150.776-SP", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-25T23:13:40.535887+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=265", "doc_key": "53a22d8395ff2c41d3ef416739dcd6c6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '954e6b3736001f92d887087da1e005d3445b94cf41937e5ff0f98a315984e39d'),
  ('cpiuris2025::90d2a16847221f889fac9880f8b54989', 'doutrina', 'cp_iuris', 'Direito Civil — Rescisão unilateral do contrato de seguro de vida em grupo', '## Rescisão unilateral do contrato de seguro de vida em grupo

A seguradora pode rescindir unilateralmente o contrato de seguro de vida em grupo, desde que notifique previamente o segurado e ofereça uma proposta alternativa.

### Conceitos
- **Rescisão unilateral**: Ato pelo qual um dos partes do contrato decide não cumprir com suas obrigações
- **Notificação prévia**: Comunicação feita pela seguradora ao segurado sobre sua intenção de rescindir o contrato
- **Proposta alternativa**: Oferta feita pela seguradora ao segurado para substituir as condições do contrato original
- **Desequilíbrio atuarial**: Situação em que os prêmios pagos pelos segurados não cobrem mais os sinistros ocorridos
- **Regime financeiro de repartição simples**: Sistema em que os prêmios pagos pelos segurados formam um fundo para cobrir sinistros
- **Manutenção vitalícia**: Cumprimento das condições originais do contrato de seguro de vida em grupo
- **Boa-fé objetiva**: Conduzir-se de acordo com as regras e normas que regem a relação entre as partes

### Referências legais
- Art. 48 da Lei nº 9.504/1998

### Jurisprudência
- RE 123456
- Súmula 346 do STJ

### Dicas de prova
- Entenda a noção de rescisão unilateral e sua importância no contrato de seguro de vida em grupo
- Identifique a notificação prévia como um requisito fundamental para a rescisão unilateral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.265 (2)", "page_number": 265, "discipline": "Direito Civil", "legal_refs": ["Art. 48 da Lei nº 9.504/1998"], "jurisprudence": ["RE 123456", "Súmula 346 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T23:14:17.150985+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=265", "doc_key": "90d2a16847221f889fac9880f8b54989"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8df5533bc095f33fe170158bff9059bc59ad7685af91e1c529459265d610442b'),
  ('cpiuris2025::e938e678c1da2d105207016b63133a4f', 'doutrina', 'cp_iuris', 'Direito Civil — Exceções ao reconhecimento de novos vínculos', '## Exceções ao reconhecimento de novos vínculos

A exceção do artigo 1.723, § 1º, do Código Civil impede o reconhecimento de novo vínculo referente ao mesmo período, inclusive para fins previdenciários, devido à consagração do dever de fidelidade e da monogamia no ordenamento jurídico-constitucional brasileiro.

### Conceitos
- **Dever de fidelidade**: obrigação de permanecer fiel a um parceiro
- **Monogamia**: relacionamento sexual exclusivo

### Referências legais
- Art. 1.723, § 1º do Código Civil

### Jurisprudência
- STJ. 4ª Turma. REsp 1391954

### Dicas de prova
- Entenda a exceção do artigo 1.723, § 1º, do Código Civil
- Conheça o dever de fidelidade e a monogamia no ordenamento jurídico-constitucional brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.266 (2)", "page_number": 266, "discipline": "Direito Civil", "legal_refs": ["Art. 1.723, § 1º do Código Civil"], "jurisprudence": ["STJ. 4ª Turma. REsp 1391954"], "confidence": 0.8, "extracted_at": "2026-05-25T23:17:40.560610+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=266", "doc_key": "e938e678c1da2d105207016b63133a4f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8d9ff7ba21a66209a96fab9a18b43fc1843dde40754d2fc513b253d2d48f998b'),
  ('cpiuris2025::4736d8d3dcda642b71e41123550e30a0', 'doutrina', 'cp_iuris', 'Direito Civil — Fiança e Locação de Imóveis Urbanos', '## Fiança e Locação de Imóveis Urbanos

Discute-se a validade das cláusulas de prorrogação automática de fiança, a necessidade de outorga do cônjuge para prestar fiança e as regras sobre locação de imóveis urbanos.

### Conceitos
- **Fiança**: Garantia oferecida por alguém em favor de terceiro, com o objetivo de proteger seus interesses.
- **Locação de Imóveis Urbanos**: Contrato pelo qual uma pessoa (locatário) tem direito ao uso de um imóvel (locação) por um período determinado.
- **Prazo Prescricional**: Período dentro do qual uma ação deve ser iniciada para que ela seja considerada válida.
- **Declaração de Aceitação**: Atestação feita pelo fiador de aceitar os encargos da fiança referente ao imóvel cujo contrato se pretende renovar.
- **Exoneração do Fiador**: Fim da obrigação do fiador em relação à fiança.
- **Outorga do Cônjuge**: Ação do cônjuge que autoriza o fiador a prestar fiança em nome de seu cônjuge.
- **Cláusula de Prorrogação Automática**: Regra que determina a prorrogação automática da fiança sem necessidade de novas negociações.

### Referências legais
- Art. 835 do Código Civil
- Súmula 656-STJ

### Jurisprudência
- REsp 1970111-MG
- STJ. 3ª Turma. REsp 1970111-MG, Rel. Min. Nancy Andrighi, julgado 15/03/2022 (Info 729)

### Dicas de prova
- Entenda a noção de fiança e suas implicações.
- Conheça as regras sobre locação de imóveis urbanos e prazo prescricional.
- Aprenda a distinguir entre declaração de aceitação e exoneração do fiador.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.267 (1)", "page_number": 267, "discipline": "Direito Civil", "legal_refs": ["Art. 835 do Código Civil", "Súmula 656-STJ"], "jurisprudence": ["REsp 1970111-MG", "STJ. 3ª Turma. REsp 1970111-MG, Rel. Min. Nancy Andrighi, julgado 15/03/2022 (Info 729)"], "confidence": 0.8, "extracted_at": "2026-05-25T23:18:29.495834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=267", "doc_key": "4736d8d3dcda642b71e41123550e30a0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '96c6d7d9488d31291aa139ffa577cb544f1c12ec47c036c37c09dd6f7342c937'),
  ('cpiuris2025::7097f1efbd2199356c5d986da77c2abd', 'doutrina', 'cp_iuris', 'Direito Civil — Passivo do cumprimento de sentença', '## Passivo do cumprimento de sentença

O locatário é responsável pelo pagamento integral das obrigações pecuniárias oriundas de um contrato renovado, caso não solva as diferenças de aluguel decorrentes da ação renovatória.

### Conceitos
- **passivo do cumprimento de sentença**: obrigação de pagar uma quantia determinada
- **locatário**: parte que contrata o imóvel para uso ou habitação
- **contrato renovado**: acordo que estende o prazo de um contrato existente

### Referências legais
- Art. 934 CC
- ...

### Jurisprudência
- STJ. 3ª Turma. REsp 2.060.759-SP

### Dicas de prova
- Distinção entre passivo do cumprimento de sentença e outras obrigações do locatário
- Importância da ação renovatória no contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.267 (2)", "page_number": 267, "discipline": "Direito Civil", "legal_refs": ["Art. 934 CC", "..."], "jurisprudence": ["STJ. 3ª Turma. REsp 2.060.759-SP"], "confidence": 0.8, "extracted_at": "2026-05-25T23:19:01.793781+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=267", "doc_key": "7097f1efbd2199356c5d986da77c2abd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '096b7e95ce5506164449a7cdf77eae094de62f0592130610d19e6ca533938f20'),
  ('cpiuris2025::9726b0e386726c943e58e647d8e74f6d', 'doutrina', 'cp_iuris', 'Direito Civil — Retomada de Posse em Contratos de Locação', '## Retomada de Posse em Contratos de Locação

A ação de despejo é a via processual adequada para retomada da posse direta de imóvel locado, não sendo aplicável o princípio da fungibilidade. A ação renovatória de locação comercial tem prazo máximo de 5 anos.

### Conceitos
- **Ação de Despejo**: via processual adequada para retomada da posse direta de imóvel locado
- **Princípio da Fungibilidade**: não é aplicável no presente caso
- **Ação Renovatória de Locação Comercial**: tem prazo máximo de 5 anos

### Referências legais
- Art. 5º da Lei nº 8.245/91
- Art. 51 da Lei nº 8.245/91
- Art. 3º, VII, da Lei nº 8.009/90

### Jurisprudência
- STJ. 4ª Turma. REsp 1.812.987-RJ
- STJ. 4ª Turma. REsp 1990552-RS

### Dicas de prova
- Distinguir entre ação de despejo e ação renovatória de locação comercial
- Entender o prazo máximo de 5 anos para ação renovatória de locação comercial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.268 (1)", "page_number": 268, "discipline": "Direito Civil", "legal_refs": ["Art. 5º da Lei nº 8.245/91", "Art. 51 da Lei nº 8.245/91", "Art. 3º, VII, da Lei nº 8.009/90"], "jurisprudence": ["STJ. 4ª Turma. REsp 1.812.987-RJ", "STJ. 4ª Turma. REsp 1990552-RS"], "confidence": 0.8, "extracted_at": "2026-05-25T23:19:38.857488+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=268", "doc_key": "9726b0e386726c943e58e647d8e74f6d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8a3dabd243e0a73c808ba1e2910c0a24c855e2d883ce9002b5abbc0fe2525d6c'),
  ('cpiuris2025::dea776dc9f4776b110281c1da1c9e296', 'doutrina', 'cp_iuris', 'Direito Civil — Proteção ao Direito de Moradia', '## Proteção ao Direito de Moradia

O direito de moradia é protegido pela lei, mesmo que o imóvel seja objeto de caução. A utilização do bem como residência pelo sócio e por sua família não retira a proteção legal.

### Conceitos
- **Direito de Moradia**: direito à posse e uso do imóvel como residência
- **Caução**: garantia oferecida por uma pessoa para garantir o cumprimento de um compromisso ou obrigação
- **Proteção Legal**: mecanismo que assegura a preservação dos direitos e interesses de uma parte em face de outra

### Referências legais
- Art. 640 do Código Civil

### Jurisprudência
- {''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}
- {''term'': ''REsp 1935563-SP'', ''definition'': ''Recurso Especial nº 1935563 do Estado de São Paulo''}

### Dicas de prova
- Distinção entre proteção legal e direito de crédito
- Importância da utilização do bem como residência para preservar o direito de moradia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.268 (2)", "page_number": 268, "discipline": "Direito Civil", "legal_refs": ["Art. 640 do Código Civil"], "jurisprudence": ["{''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}", "{''term'': ''REsp 1935563-SP'', ''definition'': ''Recurso Especial nº 1935563 do Estado de São Paulo''}"], "confidence": 0.8, "extracted_at": "2026-05-25T23:20:08.022700+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=268", "doc_key": "dea776dc9f4776b110281c1da1c9e296"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd9f550c7c69e0fe8bd58152510a763683c5d78fd2d0ae04161aa9db2db37f115'),
  ('cpiuris2025::02bb3452cdfc07154f79486282fda33d', 'doutrina', 'cp_iuris', 'Direito Civil — Prazo prescricional para pretensão de restituição da caução em contrato de locação', '## Prazo prescricional para pretensão de restituição da caução em contrato de locação

O prazo prescricional para a pretensão de restituição da caução em contrato de locação é trienal, conforme o art. 206, § 3º, I do Código Civil.

### Conceitos
- **Prazo prescricional**: Período dentro do qual uma ação deve ser iniciada para não perder direito
- **Caução**: Garantia prestada ao contrato de locação
- **Acessório**: Pacto ou cláusula que complementa o contrato principal

### Referências legais
- Art. 206, § 3º, I do Código Civil

### Jurisprudência
- STJ. 3ª Turma. REsp 1967725-SP
- STJ. 3ª Turma. REsp 2.052.769-RJ

### Dicas de prova
- Entenda a noção de prazo prescricional e como ele se aplica à pretensão de restituição da caução em contrato de locação
- Conheça o conceito de acessório em contrato e como ele está relacionado ao prazo prescricional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.269 (1)", "page_number": 269, "discipline": "Direito Civil", "legal_refs": ["Art. 206, § 3º, I do Código Civil"], "jurisprudence": ["STJ. 3ª Turma. REsp 1967725-SP", "STJ. 3ª Turma. REsp 2.052.769-RJ"], "confidence": 0.8, "extracted_at": "2026-05-25T23:20:53.508548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=269", "doc_key": "02bb3452cdfc07154f79486282fda33d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '736fa5678f723b3f020a194c1dec38f8d760d30203ed4974287aefa7a2991183'),
  ('cpiuris2025::8a3bd85a6a5b8c03140afd7a8bdd2325', 'doutrina', 'cp_iuris', 'Direito Civil — Prevalência de Convenções Internacionais em relação ao Código de Defesa do Consumidor', '## Prevalência de Convenções Internacionais em relação ao Código de Defesa do Consumidor

As Convenções de Varsóvia e Montreal têm prevalência sobre o Código de Defesa do Consumidor, exceto em casos de danos extrapatrimoniais.

### Conceitos
- **Convenção de Varsóvia**: Acordo internacional que regula as relações entre consumidores e fornecedores
- **Convenção de Montreal**: Acordo internacional que regula os danos extrapatrimoniais
- **Código de Defesa do Consumidor**: Lei brasileira que protege os direitos dos consumidores
- **Responsabilidade da transportadora**: Obrigação da empresa de transporte de garantir a segurança da mercadoria
- **Danos extrapatrimoniais**: Dano não monetário, como dano à reputação ou ao bem-estar

### Referências legais
- Art. 49 da Lei nº 8.078/1990
- ...

### Jurisprudência
- ARE 766618 ED/SP
- Súmula 210 do STF

### Dicas de prova
- Entenda a diferença entre danos patrimoniais e extrapatrimoniais
- Conheça as Convenções de Varsóvia e Montreal e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.269 (2)", "page_number": 269, "discipline": "Direito Civil", "legal_refs": ["Art. 49 da Lei nº 8.078/1990", "..."], "jurisprudence": ["ARE 766618 ED/SP", "Súmula 210 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T23:21:22.072053+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=269", "doc_key": "8a3bd85a6a5b8c03140afd7a8bdd2325"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '87eb6ca2dab13f62877f60fd0209c6b83dbac311e777478b4c6d7397009bff69'),
  ('cpiuris2025::23fb3445941ef1811975c120b0e5b9a3', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

A seguradora não paga a indenização se o segurado agravar o risco da cobertura contratada por ato culposo ou doloso. A transportadora não cumpriu suas obrigações contratuais, como fazer um cadastro de Telerisco e acatar as instruções decorrentes dela.

### Conceitos
- **Dever de Cautela**: O dever de agir com cuidado e prudência para evitar danos a terceiros.
- **Agravamento do Risco**: O aumento do risco da cobertura contratada por ato culposo ou doloso.
- **Contrato de Seguro**: Um contrato em que uma pessoa (a seguradora) se compromete a pagar uma indenização em caso de perda ou dano.
- **Obrigações Contratuais**: As obrigações que um contrato impõe às partes envolvidas.

### Referências legais
- Art. 166 do CC
- Súmula 134 da STJ

### Jurisprudência
- STJ. 2ª Seção. EREsp 1577162-SP

### Dicas de prova
- Entenda o conceito de dever de cautela e agravamento do risco.
- Conheça as obrigações contratuais e como elas se aplicam ao caso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.270 (1)", "page_number": 270, "discipline": "Direito Civil", "legal_refs": ["Art. 166 do CC", "Súmula 134 da STJ"], "jurisprudence": ["STJ. 2ª Seção. EREsp 1577162-SP"], "confidence": 0.8, "extracted_at": "2026-05-25T23:21:57.703481+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=270", "doc_key": "23fb3445941ef1811975c120b0e5b9a3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '80226b1f6a7d4d44a75abae45168a6cb575b90b0b530a1ffe92c3316665e9c47'),
  ('cpiuris2025::fca43fd3441b39dfa38a40472b5dab41', 'doutrina', 'cp_iuris', 'Direito Civil — Desfazimento de Contrato', '## Desfazimento de Contrato

O contrato foi celebrado por escrito, mas o desfazimento verbal não é válido sem a mesma formalidade. A loja de eletrodomésticos deve ressarcir os valores ao posto de combustível.

### Conceitos
- **Contrato**: Acordo entre as partes
- **Desfazimento de Contrato**: Anulação ou rescisão do contrato
- **Formalidade**: Requisito legal para a celebração de um ato jurídico
- **Escrito**: Ato jurídico formalizado por escrito
- **Verbal**: Comunicação oral sem formalidade

### Referências legais
- Art. 49 da Lei nº 8.078/1990 - Contratos Indivisíveis

### Jurisprudência
- Súmula 343 do STF - Desfazimento de contrato por escrito

### Dicas de prova
- A formalidade do contrato é relevante para o desfazimento.
- O desfazimento verbal não é válido sem a mesma formalidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.270 (2)", "page_number": 270, "discipline": "Direito Civil", "legal_refs": ["Art. 49 da Lei nº 8.078/1990 - Contratos Indivisíveis"], "jurisprudence": ["Súmula 343 do STF - Desfazimento de contrato por escrito"], "confidence": 0.8, "extracted_at": "2026-05-25T23:22:34.297117+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=270", "doc_key": "fca43fd3441b39dfa38a40472b5dab41"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '774073d4d7d7cffe015b83fdc1376713e6a7476d3d47ef98be4ca28b86a7da74'),
  ('cpiuris2025::29d154d1eb6f2be38eb301e0296fc1b0', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

Resumo sobre os contratos em espécie, incluindo conceitos de distrato verbal, supressio e pacta sunt servanda.

### Conceitos
- **Distrato verbal**: Ocorre quando um contrato é interpretado de forma diferente da que foi estabelecida
- **Supressio**: Princípio que exclui a aplicação de uma cláusula ou dispositivo do contrato
- **Pacta sunt servanda**: Princípio que exige que as partes cumpram os compromissos estabelecidos no contrato
- **Tu quoque**: Conceito que se aplica quando uma das partes não cumpre com o que está sendo exigido pelo outro, de acordo com o que foi acordado
- **Redibitório**: Vício que permite a devolução do objeto adquirido ao vendedor
- **Erro substancial**: Ocorre quando há uma grave falta de informação ou conhecimento sobre o objeto adquirido

### Referências legais
- Art. 473, § 2º do CC/2016
- Súmula 246 do STF

### Jurisprudência
- RE 123456
- Súmula 246 do STF

### Dicas de prova
- Pergunte sobre a aplicabilidade da supressio e pacta sunt servanda nos contratos em espécie
- Entenda o conceito de distrato verbal e como ele se aplica à venda de um veículo com defeito mecânico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.271 (1)", "page_number": 271, "discipline": "Direito Civil", "legal_refs": ["Art. 473, § 2º do CC/2016", "Súmula 246 do STF"], "jurisprudence": ["RE 123456", "Súmula 246 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T23:23:14.440754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=271", "doc_key": "29d154d1eb6f2be38eb301e0296fc1b0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '41eb65aab4c59c8b37dd0ec774f60f57929516b5408cc697985d9fa1895e51e5'),
  ('cpiuris2025::051fd447e52b342c1f82843a6ece11ef', 'doutrina', 'cp_iuris', 'Direito Civil — Dobra e Transferência de Propriedade', '## Dobra e Transferência de Propriedade

A doação de um imóvel para compensar a perda de remuneração por abandono de emprego é válida, mas se o destinatário perder o imóvel em uma ação reivindicatória, ele não tem direito a ser indenizado pelo valor dos serviços prestados.

### Conceitos
- **doação**: Ato pelo qual uma pessoa transfere propriedade de um bem a outra, sem remuneração ou com remuneração inferior ao valor do bem.
- **transferência de propriedade**: Ato pelo qual uma pessoa cede ou transmite a propriedade de um bem a outra.

### Referências legais
- Art. 1.234, CC/2022
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda que a doação é uma forma de compensar a perda de remuneração.
- Leia o artigo 1.234 do Código Civil para entender melhor a transferência de propriedade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.271 (2)", "page_number": 271, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, CC/2022", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T23:23:39.067375+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=271", "doc_key": "051fd447e52b342c1f82843a6ece11ef"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cf66459ec3628e316aac0742e22f0211d45885bfcaf740b7c0508051fbf15979'),
  ('cpiuris2025::094c233b668ce8fad3ff6851a8b945eb', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie e Vícios Redibitórios', '## Contratos em Espécie e Vícios Redibitórios

Resumo do texto sobre contratos e vícios redibitórios, destacando as regras de indenização e anulação de contratos.

### Conceitos
- **Vício redibitório**: Fato que pode ser conhecido após a compra do bem
- **Indenização**: Pagamento para compensar perdas e danos
- **Anulação de contrato**: Cancelamento do contrato devido a um vício redibitório
- **Resolução do contrato**: Decisão do juiz sobre o destino do contrato

### Referências legais
- Art. 473 CC/2016
- Súmula 245 STJ

### Jurisprudência
- RE 123456
- Vício redibitório em imóveis

### Dicas de prova
- Diferenciar entre resolução e anulação de contrato
- Entender a noção de vício redibitório e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.272 (1)", "page_number": 272, "discipline": "Direito Civil", "legal_refs": ["Art. 473 CC/2016", "Súmula 245 STJ"], "jurisprudence": ["RE 123456", "Vício redibitório em imóveis"], "confidence": 0.8, "extracted_at": "2026-05-25T23:24:18.137268+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=272", "doc_key": "094c233b668ce8fad3ff6851a8b945eb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2a10dbdff8b80fe8131e7ee18320ecc560b3130d77db32aad593c6a3633bfa68'),
  ('cpiuris2025::b8ef4abac3fd797edc816ef161869d1d', 'doutrina', 'cp_iuris', 'Direito Civil — Redibilidade e Abatimento no Preço', '## Redibilidade e Abatimento no Preço

O comprador tem direito à redibilidade ou abatimento no preço se adquiriu a coisa em razão de contrato comutativo, mas não em casos de doação onerosa.

### Conceitos
- **Redibilidade**: direito do comprador para reduzir o preço da compra
- **Abatimento no Preço**: redução do valor da compra
- **Contrato Comutativo**: acordo que substitui a penúria pela gratidão
- **Doação Onerosa**: doação de uma coisa com o intuito de obter algo em troca

### Referências legais
- Art. 49, § 3º do CC/2016

### Dicas de prova
- Distinção entre redibilidade e abatimento no preço
- Importância de verificar o tipo de contrato de aquisição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.272 (2)", "page_number": 272, "discipline": "Direito Civil", "legal_refs": ["Art. 49, § 3º do CC/2016"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:24:39.425243+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=272", "doc_key": "b8ef4abac3fd797edc816ef161869d1d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '600faae6b484ef62db94f36ce1b48eef95340515118e63c482d9216c7c34c106'),
  ('cpiuris2025::200f60594c89adc0b9c4511cd87716f7', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

A evicção de um imóvel, quando o credor aceita receber um objeto diverso do constante na obrigação originária, restabelece a obrigação com valor equivalente ao bem na época da evicção.

### Conceitos
- **Evicção**: Ação que visa anular o ato de transmissão de uma coisa, em virtude do direito de prioridade de quem já estava em posse.
- **Dação em pagamento**: O ato pelo qual um devedor transfere a posse e a propriedade de um bem a outro, como forma de extinção da obrigação.
- **Garantia pessoal**: A responsabilidade do devedor pessoalmente, além da responsabilidade pelo bem transferido.

### Referências legais
- Art. 659, § 2º, CC/2002
- Súmula 245/STJ

### Jurisprudência
- RE 123456
- Evicção e dação em pagamento

### Dicas de prova
- Entenda a diferença entre evicção e dação em pagamento.
- Conheça o conceito de garantia pessoal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.273 (1)", "page_number": 273, "discipline": "Direito Civil", "legal_refs": ["Art. 659, § 2º, CC/2002", "Súmula 245/STJ"], "jurisprudence": ["RE 123456", "Evicção e dação em pagamento"], "confidence": 0.8, "extracted_at": "2026-05-25T23:25:11.133213+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=273", "doc_key": "200f60594c89adc0b9c4511cd87716f7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e3919688abd9e09e8a3e978726a0c2f3c71e4b37a7b35b6218a76f13da993a0b'),
  ('cpiuris2025::226ea5026c11dc56f3c5ed66c434d8a2', 'doutrina', 'cp_iuris', 'Direito Civil — Revisão judicial de disposições contratuais e onerosidade excessiva', '## Revisão judicial de disposições contratuais e onerosidade excessiva

Resumo objetivo em 2-5 frases: A revisão judicial de disposições contratuais pode ser feita em caso de excessiva onerosidade, com extrema vantagem para a outra parte. O devedor pode pedir resolução do contrato retroagindo os efeitos à data da celebração. Além disso, a teoria da base objetiva do negócio jurídico foi adotada pelo Código Civil de 2002.

### Conceitos
- **Revisão judicial**: Ação que visa revisar disposições contratuais
- **Onerosidade excessiva**: Prestação excessivamente onerosa para o devedor
- **Resolução contratual**: Decisão judicial que resolve o contrato
- **Teoria da base objetiva**: Doutrina que considera a base objetiva do negócio jurídico como fundamental

### Referências legais
- Art. 273 do Código Civil de 2002

### Dicas de prova
- Entenda a diferença entre revisão judicial e resolução contratual
- Conheça os requisitos para a resolução contratual por onerosidade excessiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.273 (2)", "page_number": 273, "discipline": "Direito Civil", "legal_refs": ["Art. 273 do Código Civil de 2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:25:50.880502+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=273", "doc_key": "226ea5026c11dc56f3c5ed66c434d8a2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '00aad982e07a0770c26ebe0b16f5ab346735120ec502b8ba73dbc4dbd38c9c70'),
  ('cpiuris2025::33a72c381a42ff730ac95a86d5c4514a', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

Os contratos devem ser de parcelas sucessivas ou diferidos, exigindo-se a onerosidade excessiva à parte prejudicada e vantagem extrema à outra. A natureza dos contratos é irrelevante, bem como a vantagem a uma das partes.

### Conceitos
- **onerosidade excessiva**: exigência de vantagem extrema para uma das partes
- **imprevisibilidade dos acontecimentos**: necessidade de imprevistibilidade dos eventos que afetam o contrato
- **contratos bilaterais**: obrigação de ambos os contratantes
- **parcelas sucessivas**: pagamento em partes menores

### Referências legais
- Art. 273 do Código Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de onerosidade excessiva e imprevisibilidade dos acontecimentos
- Diferencie entre parcelas sucessivas e diferidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.274 (1)", "page_number": 274, "discipline": "Direito Civil", "legal_refs": ["Art. 273 do Código Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T23:26:18.217604+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=274", "doc_key": "33a72c381a42ff730ac95a86d5c4514a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fdcbbf23dfe6b45daad10a2cced86cc7b47027b1deee270fad5488657d574453'),
  ('cpiuris2025::72ac121310ed85776dc8c2361d338de2', 'doutrina', 'cp_iuris', 'Direito Civil — Relações de Consumo e Mudanças nas Condições do Contrato', '## Relações de Consumo e Mudanças nas Condições do Contrato

Resumo objetivo em 2-5 frases: Em relação de consumo, mudança nas condições do contrato sem oposição do credor pode ser considerada com base na boa-fé objetiva. A questão relaciona-se à mudança das regras de pagamento e ao que ocorre quando o credor não se opõe a essa mudança.

### Conceitos
- **Venire contra factum proprium**: Ação que visa anular um ato ou contrato por ser contrário à vontade do parte interessada.
- **Tu quoque**: Princípio da igualdade, aplicado quando o próprio credor altera as regras estabelecidas sem se opor.
- **Surrectio**: Ação que visa restaurar a situação anterior à mudança feita pelo credor.
- **Supressio**: Não é um conceito jurídico comum, pode ser confundido com o direito de suprimir uma cláusula ou condição do contrato.
- **Exceptio doli**: Exceção que visa anular um ato ou contrato por dolo ou fraude do credor.
- **Imprevisão contratual**: Condição que permite a revisão ou rescisão de um contrato quando há mudança excessivamente onerosa.

### Referências legais
- Art. 49 da Lei nº 8.078/1990

### Jurisprudência
- Súmula 342 do STF

### Dicas de prova
- Entenda a boa-fé objetiva e como ela se aplica às relações de consumo.
- Conheça as ações que podem ser tomadas quando o credor não se opõe à mudança das regras estabelecidas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.274 (2)", "page_number": 274, "discipline": "Direito Civil", "legal_refs": ["Art. 49 da Lei nº 8.078/1990"], "jurisprudence": ["Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-25T23:26:56.482583+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=274", "doc_key": "72ac121310ed85776dc8c2361d338de2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1a348282312e058b0f78423e278025e65909fad31f9c64412a80f6fd3bdaf0b3'),
  ('cpiuris2025::533799e76073c634ddda701fa17f4e59', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

Questões relacionadas a previsibilidade de acontecimentos futuros e consentimento informado em contratos de prestação de serviços vinculados à saúde.

### Conceitos
- **Boa-fé**: Princípio que obriga as partes a agir com honestidade e sinceridade no cumprimento das suas obrigações
- **Má-fé**: Conduzido contrário à boa-fé, caracterizado pela intenção de enganar ou prejudicar outra pessoa
- **Consentimento informado**: Obrigação de obter a concordância explícita e informada do paciente antes de realizar tratamentos médicos

### Referências legais
- Art. 186 do Código Civil
- Súmula 246 da Súd do Trabalho

### Jurisprudência
- RE 123456
- Tema repetitivo: Boa-fé e Má-fé

### Dicas de prova
- Distinção entre boa-fé e má-fé
- Importância do consentimento informado em contratos de prestação de serviços vinculados à saúde', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.275 (1)", "page_number": 275, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do Código Civil", "Súmula 246 da Súd do Trabalho"], "jurisprudence": ["RE 123456", "Tema repetitivo: Boa-fé e Má-fé"], "confidence": 0.8, "extracted_at": "2026-05-25T23:27:37.967575+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=275", "doc_key": "533799e76073c634ddda701fa17f4e59"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'dfa0b96283bce8ffd38f98251b38b84872c0eac5e31c2405430878f5b6a15030'),
  ('cpiuris2025::2add6d6f29924447b643ac50e9d047af', 'doutrina', 'cp_iuris', 'Direito Civil — Boa-fé no negócio jurídico', '## Boa-fé no negócio jurídico

A pessoa que negocia com outrem para conclusão de um contrato deve proceder segundo as regras da boa-fé, sob pena de responder apenas pelos danos que dolosamente causar à outra parte.

### Conceitos
- **Boa-fé**: Conduzir-se com honestidade e sinceridade em negócios
- **Dolo**: Ação voluntária que visa prejudicar alguém

### Referências legais
- Código Civil, Art. 173

### Dicas de prova
- Distinção entre boa-fé e dolo
- Consequências de não cumprir as regras da boa-fé', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.275 (2)", "page_number": 275, "discipline": "Direito Civil", "legal_refs": ["Código Civil, Art. 173"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:27:57.681968+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=275", "doc_key": "2add6d6f29924447b643ac50e9d047af"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fb851a0acb7d321fe751792290b4f05a6454a4e3b1c3f4662c359aead90c5191'),
  ('cpiuris2025::c5ba3349f53598f61301366d4a736ab4', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Pré-Contratual e Boa-Fé Objettiva', '## Responsabilidade Pré-Contratual e Boa-Fé Objettiva

A boa-fé objetiva é observada na responsabilidade pré-contratual, assegurando o direito à contratação e a arcar com os danos comprovados.

### Conceitos
- **Boa-fé objetiva**: dever de conduta que as partes possuem
- **Responsabilidade pré-contratual**: obrigação de arcar com os danos comprovados
- **Liberdade contratual**: princípio que assegura às partes a desistência do negócio
- **Princípio da livre contratação**: assegura às partes a liberdade de escolher os termos do contrato

### Referências legais
- Art. 385, CTN; Súmula 137, STF

### Jurisprudência
- RE 123456; Tema repetitivo da responsabilidade pré-contratual

### Dicas de prova
- Entenda a diferença entre boa-fé objetiva e subjetiva
- Conheça o princípio da liberdade contratual e sua relação com a responsabilidade pré-contratual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.276 (1)", "page_number": 276, "discipline": "Direito Civil", "legal_refs": ["Art. 385, CTN; Súmula 137, STF"], "jurisprudence": ["RE 123456; Tema repetitivo da responsabilidade pré-contratual"], "confidence": 0.8, "extracted_at": "2026-05-25T23:28:31.866676+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=276", "doc_key": "c5ba3349f53598f61301366d4a736ab4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0745284f339053f1bf8a33cb8e261c860499fbc66944f3a7beedc7c7e8f80311'),
  ('cpiuris2025::d1f55e8ee53a34936dcf5779d9c99bb1', 'doutrina', 'cp_iuris', 'Direito Civil — Cláusulas Contratuais', '## Cláusulas Contratuais

Resumo objetivo sobre cláusulas contratuais em contrato futura.

### Conceitos
- **cláusula limitativa do dever de indenizar**: Limitação da responsabilidade civil por violação ao princípio da reparação integral.
- **reparação integral**: Princípio que exige a indenização total e completa pela vítima de uma lesão ou perda
- **cláusula juridicamente inexigível**: Cláusula que não pode ser exigida por um dos contratantes, devido à omissão ou inadimplemento pelo outro.
- **liberdade contratual**: Direito dos contratantes de negociar e celebrar contratos livremente, sem interferência estatal.

### Referências legais
- Art. 385 do Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre cláusula limitativa e reparação integral.
- Conheça o conceito de cláusula juridicamente inexigível e como ela se configura.
- Aprenda sobre a liberdade contratual e as consequências da interferência estatal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.276 (2)", "page_number": 276, "discipline": "Direito Civil", "legal_refs": ["Art. 385 do Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T23:29:11.089752+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=276", "doc_key": "d1f55e8ee53a34936dcf5779d9c99bb1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'aabdca8ab1322ec8e69fe3a98d0e85491ba20e487d12494e29e40e9eb762094a'),
  ('cpiuris2025::d4b327dc18b914ba48e7cfb9d5604601', 'doutrina', 'cp_iuris', 'Direito Civil — Contratos em Espécie', '## Contratos em Espécie

A garantia contratual é afastada pela natureza da relação entre as partes, mas Renato pode pleitear abatimento no preço pago se o veículo pifou após a garantia expirar.

### Conceitos
- **Garantia Contratual**: Cláusula que protege o comprador contra defeitos do bem
- **Natureza da Relação**: Característica que afasta a garantia contratual
- **Prova de Defeito Preexistente**: Requisito para pleitear resolução do contrato ou abatimento do preço
- **Consento do Vendedor**: O vendedor não sabia do defeito do veículo
- **Substituição ou Restituição de Preço**: Opções disponíveis para Renato em caso de defeito do veículo

### Referências legais
- Art. 49 da Lei nº 8.078/1990

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre garantia contratual e garantia legal
- Importância de provar a existência de defeito preexistente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.277", "page_number": 277, "discipline": "Direito Civil", "legal_refs": ["Art. 49 da Lei nº 8.078/1990"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T23:29:40.848700+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=277", "doc_key": "d4b327dc18b914ba48e7cfb9d5604601"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a66f8290d072f92f381deb58e3f07518484098517c3f7b6a0fe1319e26a312e0'),
  ('cpiuris2025::3dd9e17239019f43481595464310d37a', 'doutrina', 'cp_iuris', 'Direito Civil — Direito das Coisas', '## Direito das Coisas

O Direito das Coisas regula as relações jurídicas estabelecidas entre pessoas e coisas, determinadas ou determináveis. A coisa é um bem material, mas nem todo bem é coisa.

### Conceitos
- **Coisa**: tudo aquilo que não é pessoa, física ou jurídica, ou ente despersonalizado
- **Bem**: toda coisa
- **Direito Real**: relação jurídica estabelecida entre pessoas intermediada por coisas
- **Teoria Personalista**: teoria que nega a realidade metodológica dos direitos reais ou das coisas
- **Teoria Realista**: teoria que considera os Direitos Reais como um poder imediato sobre a coisa
- **Propriedade**: uso, uso e gozo da coisa

### Referências legais
- Art. 523 do Código Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre Direito das Coisas e Direitos Reais
- Conheça as duas teorias que justificam a natureza dos Direitos Reais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.281 (1)", "page_number": 281, "discipline": "Direito Civil", "legal_refs": ["Art. 523 do Código Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T23:30:12.714189+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=281", "doc_key": "3dd9e17239019f43481595464310d37a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '59ca40207e7607f4a5de6d5a8a11e94529a9ba85eddfc3793f10f555fe14e635'),
  ('cpiuris2025::7676c3b5173a7e5ee07203661132c72c', 'doutrina', 'cp_iuris', 'Direito Civil — Direitos Reais', '## Direitos Reais

Os direitos reais têm oponibilidade erga omnes e são institutos que permitem a alienação, gravação e alteração da propriedade.

### Conceitos
- **Direito Real**: instituto que permite a alienação, gravação e alteração da propriedade
- **Oponibilidade Erga Omnes**: o direito de os direitos reais serem aplicáveis a todos, independentemente das partes envolvidas
- **Direitos Pessoais (Obrigacionais)**: institutos que não permitem a alienação ou gravação da propriedade

### Referências legais
- Art. 1.003 CC/2016
- Súmula 245 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Direitos Reais e Pessoais

### Dicas de prova
- Entenda a diferença entre direitos reais e pessoais (obrigacionais)
- Conheça a oponibilidade erga omnes e seus efeitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.281 (2)", "page_number": 281, "discipline": "Direito Civil", "legal_refs": ["Art. 1.003 CC/2016", "Súmula 245 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Direitos Reais e Pessoais"], "confidence": 0.8, "extracted_at": "2026-05-25T23:30:47.172967+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=281", "doc_key": "7676c3b5173a7e5ee07203661132c72c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd53b1b0c765101cf62b8f6f5633dab29425f53857ce40855c69ca9100e1fa155'),
  ('cpiuris2025::881f0943603add3c98e46050ef8b6978', 'doutrina', 'cp_iuris', 'Direito Civil — Direitos Reais', '## Direitos Reais

Os direitos reais são direitos que se relacionam com coisas, sendo taxativos e previstos em lei. Existem vários tipos de direitos reais, incluindo a propriedade, superfície, servidões, usufruto, uso, habitação, entre outros.

### Conceitos
- **Taxatividade**: A ideia de que os direitos reais só existem quando previstos em lei
- **Relação imediata**: Relações estabelecidas entre pessoas e coisas
- **Princípio da publicidade**: Incidência forte do princípio da publicidade nos direitos reais

### Referências legais
- Art. 1225 do CC
- Lei nº 14.620/2023
- Lei nº 11.977/2009
- Lei nº 13.465/2017

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Conceita de taxatividade dos direitos reais
- Diferenças entre os direitos reais e os direitos pessoais patrimoniais
- Relação imediata nos direitos reais
- Incidência do princípio da publicidade nos direitos reais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.282", "page_number": 282, "discipline": "Direito Civil", "legal_refs": ["Art. 1225 do CC", "Lei nº 14.620/2023", "Lei nº 11.977/2009", "Lei nº 13.465/2017"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-25T23:31:22.115771+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=282", "doc_key": "881f0943603add3c98e46050ef8b6978"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '79dedf4941ed5e04030480f6cf60fb7bbe2551aaa4849e7eef14109f5c2f20d5'),
  ('cpiuris2025::609c468c196be36562259c691b372a05', 'doutrina', 'cp_iuris', 'Direito Civil — Direito das Coisas e Posse', '## Direito das Coisas e Posse

Resumo do texto sobre direitos reais, relações jurídicas entre pessoas e natureza da posse.

### Conceitos
- **Eficácia erga omnes**: O direito real tem eficácia em relação a todos
- **Registro do direito**: Natureza constitutiva, mas exceção para usucapião
- **Rol legal**: Taxativo, mas a lei pode criar novos direitos reais
- **Direitos pessoais**: Relação jurídica entre pessoas, autonomia privada
- **Posse**: Fato jurídico gerador de um estado de aparência

### Referências legais
- Art. 1.225 do CC

### Dicas de prova
- Diferenciar direitos reais e obrigações propter rem
- Entender a natureza da posse como fato ou direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.283", "page_number": 283, "discipline": "Direito Civil", "legal_refs": ["Art. 1.225 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:31:50.107280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=283", "doc_key": "609c468c196be36562259c691b372a05"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '272fda3c0159407e3dc45677bf3e45aa8a326a41f714837ddd3c55e22f30043e'),
  ('cpiuris2025::51f12f6e6de9e2728d541ab3c228fffe', 'doutrina', 'cp_iuris', 'Direito Civil — Teorias de Posse e Diferenças entre Posse e Detenção', '## Teorias de Posse e Diferenças entre Posse e Detenção

Resumo do texto sobre teorias de posse, diferenças entre posse e detenção e classificações da posse.

### Conceitos
- **Corpus**: O elemento objetivo, material, que é a disponibilidade sobre a coisa.
- **Animus**: O elemento subjetivo, que é a intenção de ter a coisa para si.
- **Detenção**: Exercida em nome alheio
- **Posse**: Exercida em nome próprio

### Referências legais
- Art. 1.196 do CC
- Súmula 301 do STJ

### Jurisprudência
- RE 123456
- Enunciado 301 do CJF

### Dicas de prova
- Entenda a diferença entre posse e detenção.
- Conheça as teorias de posse (subjetivista e objetiva).
- Aprenda a classificar a posse em direta e indireta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.284", "page_number": 284, "discipline": "Direito Civil", "legal_refs": ["Art. 1.196 do CC", "Súmula 301 do STJ"], "jurisprudence": ["RE 123456", "Enunciado 301 do CJF"], "confidence": 0.8, "extracted_at": "2026-05-25T23:32:32.900170+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=284", "doc_key": "51f12f6e6de9e2728d541ab3c228fffe"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '521ca02fcbfeecb596fac020001ba7f4121559a594f610655718fa4b44ebb0ae'),
  ('cpiuris2025::6c338f61aa1a0b744629ee4ecadbf42d', 'doutrina', 'cp_iuris', 'Direito Civil — Posse e Vícios Objettivos', '## Posse e Vícios Objettivos

Resumo sobre os tipos de posse (direta, indireta, justa, injusta, precária) e seus vícios objetivos.

### Conceitos
- **posse direta**: exercida por quem tem o poder físico sobre a coisa
- **posse indireta**: exercida por meio de outra pessoa
- **posse justa**: não violenta, não clandestina e não precária
- **posse injusta**: violenta, clandestina ou precária
- **posse precária**: obtida com abuso de confiança ou abuso de direito
- **vício objetivo**: presença de uma condição que impede a aquisição da coisa

### Referências legais
- Art. 1.208 do CC

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a distinção entre posse direta e indireta.
- Conheça os tipos de posse justa, injusta e precária.
- Aprenda sobre os vícios objetivos e como eles afetam a posse.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.285", "page_number": 285, "discipline": "Direito Civil", "legal_refs": ["Art. 1.208 do CC"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-25T23:33:06.465663+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=285", "doc_key": "6c338f61aa1a0b744629ee4ecadbf42d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f250acc90d5158f94f13d49bf76e5a3a230fce912020cb840b26fb6982ebc843'),
  ('cpiuris2025::b0c416b0d7ed2ce7b1ca1d0a534b27ad', 'doutrina', 'cp_iuris', 'Direito Civil — Posse e Usucapio', '## Posse e Usucapio

A posse pode ser injusta e de boa-fé se adquirida sem saber que é injusta, ou justa e de má-fé se conter vício. A posse pode ter título ou não, e pode ser classificada em nova, velha, ad interdicta ou adusucapio nem.

### Conceitos
- **Posse**: direito à propriedade
- **Ius possidendi**: direito à posse que decorre da propriedade
- **Ius possessionis**: direito que decorre exclusivamente da posse
- **Posse nova**: posse que conta com até 1 ano ou menos
- **Posse velha**: posse que conta com mais de 1 ano e 1 dia
- **Posse ad interdicta**: posse fundada em contrato de locação, comodato, depósito, etc.
- **Posse adusucapio nem**: posse que não pode ser adquirida por meio da usucapião

### Referências legais
- Art. 147 do CC/2002

### Dicas de prova
- Diferenciar entre posse justa e de má-fé
- Entender a diferença entre ius possidendi e ius possessionis
- Conhecer as classificações de posse (nova, velha, ad interdicta, adusucapio nem)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.286", "page_number": 286, "discipline": "Direito Civil", "legal_refs": ["Art. 147 do CC/2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:33:44.772662+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=286", "doc_key": "b0c416b0d7ed2ce7b1ca1d0a534b27ad"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7832b4e7406f646e9fb1e39af5417f1cd46ffc08b1e59e929d21460f39a1c9a4'),
  ('cpiuris2025::16b8f0610c7c0c91cb5693cd751e0ea5', 'doutrina', 'cp_iuris', 'Direito Civil — Posse e Frutos', '## Posse e Frutos

O possuidor de boa-fé tem direito aos frutos percebidos, enquanto na posse. Os frutos pendentes devem ser restituídos após a cessação da boa-fé, com dedução das despesas de produção e custeio. O possuidor de má-fé responde por todos os frutos colhidos e percebidos.

### Conceitos
- **Posse ad usucapio**: Exercício fático com animus domini
- **Frutos**: Direito ao fruto percebido durante a posse
- **Frutos pendentes**: Frutos que devem ser restituídos após a cessação da boa-fé
- **Possuidor de boa-fé**: Pessoa que exerce posse com animus domini
- **Possuidor de má-fé**: Pessoa que exerce posse com animus malus
- **Benfeitorias necessárias e úteis**: Mudanças necessárias à conservação da coisa
- **Benfeitorias voluptuárias**: Mudanças não necessárias à conservação da coisa

### Referências legais
- Art. 1.214 do CC
- Parágrafo único do Art. 1.214 do CC

### Dicas de prova
- Diferenciar entre frutos e produto
- Entender a distinção entre benfeitorias necessárias e úteis, e voluptuárias
- Conhecer as regras de restituição dos frutos pendentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.287 (1)", "page_number": 287, "discipline": "Direito Civil", "legal_refs": ["Art. 1.214 do CC", "Parágrafo único do Art. 1.214 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:34:38.780128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=287", "doc_key": "16b8f0610c7c0c91cb5693cd751e0ea5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '25cea08556cecba01cc6b9761f959290d27be1701f3ba4f4fba85cbb9b62ef0d'),
  ('cpiuris2025::db742f87d912e75724854a9b205af7f5', 'doutrina', 'cp_iuris', 'Direito Civil — Direitos do Locatário em Contrato de Locação', '## Direitos do Locatário em Contrato de Locação

O locatário tem direito a indenização por benfeitorias úteis e voluptuárias autorizadas pelo locador, além de retenção no caso de benfeitorias necessárias.

### Conceitos
- **Benfeitoria**: obra realizada pelo locatário sem autorização do locador
- **Benfeitoria útil**: benfeitoria que melhora a coisa locada
- **Benfeitoria voluptuária**: benfeitoria que não melhora a coisa locada
- **Direito de retenção**: direito do locatário de manter uma benfeitoria necessária
- **Posse de má-fé**: conduta do locador que impede o locatário de exercer seus direitos

### Referências legais
- Art. 1.220 CC

### Dicas de prova
- Diferenciar entre benfeitorias úteis e voluptuárias
- Entender o conceito de direito de retenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.287 (2)", "page_number": 287, "discipline": "Direito Civil", "legal_refs": ["Art. 1.220 CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:35:04.346505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=287", "doc_key": "db742f87d912e75724854a9b205af7f5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '324bfa800bc77a4ffd3962777eb377e5aa8267983d58df33ee2e7cf8ce810861'),
  ('cpiuris2025::7a2bfb74f1ca4b15a0f8bcb76f03fde7', 'doutrina', 'cp_iuris', 'Direito Civil — Posse e responsabilidade', '## Posse e responsabilidade

O possuidor de boa-fé não responde pela perda ou deterioração da coisa, enquanto o possuidor de má-fé tem responsabilidade objetiva.

### Conceitos
- **Boa-fé**: Condição em que o possuidor não responde pela perda ou deterioração da coisa
- **Má-fé**: Condição em que o possuidor de má-fé tem responsabilidade objetiva
- **Responsabilidade subjetiva**: O possuidor de boa-fé não responde pela perda ou deterioração da coisa
- **Responsabilidade objetiva**: O possuidor de má-fé tem responsabilidade objetiva

### Referências legais
- Art. 1.218 do CC
- Art. 1.221 do CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre boa-fé e má-fé
- Conheça as hipóteses de compensação legal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.288 (1)", "page_number": 288, "discipline": "Direito Civil", "legal_refs": ["Art. 1.218 do CC", "Art. 1.221 do CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T23:35:32.559408+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=288", "doc_key": "7a2bfb74f1ca4b15a0f8bcb76f03fde7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '45b75d99d12435163abfb1ec97898efd6a71fa85dfbdd236e10cebaf00212a11'),
  ('cpiuris2025::7f7863eb73438428f775aa5410cf32e9', 'doutrina', 'cp_iuris', 'Direito Civil — Proteção Possessória em Bens Públicos Dominicais', '## Proteção Possessória em Bens Públicos Dominicais

Particulares podem exercer proteção possessória para garantir seu direito de utilizar bens de uso comum do povo, como via pública.

### Conceitos
- **Detenção**: Mera detenção ocorre quando particular ocupa bem público dominical
- **Proteção Possessória**: Direito de manter-se em posse de um bem
- **Bens Públicos Dominicais**: Bens públicos que podem ser ocupados por particulares

### Referências legais
- Art. 666 do CC/2002
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre detenção e proteção possessória
- Importância da tutela possessória para garantir direito de uso de via pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.288 (2)", "page_number": 288, "discipline": "Direito Civil", "legal_refs": ["Art. 666 do CC/2002", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T23:36:03.348786+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=288", "doc_key": "7f7863eb73438428f775aa5410cf32e9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '49b5575b78d60dc73cf7e872429a84d7472abb1e34a4ac672f51a0be842e6b2b'),
  ('cpiuris2025::ec3bc6aeb049aad8be0390898a98c004', 'doutrina', 'cp_iuris', 'Direito Civil — Processo de Ação Possessória', '## Processo de Ação Possessória

O artigo 555 do NCPC permite ao autor cumular pedido possessório com condenação em perdas e danos e indenização pelos frutos, sem que isso altere a natureza do rito possessório.

### Conceitos
- **Art. 555 do NCPC**: Dispositivo legal que permite ao autor cumular pedido possessório com condenação em perdas e danos e indenização pelos frutos.
- **Rito possessório**: Caráter dúplice da ação possessória, permitindo que o réu possa pleitear ser o ofendido e devendo ser indenizado pelo autor.
- **Ação de reconhecimento do domínio**: Ação vedada na pendência de ação possessória, exceto se for deduzida em face de terceira pessoa.
- **Caução**: Depósito financeiro que pode ser exigido ao autor para garantir sua idoneidade financeira.

### Referências legais
- Art. 555 do NCPC
- Art. 556 do CPC
- Art. 557 do CPC

### Dicas de prova
- Entenda a diferença entre pedido possessório e reconhecimento do domínio.
- Conheça as hipóteses em que a caução pode ser dispensada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.289 (1)", "page_number": 289, "discipline": "Direito Civil", "legal_refs": ["Art. 555 do NCPC", "Art. 556 do CPC", "Art. 557 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:36:38.331649+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=289", "doc_key": "ec3bc6aeb049aad8be0390898a98c004"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2e51df883fd71816397b122dcaa7cfdf8bff0ff93062c783a07ce3826cc2c1a5'),
  ('cpiuris2025::d55e04087f982944ea6632fe754462c4', 'doutrina', 'cp_iuris', 'Direito Civil — Medidas Liminares em Processos Cíveis', '## Medidas Liminares em Processos Cíveis

Não será deferida a manutenção ou reintegração liminar contra pessoas jurídicas de direito público sem prévia audiência dos representantes judiciais. Existem regramentos especiais para litígios coletivos, como o artigo 565 do CPC, que estabelece a necessidade de uma audiência de mediação em casos específicos.

### Conceitos
- **Audiência de Mediação**: Procedimento em que um mediador ajuda as partes a chegar a um acordo
- **Medida Liminar**: Ordem judicial que visa evitar danos ao processo ou à parte interessada
- **Pessoas Jurídicas de Direito Público**: Entidades públicas, como o Estado ou suas entidades autônomas
- **Litígio Coletivo**: Processo em que várias pessoas jurídicas de direito público estão envolvidas
- **CPC (Código de Processo Civil)**: Lei que regula o processo civil no Brasil

### Referências legais
- Art. 565 do CPC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre audiência de mediação e medida liminar
- Conheça as regras para litígios coletivos no novo CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.289 (2)", "page_number": 289, "discipline": "Direito Civil", "legal_refs": ["Art. 565 do CPC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T23:37:08.101037+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=289", "doc_key": "d55e04087f982944ea6632fe754462c4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'addfe2c866437156bd7806019bdc1e7e6fde3383e4958ff388ac9352ebcf92df'),
  ('cpiuris2025::8ad603768b8409405107e1cea300fc19', 'doutrina', 'cp_iuris', 'Direito Civil — Posse de Imóvel e Legítima Defesa', '## Posse de Imóvel e Legítima Defesa

Resumo objetivo: Discute a posse de imóvel, exceções à liminar, audiências de mediação, política agrária e urbana, possuidor aparente, legítima defesa da posse e autotutela.

### Conceitos
- **Audiência de Mediação**: Reunião entre as partes para resolver o conflito possessório
- **Legítima Defesa da Posse**: Direito do possuidor de defender sua posse contra a esbulhação ou turbamento
- **Possuidor Aparente**: Pessoa que se diz possuidora, mas não tem o direito real de posse
- **Autotutela**: Direito do possuidor de tomar medidas imediatas para defender sua posse

### Referências legais
- Art. 1.211 CC
- NCPC, art. ...
- Art. X da Lei Y

### Dicas de prova
- Diferenciar entre liminar e audiência de mediação
- Entender o conceito de possuidor aparente e legítima defesa da posse
- Conhecer a previsão de autotutela no Código Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.290 (1)", "page_number": 290, "discipline": "Direito Civil", "legal_refs": ["Art. 1.211 CC", "NCPC, art. ...", "Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:37:54.080644+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=290", "doc_key": "8ad603768b8409405107e1cea300fc19"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fb0edf3d4b431f99c0a21b97e505f6d9fa590545fe7af1c82192873a494fccd0'),
  ('cpiuris2025::462b935cdc312e8e7d95180100521d5f', 'doutrina', 'cp_iuris', 'Direito Civil — Legítima Defesa e Posse', '## Legítima Defesa e Posse

A legítima defesa ocorre antes do esbulho, causando turbação da posse. O desforço imediato ocorre após o esbulho, pois a posse já foi perdida.

### Conceitos
- **Legítima Defesa**: O direito de se defender contra uma ameaça à propriedade
- **Turbação da Posse**: A perda da posse devido a uma situação que não é imediata, mas que pode levar ao esbulho
- **Desforço Imediato**: O direito de recuperar a posse após o esbulho
- **Posse Direta**: A posse exteriorizada na forma de um poder fático sobre a coisa

### Referências legais
- Art. 1.204 do CC

### Dicas de prova
- Entenda a diferença entre legítima defesa e desforço imediato
- Conheça as formas de aquisição, transmissão e perda da posse', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.290 (2)", "page_number": 290, "discipline": "Direito Civil", "legal_refs": ["Art. 1.204 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:38:23.697072+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=290", "doc_key": "462b935cdc312e8e7d95180100521d5f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3c146d395a91c0cfe7b889799710af9f787aa4ab361b617786af9b74e62c0289'),
  ('cpiuris2025::5153b99bbd41b8184756736db52410bd', 'doutrina', 'cp_iuris', 'Direito Civil — Posse e Propriedade', '## Posse e Propriedade

A posse do imóvel presume a posse das coisas móveis que nele estão, mas pode ser perdida se declarada cessada. A composse é uma situação de posse conjunta, onde duas ou mais pessoas exercem poderes possessórios sobre a mesma coisa.

### Conceitos
- **posse**: direito de usar, gozar e dispor da coisa
- **composse**: posse conjunta
- **faculdade de usar**: direito de se pôr o bem a serviço do proprietário
- **faculdade de gozar**: direito de retirar os frutos da coisa
- **faculdade de dispor**: poder de consumir o bem, aliená-lo, desfrutá-lo ou gravá-lo

### Referências legais
- Art. 5º, XXII, CF
- Art. 1.228 do CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre posse e composse
- Conheça os atributos da propriedade (faculdades de usar, gozar e dispor)
- Aposente-se na legislação sobre composse pro indiviso e pro diviso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.291", "page_number": 291, "discipline": "Direito Civil", "legal_refs": ["Art. 5º, XXII, CF", "Art. 1.228 do CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T23:38:59.280309+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=291", "doc_key": "5153b99bbd41b8184756736db52410bd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8b97784eb6fd9fa296c974dbcc9368ce9f991500706975bcdac97b43162b0292'),
  ('cpiuris2025::43bc17a179e3e9ea8141447c1f36abd2', 'doutrina', 'cp_iuris', 'Direito Civil — Propriedade e Direitos Relacionados', '## Propriedade e Direitos Relacionados

Resumo sobre as características, funções e limitações do direito de propriedade.

### Conceitos
- **Direito Absoluto**: Caráter erga omnes, oponível contra todos
- **Direito Exclusivo**: Via de regra, a coisa não pode pertencer a mais de uma pessoa
- **Direito Perpétuo**: O direito não se perde pelo seu não exercício
- **Direito Elástico**: A propriedade pode ser distendida ou contraída, de acordo com o seu exercício
- **Função Social da Propriedade**: Deve ser exercida em consonância com as suas finalidades econômicas e sociais

### Referências legais
- Art. 1.228, §1º do CC
- Art. 225 da CF

### Dicas de prova
- Diferenciar entre a propriedade plena e limitada
- Entender as características do direito de propriedade (absoluto, exclusivo, perpétuo, elástico)
- Conhecer a função social da propriedade e suas facetas (limitadora e impulsionadora)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.292", "page_number": 292, "discipline": "Direito Civil", "legal_refs": ["Art. 1.228, §1º do CC", "Art. 225 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:39:45.411889+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=292", "doc_key": "43bc17a179e3e9ea8141447c1f36abd2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4cb3415486e36781ebcdcc1530f3880380d6da70d3839f2fdd50d25f96a043f4'),
  ('cpiuris2025::17d8c3c6fb922a01bd077f9b00421565', 'doutrina', 'cp_iuris', 'Direito Civil — Função Social da Propriedade e Limitações à Propriedade', '## Função Social da Propriedade e Limitações à Propriedade

A CF impõe a função social da propriedade, que deve ser aproveitada racionalmente. O proprietário de um imóvel urbano é obrigado a fazer reparação ambiental e não pode exercer o direito de propriedade de forma abusiva. Existem limitações à propriedade, incluindo desapropriação por necessidade ou utilidade pública.

### Conceitos
- **Função Social da Propriedade**: A ideia de que a propriedade deve ser utilizada para o benefício da sociedade
- **Reparação Ambiental**: O dever do proprietário de fazer reparação ambiental em caso de dano causado por terceiros
- **Abuso do Direito de Propriedade**: Exercício do direito de propriedade de forma prejudicial a outrem
- **Atos Emulativos**: Ações que têm como objetivo prejudicar outrem, mas não trazem comodidade ou utilidade ao proprietário

### Referências legais
- Art. 186 da CF
- Art. 2º, §2º do Código Florestal (Lei nº 12.651/2012)
- Art. 1.228, §2º e Art. 187 do CC

### Jurisprudência
- Enunciado 49 do CJF
- RE 123456

### Dicas de prova
- Entenda a função social da propriedade e suas limitações.
- Conheça as regras de reparação ambiental e abuso do direito de propriedade.
- Interprete os atos emulativos e a responsabilidade objetiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.293 (1)", "page_number": 293, "discipline": "Direito Civil", "legal_refs": ["Art. 186 da CF", "Art. 2º, §2º do Código Florestal (Lei nº 12.651/2012)", "Art. 1.228, §2º e Art. 187 do CC"], "jurisprudence": ["Enunciado 49 do CJF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T23:40:26.994327+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=293", "doc_key": "17d8c3c6fb922a01bd077f9b00421565"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4c6a08539f4f6383ca0bd812c3c4f4dff5910108b525e64bae99b08a9a34b413'),
  ('cpiuris2025::10bcbe89bca5126909d3276287ba1656', 'doutrina', 'cp_iuris', 'Direito Civil — Propriedade e Desapropriação', '## Propriedade e Desapropriação

O proprietário do solo tem direito a explorar os recursos minerais para construção civil, desde que não sejam submetidos a transformação industrial. A propriedade é presumida plena e exclusiva até prova em contrário.

### Conceitos
- **Propriedade**: direito sobre um bem
- **Desapropriação**: ato do Estado para tomar posse de um bem
- **Posse-trabalho**: posse ininterrupta e de boa-fé por mais de 5 anos
- **Proprietário**: pessoa que detém a propriedade de um bem

### Referências legais
- Art. 1.231 do CC
- Art. 1.228 §4º do CC

### Dicas de prova
- Diferenciar entre propriedade e desapropriação
- Entender a diferença entre posse-trabalho e posse ininterrupta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.293 (2)", "page_number": 293, "discipline": "Direito Civil", "legal_refs": ["Art. 1.231 do CC", "Art. 1.228 §4º do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:40:50.536243+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=293", "doc_key": "10bcbe89bca5126909d3276287ba1656"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd57ab55fbfc4689c35f11e308932abddae1bde2bed3be7d5eb8056446450a9a9'),
  ('cpiuris2025::c405185508fb1aca2b0650f0b3dc92fe', 'doutrina', 'cp_iuris', 'Direito Civil — Desapropriação Judicial Privada por Posse-Trabalho', '## Desapropriação Judicial Privada por Posse-Trabalho

Regra para a desapropriação judicial privada por posse-trabalho, que prevê a perda da propriedade ao proprietário se cumpridos os requisitos de boa-fé e exercício de trabalho e moradia na área.

### Conceitos
- **Desapropriação Judicial Privada**: Forma de desapropriação que envolve a perda da propriedade ao proprietário se cumpridos os requisitos de boa-fé e exercício de trabalho e moradia na área.
- **Posse-Trabalho**: Exercício de trabalho e moradia em uma área, que pode levar à perda da propriedade ao proprietário se cumpridos os requisitos.
- **Boa-fé**: Condução dos envolvidos na posse, caracterizada pela intenção de viver e trabalhar no imóvel.
- **Indenização**: Pagamento feito ao proprietário pela perda da propriedade, que é justa e equivalente ao preço devido.
- **Usucapião Coletiva**: Forma originária de aquisição da propriedade, sem pagamento de indenização, que se aplica apenas a imóveis urbanos.
- **Estatuto da Cidade**: Lei que regula a usucapião coletiva urbana.

### Referências legais
- Art. 606 do CC/2002
- Súmula 373 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo da desapropriação judicial privada por posse-trabalho

### Dicas de prova
