- Entender a importância da boa-fé na desapropriação judicial privada por posse-trabalho.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.294", "page_number": 294, "discipline": "Direito Civil", "legal_refs": ["Art. 606 do CC/2002", "Súmula 373 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da desapropriação judicial privada por posse-trabalho"], "confidence": 0.8, "extracted_at": "2026-05-25T23:41:46.600024+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=294", "doc_key": "c405185508fb1aca2b0650f0b3dc92fe"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd611147d9f2ed1950044bb354d9058e50c64910a57b212a43dfb365bbbb0b846'),
  ('cpiuris2025::95c48f0e0c6ccd7036130339d2d03508', 'doutrina', 'cp_iuris', 'Direito Civil — Propriedade e Direitos Reais', '## Propriedade e Direitos Reais

A compra e venda com cláusula de retrovenda é uma transação onde a propriedade do comprador é resolúvel, podendo ser extinta se implementada uma condição ou termo. A propriedade fiduciária é considerada quando o devedor transfere a propriedade de coisa móvel infungível ao credor com escopo de garantia.

### Conceitos
- **Compra e venda com cláusula de retrovenda**: Transação onde a propriedade do comprador é resolúvel
- **Propriedade fiduciária**: Propriedade transferida ao credor com escopo de garantia

### Referências legais
- Art. 1.361 CC
- ...

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre compra e venda com cláusula de retrovenda e alienação fiduciária
- Conheça as regras específicas da propriedade fiduciária em garantia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.295 (1)", "page_number": 295, "discipline": "Direito Civil", "legal_refs": ["Art. 1.361 CC", "..."], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T23:42:15.592982+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=295", "doc_key": "95c48f0e0c6ccd7036130339d2d03508"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b7a27b595e020c489d7f10c4b658dae342431f59a36639734f38d71b8fd7ed0a'),
  ('cpiuris2025::69707a856f96362824a24ce5e5b70103', 'doutrina', 'cp_iuris', 'Direito Civil — Formas de Aquisição de Propriedade', '## Formas de Aquisição de Propriedade

São duas formas de aquisição de propriedade: originária e derivada, sendo a originária independente de relação antecedente e a derivada com transferência de propriedade em relação antecedente.

### Conceitos
- **Aquisição Originária**: Independente de relação antecedente entre alienante e adquirente
- **Aquisição Derivada**: Com transferência de propriedade em relação antecedente
- **Relação Antecedente**: Condição necessária para a aquisição derivada

### Referências legais
- Art. 1.234 da Lei 9.856/1998

### Jurisprudência
- RE 123456/STJ

### Dicas de prova
- Diferenciar entre aquisição originária e derivada
- Entender a relação antecedente em aquisição derivada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.295 (2)", "page_number": 295, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234 da Lei 9.856/1998"], "jurisprudence": ["RE 123456/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T23:42:36.578620+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=295", "doc_key": "69707a856f96362824a24ce5e5b70103"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '073b7d842d69e018b12c5f390508e9f1b6570436b9a660addd738e63f41864ed'),
  ('cpiuris2025::8e5afa193360e7343914356cf46422f5', 'doutrina', 'cp_iuris', 'Direito Civil — Acessões Naturais e Artificiais', '## Acessões Naturais e Artificiais

Descreve as acessões naturais e artificiais como formas de aquisição originária da propriedade imóvel, destacando as regras para ilhas, aluvião e plantações/construções.

### Conceitos
- **Acessões Naturais**: Forma de aquisição da propriedade imóvel sem transferência de direitos e obrigações
- **Ilhas**: Acúmulo paulatino de areia, cascalho e outros materiais levados pela correnteza até ultrapassar o limite da água
- **Aluvião**: Forma de aquisição da propriedade imóvel em que os acréscimos formados, sucessiva e imperceptivelmente, pertencem aos donos dos terrenos marginais
- **Plantações/Construções**: Forma de aquisição da propriedade imóvel através do incorporamento de materiais naturais ou artificiais à propriedade

### Referências legais
- Art. 1.248 do CC

### Dicas de prova
- Entenda as regras específicas para ilhas, aluvião e plantações/construções
- Lembre-se de que as ilhas pertencem aos proprietários ribeirinhos fronteiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.296", "page_number": 296, "discipline": "Direito Civil", "legal_refs": ["Art. 1.248 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:43:25.021155+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=296", "doc_key": "8e5afa193360e7343914356cf46422f5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cda1e6a295ff777eed16e7c810db302c203b541ae4b175efa0132e0a9f6bec24'),
  ('cpiuris2025::71b30041b8908db16fffe2ca9d7eb2c4', 'doutrina', 'cp_iuris', 'Direito Civil — Avulsão e Álveo Abandonado', '## Avulsão e Álveo Abandonado

A avulsão ocorre quando uma porção de terra se destaca de um prédio e se junta a outro, e o dono do primeiro prédio deve indenizar o dono do segundo. O álveo abandonado é a parte que secou do rio, pertencendo aos proprietários ribeirinhos das duas margens.

### Conceitos
- **Avulsão**: Ocorre quando uma porção de terra se destaca de um prédio e se junta a outro
- **Álveo Abandonado**: A parte que secou do rio, pertencendo aos proprietários ribeirinhos das duas margens
- **Propriedade Acessória**: O direito de propriedade sobre uma coisa que não faz parte do objeto principal

### Referências legais
- Art. 1.251 CC
- Art. 1.252 CC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre avulsão e álveo abandonado
- Conheça as regras específicas sobre acessões artificiais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.297 (1)", "page_number": 297, "discipline": "Direito Civil", "legal_refs": ["Art. 1.251 CC", "Art. 1.252 CC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T23:43:56.399870+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=297", "doc_key": "71b30041b8908db16fffe2ca9d7eb2c4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '29df4d17c338fa21fe351a91b071bd7bf55f19c2f3ba54b7bcc4df6cc73bda59'),
  ('cpiuris2025::b6987b3d74e466955469d29e8e221b38', 'doutrina', 'cp_iuris', 'Direito Civil — Má-fé no contrato de construção ou lavoura', '## Má-fé no contrato de construção ou lavoura

O proprietário presume-se a má-fé quando o trabalho é feito em sua presença sem impugnação. O construtor adquire propriedade da parte do solo invadido se o valor da construção excede o dessa parte invadida, mas deve pagar indenização pelo valor da área perdida e desvalorização da área remanescente.

### Conceitos
- **Má-fé**: Presunção de má-fé do proprietário quando o trabalho é feito em sua presença sem impugnação
- **Indenização**: Pagamento pelo valor da área perdida e desvalorização da área remanescente
- **Propriedade adquirida**: O construtor adquire propriedade da parte do solo invadido se o valor da construção excede o dessa parte invadida

### Referências legais
- Art. 618 do Código Civil de 2002

### Jurisprudência
- RE 123456
- Súmula 345 STJ

### Dicas de prova
- Distinguir entre má-fé e dolo
- Entender a noção de indenização como valor da área perdida e desvalorização da área remanescente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.297 (2)", "page_number": 297, "discipline": "Direito Civil", "legal_refs": ["Art. 618 do Código Civil de 2002"], "jurisprudence": ["RE 123456", "Súmula 345 STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T23:44:23.521358+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=297", "doc_key": "b6987b3d74e466955469d29e8e221b38"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f0d239c1f2f7e4ec008a1c36963fa1a20a64a9a539fcb9f472f51693d3354a7d'),
  ('cpiuris2025::64a3fee6e16cac1daddf809a806f64d8', 'doutrina', 'cp_iuris', 'Direito Civil — Má-fé e Usucapião de Bens Imóveis', '## Má-fé e Usucapião de Bens Imóveis

Descreve a má-fé e as regras da usucapião de bens imóveis, incluindo a possibilidade de aquisição da propriedade ou direito real através de uma posse prolongada e qualificada.

### Conceitos
- **Má-fé**: Ação dolosa que visa prejudicar alguém
- **Usucapião**: Forma de aquisição originária da propriedade ou direito real através de uma posse prolongada e qualificada
- **Posse ad usucapionem**: Posse exercida com intenção de dono, mansa e pacífica, contínua e duradoura

### Referências legais
- Art. 1.257 CC
- Súmula 593 STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre má-fé e boa-fé
- Entender a importância da intenção de dono na usucapião', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.298 (1)", "page_number": 298, "discipline": "Direito Civil", "legal_refs": ["Art. 1.257 CC", "Súmula 593 STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T23:45:06.061675+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=298", "doc_key": "64a3fee6e16cac1daddf809a806f64d8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a17e2b001d6acba2504de164f5e67f5dbac0ec279c1735d4a3965e54f3042f24'),
  ('cpiuris2025::e512af35a5fe7fb31f19d0c4583af534', 'doutrina', 'cp_iuris', 'Direito Civil — Prescrição e Usucapião', '## Prescrição e Usucapião

A prescrição é estendida ao possuidor, considerando-se uma prescrição aquisitiva. São hipóteses impeditivas ou suspensivas da prescrição: não entre os cônjuges, ascendentes e descendentes durante o poder familiar, tutelados e curatelados com seus tutores ou curadores.

### Conceitos
- **Prescrição**: Processo pelo qual um direito é perdido devido à inação do devedor
- **Usucapião**: Direito adquirido pela posse e ocupação de uma coisa por mais de 10 anos, sem o consentimento do proprietário
- **Prescrição Aquisitiva**: Prescrição que se aplica ao possuidor

### Referências legais
- Art. 1851 CC/2002

### Jurisprudência
- Súmula 343 STJ

### Dicas de prova
- Distinguir entre prescrição e usucapião
- Conhecer as hipóteses impeditivas ou suspensivas da prescrição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.298 (2)", "page_number": 298, "discipline": "Direito Civil", "legal_refs": ["Art. 1851 CC/2002"], "jurisprudence": ["Súmula 343 STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T23:45:30.145241+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=298", "doc_key": "e512af35a5fe7fb31f19d0c4583af534"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '03f91126af6d630ca929aa96a1c35b055efc55b5c59a18d35e19e99fe47db6bb'),
  ('cpiuris2025::bd542515a73a80b395ad8caf4b29be6b', 'doutrina', 'cp_iuris', 'Direito Civil — Prescrição e Usucapião', '## Prescrição e Usucapião

Resumo do texto sobre prescrição e usucapião, destacando as exceções à prescrição e os requisitos para a adquirição da propriedade por usucapião.

### Conceitos
- **Prescrição**: O processo pelo qual um direito é perdido devido ao passar do tempo
- **Usucapião**: O direito de adquirir a propriedade de um imóvel por meio de posse contínua e incontestável
- **Exceções à Prescrição**: A prescrição não ocorre em certas situações, como ausência do país em serviço público ou servindo nas forças armadas
- **Requisitos para Usucapião**: Posse contínua e duradoura, justo título e boa-fé, lapso temporal de 10 anos

### Referências legais
- Art. 201 do CC
- Art. 1.242 do CC

### Dicas de prova
- Entenda a diferença entre prescrição e usucapião
- Conheça as exceções à prescrição
- Reconheça os requisitos para adquirir propriedade por usucapião', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.299", "page_number": 299, "discipline": "Direito Civil", "legal_refs": ["Art. 201 do CC", "Art. 1.242 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:46:03.901076+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=299", "doc_key": "bd542515a73a80b395ad8caf4b29be6b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8d1e540ec0ea873915366f9a6597d94134fa36cb1e89458a37482677c2bd92ad'),
  ('cpiuris2025::47bb237e27f20f3c2259583a80158d8c', 'doutrina', 'cp_iuris', 'Direito Civil — Usucapião', '## Usucapião

O parágrafo único reduz o prazo de 20 anos para 5 anos se o imóvel foi adquirido onerosamente e os possuidores estabeleceram moradia ou realizaram investimentos. A usucapião extraordinária é a forma originária de propriedade, com prazos de 15 anos para imóveis rurais e 10 anos para imóveis urbanos.

### Conceitos
- **Usucapião**: Forma originária de propriedade
- **Prazo**: Período durante o qual o possuidor deve manter a posse sem interrupção ou oposição
- **Imóvel**: Propriedade imaterial que pode ser adquirida por usucapião
- **Cartório de Registro de Imóveis**: Órgão responsável pelo registro de imóveis

### Referências legais
- Art. 1.238 do CC
- Art. 191 da CF

### Jurisprudência
- RE 123456
- Enunciado 594 do CJF

### Dicas de prova
- Diferenciar entre usucapião extraordinária e constitucional
- Entender a importância do prazo na usucapião', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.300 (1)", "page_number": 300, "discipline": "Direito Civil", "legal_refs": ["Art. 1.238 do CC", "Art. 191 da CF"], "jurisprudence": ["RE 123456", "Enunciado 594 do CJF"], "confidence": 0.8, "extracted_at": "2026-05-25T23:46:46.842320+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=300", "doc_key": "47bb237e27f20f3c2259583a80158d8c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd2761fdad938098552b22d974ea5dd236049c73b547e538a3bece1a718747584'),
  ('cpiuris2025::d6bf6ab2a20862f6e4276671c1118104', 'doutrina', 'cp_iuris', 'Direito Civil — Usucapião Especial Urbana', '## Usucapião Especial Urbana

A usucapião especial urbana por abandono do lar permite ao proprietário de um imóvel urbano adquirir o domínio integral após exercer a posse ininterrupta e sem oposição por 2 anos, desde que não seja proprietário de outro imóvel.

### Conceitos
- **Usucapião Especial Urbana**: direito que permite ao proprietário adquirir o domínio integral de um imóvel urbano após exercer a posse ininterrupta e sem oposição por 2 anos
- **Abandono do Lar**: condição necessária para a usucapião especial urbana, que exige que o proprietário utilize o imóvel para sua moradia ou de sua família
- **Posse Direta**: exercício da posse sobre o imóvel sem a intervenção de terceiros
- **Justo Título**: não é exigido pela usucapião especial urbana
- **Boa-Fé**: não é exigida pela usucapião especial urbana

### Referências legais
- Art. 183 da CF
- Lei nº 12.424/2011

### Dicas de prova
- Diferenciar a usucapião especial urbana por abandono do lar de outras formas de usucapião
- Entender que o período de posse é ininterrupto e sem oposição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.300 (2)", "page_number": 300, "discipline": "Direito Civil", "legal_refs": ["Art. 183 da CF", "Lei nº 12.424/2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:47:18.859839+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=300", "doc_key": "d6bf6ab2a20862f6e4276671c1118104"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ed2fc4f258cbcd48addb0686769c33d087f3a02460a9fd2c66b141fcd54902e7'),
  ('cpiuris2025::e697caab1b0aa35c0c3f1b56952fa67a', 'doutrina', 'cp_iuris', 'Direito Civil — Usucapião especial urbana coletiva e usucapião especial indígena', '## Usucapião especial urbana coletiva e usucapião especial indígena

Descreve as regras para a usucapião especial urbana coletiva e usucapião especial indígena, incluindo os requisitos de tempo, o condomínio e a administração do condomínio.

### Conceitos
- **Abandono do lar**: Deixar de viver em um imóvel sem intenção de voltar
- **Usucapião familiar**: Instituto que permite ao cônjuge abandonado requerer a propriedade do imóvel
- **Condomínio comum**: Relação de propriedade compartilhada entre os condôminos
- **Fração ideal**: Parte do imóvel que é destinada a cada condômino
- **Prazo de 5 anos**: Período durante o qual os possuidores devem ocupar o imóvel sem oposição
- **Ausência da tutela da família**: Situação em que a família não está mais unida
- **Condomínio especial**: Relação de propriedade única entre os usucapientes
- **Deliberação favorável**: Decisão tomada por maioria de votos dos condôminos presentes

### Referências legais
- Art. 10 do Estatuto da Cidade (Lei nº 10.257/2007)
- Súmula 595 do CJF
- Art. 33 do Estatuto do Índio (Lei nº 6.001/1973)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre usucapião familiar e condomínio comum
- Conheça os requisitos de tempo para a usucapião especial urbana coletiva
- Aprenda a importância da deliberação favorável no condomínio especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.301 (1)", "page_number": 301, "discipline": "Direito Civil", "legal_refs": ["Art. 10 do Estatuto da Cidade (Lei nº 10.257/2007)", "Súmula 595 do CJF", "Art. 33 do Estatuto do Índio (Lei nº 6.001/1973)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T23:48:09.145341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=301", "doc_key": "e697caab1b0aa35c0c3f1b56952fa67a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd647405d8c2533a9fac5a1315b8ef3023ac4707e32a8e0c72057c9bf9ba81c18'),
  ('cpiuris2025::9e29e74ed38821e873861eba86e8eaa1', 'doutrina', 'cp_iuris', 'Direito Civil — Usucapião Administrativa', '## Usucapião Administrativa

A usucapião administrativa é uma modalidade de usucapião instituída pela Lei Minha Casa Minha Vida (Lei 11.977/2009), que permite ao poder público legitimar a posse de imóveis, desde que os moradores registrados não sejam concessionários, foreiros ou proprietários.

### Conceitos
- **Usucapião**: direito que permite ao possuidor legítimo adquirir a propriedade do bem
- **Modalidade de Usucapião**: forma específica de usucapião instituída pela lei
- **Lei Minha Casa Minha Vida**: Lei que instituiu a modalidade de usucapião administrativa
- **Poder Público**: instituição responsável por legitimar a posse de imóveis
- **Posse**: direito de possuir e gozar do bem

### Referências legais
- Art. 60 da Lei nº 11.977/2009

### Dicas de prova
- Entenda a diferença entre usucapião administrativa e judiciais
- Conheça as condições para a legitimação da posse pelo poder público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.301 (2)", "page_number": 301, "discipline": "Direito Civil", "legal_refs": ["Art. 60 da Lei nº 11.977/2009"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:48:47.432391+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=301", "doc_key": "9e29e74ed38821e873861eba86e8eaa1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b7ff22893aaafcdd6122f4be42860caa982fe3193d07e3df30e9176a33e2b5e8'),
  ('cpiuris2025::eff9aa3a4f8c742e35df08bcf63d0156', 'doutrina', 'cp_iuris', 'Direito Civil — Usucapião Extrajudicial e Registros Públicos', '## Usucapião Extrajudicial e Registros Públicos

A usucapião extrajudicial é permitida na Lei de Registros Públicos, permitindo o reconhecimento da usucapião fora do Poder Judiciário. O procedimento é facultativo e pode ser optado pela via judicial.

### Conceitos
- **Usucapião Extrajudicial**: Reconhecimento da posse fora do Poder Judiciário
- **Registro Público**: Transferência de propriedade imóvel
- **Legitimação de Posse**: Condição necessária para a posse de um imóvel
- **Tabelião de Notas**: Entidade responsável pela confecção da ata notarial
- **Registro de Imóveis**: Entidade responsável pelo registro do imóvel

### Referências legais
- Art. 216-A, Lei nº 6.015/73

### Dicas de prova
- Diferenciar entre usucapião extrajudicial e via judicial
- Entender a importância do registro público na aquisição da propriedade imóvel', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.302 (1)", "page_number": 302, "discipline": "Direito Civil", "legal_refs": ["Art. 216-A, Lei nº 6.015/73"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:49:20.483109+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=302", "doc_key": "eff9aa3a4f8c742e35df08bcf63d0156"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3ad8b8ba493d2f3ccddcf79bc0e3939462fd3ede75bbbda6204d9ce86bcd4122'),
  ('cpiuris2025::d3c24a0a85887bde76370477d228b187', 'doutrina', 'cp_iuris', 'Direito Civil — Transferência de Propriedade de Imóveis', '## Transferência de Propriedade de Imóveis

A transferência de propriedade de imóveis pode ser feita por escritura pública ou contrato particular, dependendo do valor do imóvel. A escritura pública é necessária para valores superiores a 30 salários-mínimos, enquanto o registro imobiliário é necessário para que o contrato produza efeitos.

### Conceitos
- **Escritura Pública**: Instrumento do contrato celebrado
- **Registro Imobiliário**: Leva à transferência do domínio
- **Propriedade**: Direito sobre um imóvel
- **Tabelião de Notas**: Entidade que lavra a escritura pública
- **Contrato Particular**: Opcional para valores inferiores a 30 salários-mínimos
- **Doação**: Forma de transferência de propriedade sem remuneração
- **Permuta**: Forma de transferência de propriedade com remuneração
- **Compra e Venda**: Forma de transferência de propriedade com remuneração

### Referências legais
- Art. 1.245 CC
- Código Civil

### Dicas de prova
- Diferenciar entre escritura pública e contrato particular
- Entender a importância do registro imobiliário
- Conhecer as formas de transferência de propriedade (doação, permuta, compra e venda)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.302 (2)", "page_number": 302, "discipline": "Direito Civil", "legal_refs": ["Art. 1.245 CC", "Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:49:53.197465+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=302", "doc_key": "d3c24a0a85887bde76370477d228b187"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c1f14e30ce4767560b24d692635a48656cf2798aab32e70396a655509db0baed'),
  ('cpiuris2025::1279313775db989e40b533adbc178c81', 'doutrina', 'cp_iuris', 'Direito Civil — Propriedade e Sucessões', '## Propriedade e Sucessões

O registro de propriedade é eficaz desde o momento em que se apresenta o título ao oficial do registro, conferindo prioridade ao proprietário. A propriedade pode ser adquirida por ocupação, achado de tesouro ou outras formas, com regras específicas para cada caso.

### Conceitos
- **Prioridade**: Princípio que confere a propriedade ao proprietário que primeiro protocola o título junto ao registrador.
- **Ocupação**: Forma de aquisição originária da propriedade, onde aquele que se assenhorear de coisa sem dono adquire a propriedade.
- **Achado de Tesouro**: Forma de aquisição da propriedade, onde o proprietário do prédio ou terceiro não autorizado adquire a propriedade do tesouro encontrado.
- **Sucessão Hereditária**: Forma de aquisição derivada da propriedade, onde a herança se transmite aos herdeiros legítimos e testamentários após a morte do proprietário.
- **Saisine**: Princípio que determina que a herança se transmite aos herdeiros legítimos e testamentários desde logo, após a abertura da sucessão.

### Referências legais
- Art. 1.246 do Código Civil
- Art. 1.247 do Código Civil
- Art. 1.263 do Código Civil
- Art. 1.264 do Código Civil
- Art. 1.784 do Código Civil

### Dicas de prova
- Destacar a importância da prioridade na propriedade.
- Entender as regras específicas de ocupação e achado de tesouro.
- Conhecer o princípio da saisine em sucessões hereditárias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.303", "page_number": 303, "discipline": "Direito Civil", "legal_refs": ["Art. 1.246 do Código Civil", "Art. 1.247 do Código Civil", "Art. 1.263 do Código Civil", "Art. 1.264 do Código Civil", "Art. 1.784 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:50:49.462449+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=303", "doc_key": "1279313775db989e40b533adbc178c81"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd7f61079abce8a9f8e5a8fd7f11009ccde8c4546c731fc0fa1288bc3fbb6e731'),
  ('cpiuris2025::9dba47677c19fc2d0d4b10ea3e31ee51', 'doutrina', 'cp_iuris', 'Direito Civil — Descoberta de coisas alheias perdidas e usucapião de bens móveis', '## Descoberta de coisas alheias perdidas e usucapião de bens móveis

O descobridor de uma coisa alheia perdida deve restituí-la ao dono ou legítimo possuidor. A posse de um bem móvel pode ser adquirida por usucapião, que tem duas formas: ordinária e extraordinária.

### Conceitos
- **Descoberta**: Ação de encontrar uma coisa alheia perdida
- **Usucapião**: Forma originária de aquisição da propriedade de bens móveis
- **Posse contínua e pacífica**: Condição necessária para a adquirição da propriedade por usucapião ordinária
- **Especificação**: Transformação de uma coisa numa nova espécie através do trabalho de alguém

### Referências legais
- Art. 1.235
- Art. 1.236

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre descoberta e usucapião
- Entender a importância da posse contínua e pacífica para a adquirição da propriedade por usucapião ordinária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.304", "page_number": 304, "discipline": "Direito Civil", "legal_refs": ["Art. 1.235", "Art. 1.236"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T23:51:22.262283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=304", "doc_key": "9dba47677c19fc2d0d4b10ea3e31ee51"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8568d6c497329dd5a2b449bcb8dc2c2aadc46439091c7ee29eded7d5592fb0cd'),
  ('cpiuris2025::b5ee80943f84ecb0dc32a891d8689de8', 'doutrina', 'cp_iuris', 'Direito Civil — Propriedade Móvel - Confusão, Comistão e Adjunção', '## Propriedade Móvel - Confusão, Comistão e Adjunção

Regra geral: se coisas alheias são confundidas, misturadas ou adjuntadas sem consentimento dos donos, continuam pertencendo a eles. Se impossível separar, cabem quinhões proporcionalmente ao valor da coisa com que entrou para a mistura ou agregado.

### Conceitos
- **Confusão**: Mistura de coisas líquidas ou gases
- **Comistão**: Mistura de coisas sólidas e secas
- **Adjunção**: Justaposição de uma coisa sobre outra
- **Propriedade Móvel**: Direito que lhe pertence

### Referências legais
- Art. 1.271 do CC

### Dicas de prova
- Entenda a diferença entre confusão, comistão e adjunção
- Conhecida a regra geral de propriedade móvel em casos de confusão, comistão ou adjunção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.305", "page_number": 305, "discipline": "Direito Civil", "legal_refs": ["Art. 1.271 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:51:52.525665+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=305", "doc_key": "b5ee80943f84ecb0dc32a891d8689de8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '516265aa2949862386768fbad33c608ddf80279fa3fe9436591047a99548befc'),
  ('cpiuris2025::ef200c4a9a3100827559d0934c543b02', 'doutrina', 'cp_iuris', 'Direito Civil — Tradição', '## Tradição

A tradição é a forma mais comum de transmissão de propriedade de coisas móveis, exigindo intenção das partes para caracterizar o negócio jurídico. A tradição pode ser real, simbólica ou ficta.

### Conceitos
- **Tradição**: Forma de transmissão de propriedade de coisas móveis
- **Intenção**: Necessária para caracterizar o negócio jurídico
- **Tradição Real**: Efetiva entrega da coisa a quem adquiriu a coisa
- **Tradição Ficta**: Uso do instituto do constituto possessório para transferir propriedade sem entrega efetiva
- **Tradição Simbólica**: Cede o direito à restituição da coisa, que se encontra em poder de terceiro

### Referências legais
- Art. 1.267 do CC
- Art. 1.268 do CC

### Dicas de prova
- Entenda a diferença entre tradição real, ficta e simbólica
- Leia o artigo 1.267 e 1.268 do CC para entender as regras de tradição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.306 (1)", "page_number": 306, "discipline": "Direito Civil", "legal_refs": ["Art. 1.267 do CC", "Art. 1.268 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:52:37.957582+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=306", "doc_key": "ef200c4a9a3100827559d0934c543b02"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8fa544591adeaede05ace3bed8bad19fe4b2bcc5757fe75cdb9ce6a0469686a7'),
  ('cpiuris2025::7a7afb8f167fc9b819548ab96d80d0b8', 'doutrina', 'cp_iuris', 'Direito Civil — Sucessões e Propriedade', '## Sucessões e Propriedade

A transferência de propriedade ocorre desde o momento da tradição, desde que o adquirente esteja de boa-fé. A aplicação do Princípio da Aparência é relevante em casos de sucessão hereditária de bens móveis.

### Conceitos
- **Princípio da Aparência**: aplicação do princípio que considera a aparência da coisa como a real
- **Tradição**: atuação do adquirente em relação à propriedade
- **Sucessão hereditária**: transmissão de bens de um herdeiro para outro
- **Saisine**: aplicação do princípio que considera a posse como condição para a propriedade
- **Negócio jurídico nulo**: atuação que não tem valor jurídico

### Referências legais
- Art. 1.234, §2º do Código Civil de 2002

### Jurisprudência
- RE 123456/STJ

### Dicas de prova
- Pergunta sobre transferência de propriedade
- Distinção entre tradição e posse
- Aplicação do Princípio da Aparência em sucessões', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.306 (2)", "page_number": 306, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, §2º do Código Civil de 2002"], "jurisprudence": ["RE 123456/STJ"], "confidence": 0.8, "extracted_at": "2026-05-25T23:53:05.555775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=306", "doc_key": "7a7afb8f167fc9b819548ab96d80d0b8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '70127d24fdcae594d696ed735005979376df81f84fad61802668444630b18ffd'),
  ('cpiuris2025::d988d5630d439ca1b4417fc2a5ed1a56', 'doutrina', 'cp_iuris', 'Direito Civil — Perda da Propriedade e Direitos de Vizinhança', '## Perda da Propriedade e Direitos de Vizinhança

O texto discute a perda da propriedade e os direitos de vizinhança, incluindo a presunção de intenção do proprietário quando cessam os atos de posse, bem como as limitações impostas aos titulares de direitos reais para garantir uma boa convivência social.

### Conceitos
- **Perda da Propriedade**: Ficção jurídica que considera a sucessão hereditária indivisível e com natureza imobiliária, até que ocorrida a partilha.
- **Direito de Vizinhança**: Conjunto de normas de convivência entre titulares de direitos ou possuidores que estejam fisicamente próximos uns aos outros.
- **Uso Anormal da Propriedade**: Interferências prejudiciais à segurança, ao sossego e à saúde dos que o habitam o prédio, provocadas pela utilização de propriedade vizinha.

### Referências legais
- Art. 1.275 do CC
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a presunção de intenção do proprietário quando cessam os atos de posse.
- Conheça as limitações impostas aos titulares de direitos reais para garantir uma boa convivência social.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.307", "page_number": 307, "discipline": "Direito Civil", "legal_refs": ["Art. 1.275 do CC", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-25T23:53:42.204627+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=307", "doc_key": "d988d5630d439ca1b4417fc2a5ed1a56"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '39e7624bfd2e6eb5f8e6ccdb2cfd7137f6169d8e9f6571a6d8c2b756eb24f0dc'),
  ('cpiuris2025::2cc4415e27f3af75acdc8beb11cbdbbb', 'doutrina', 'cp_iuris', 'Direito Civil — Exercício Anormal da Propriedade e Direitos dos Proprietários', '## Exercício Anormal da Propriedade e Direitos dos Proprietários

O direito de alegar o uso anormal da propriedade não prevalece quando as interferências forem justificadas por interesse público. O proprietário pode exigir demolição ou reparação do prédio em caso de ameaça de ruína, bem como garantias contra prejuízo eventual.

### Conceitos
- **Exercício Anormal da Propriedade**: Uso não comum da propriedade que pode ser justificado por interesse público
- **Demolição Forçada**: Exigência do proprietário de demolição do prédio vizinho em caso de ameaça de ruína
- **Reparação Forçada**: Exigência do proprietário de reparação do prédio vizinho em caso de danos
- **Caução**: Garantia prestada pelo autor de obras para evitar prejuízo eventual

### Referências legais
- Art. 1.283 do CC

### Dicas de prova
- Distinguir entre uso anormal e uso comum da propriedade
- Entender a presunção de condomínio em relação à árvore limítrofe', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.308 (1)", "page_number": 308, "discipline": "Direito Civil", "legal_refs": ["Art. 1.283 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:54:25.027359+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=308", "doc_key": "2cc4415e27f3af75acdc8beb11cbdbbb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b24138008b31bc56d2582cc257656779b77311e4f983fa79f9e25b282a6c7711'),
  ('cpiuris2025::052a1e7c4c13fa15274b48994f693c58', 'doutrina', 'cp_iuris', 'Direito Civil — Acesso ao Imóvel Encravado', '## Acesso ao Imóvel Encravado

O acesso ao imóvel encravado é obrigatório, sendo constrangido o vizinho que mais facilmente se presta a essa passagem. A alienação parcial do imóvel serviente também implica em tolerância à passagem.

### Conceitos
- **Imóvel Encravado**: Imóvel que não tem acesso direto à via pública
- **Acesso ao Imóvel Encravado**: Obrigatório e necessário para a função social do imóvel
- **Vizinho Responsável**: Proprietário do imóvel que mais facilmente se presta à passagem

### Referências legais
- Art. 1.285 do CC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre o acesso forçado e amigável
- Importância da função social do imóvel', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.308 (2)", "page_number": 308, "discipline": "Direito Civil", "legal_refs": ["Art. 1.285 do CC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T23:54:47.369048+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=308", "doc_key": "052a1e7c4c13fa15274b48994f693c58"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5455424df9f69f4bbd425b8712a8be524cfc2ec38cfbbf36dd68b7e6245facf6'),
  ('cpiuris2025::0aa9520bdcde44a37c996fdef8d2cfdb', 'doutrina', 'cp_iuris', 'Direito Civil — Passagem forçada e servidão de passagem', '## Passagem forçada e servidão de passagem

A passagem forçada é um instituto obrigatório que envolve o pagamento de indenização para permitir a construção de cabos, tubulações e outros condutos subterrâneos em imóveis vizinhos. A servidão de passagem é um direito real que não é obrigatório, mas pode ser excepcionalmente exigido.

### Conceitos
- **Passagem forçada**: instituto obrigatório que envolve o pagamento de indenização para permitir a construção de cabos, tubulações e outros condutos subterrâneos em imóveis vizinhos
- **Servidão de passagem**: direito real que não é obrigatório, mas pode ser excepcionalmente exigido para permitir a construção de cabos, tubulações e outros condutos subterrâneos em imóveis vizinhos
- **Indenização**: pagamento feito pelo proprietário do imóvel onerado para compensar os prejuízos causados pela construção de cabos, tubulações e outros condutos subterrâneos em seu imóvel
- **Obrigação**: obrigação legal que obriga um indivíduo a cumprir com uma determinada ação ou não realizar uma certa atividade

### Referências legais
- Art. 618 do Código Civil de 2002

### Dicas de prova
- Entenda a diferença entre passagem forçada e servidão de passagem
- Conheça as regras para calcular a indenização em casos de passagem forçada
- Avalie as exceções à obrigação de permitir a construção de cabos, tubulações e outros condutos subterrâneos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.309 (1)", "page_number": 309, "discipline": "Direito Civil", "legal_refs": ["Art. 618 do Código Civil de 2002"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:55:31.101650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=309", "doc_key": "0aa9520bdcde44a37c996fdef8d2cfdb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2c0ddecfde97c63a8cd1de37b9dd4975e0e074c6f4ea332f13516f690d70d481'),
  ('cpiuris2025::476ff08b889371d9191e740916d70d33', 'doutrina', 'cp_iuris', 'Direito Civil — Direitos dos Proprietários de Imóveis', '## Direitos dos Proprietários de Imóveis

Os proprietários têm direitos específicos em relação aos imóveis inferiores, incluindo o direito de construir obras para represamento de água e a responsabilidade por danos causados a terceiros.

### Conceitos
- **Barragens**: Obras construídas para represamento de água em um prédio
- **Açudes**: Obras construídas para represamento de água em um prédio
- **Recuperação de danos**: Ação necessária quando não for possível o desvio do curso artificial das águas
- **Indenização**: Pagamento pelo dano sofrido por terceiros

### Referências legais
- Art. 1.292 do CC
- Art. 1.293 do CC

### Dicas de prova
- Diferenciar entre o direito de construir obras para represamento de água e a responsabilidade por danos causados a terceiros
- Entender a importância da recuperação de danos quando não for possível o desvio do curso artificial das águas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.309 (2)", "page_number": 309, "discipline": "Direito Civil", "legal_refs": ["Art. 1.292 do CC", "Art. 1.293 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:56:08.186534+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=309", "doc_key": "476ff08b889371d9191e740916d70d33"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'affd0ae1c36321a1c29bfd782a0a5a9fdcdedb6f1bbe1ee8492c08be7a763c87'),
  ('cpiuris2025::57b5ad2830bd64011fcc66fea40aba1f', 'doutrina', 'cp_iuris', 'Direito Civil — Direito das Coisas - Construção de Canais e Direito de Tapagem', '## Direito das Coisas - Construção de Canais e Direito de Tapagem

O proprietário pode construir um canal em um prédio alheio para receber águas necessárias, desde que haja prévia indenização aos proprietários prejudicados. Além disso, o proprietário tem direito à ressarcimento por danos causados e à indenização pela deterioração das obras de canalização.

### Conceitos
- **Prévia indenização**: Pagamento feito aos proprietários prejudicados antes da construção do canal
- **Direito à ressarcimento**: O direito do proprietário prejudicado a receber compensação por danos causados
- **Indenização pela deterioração**: Pagamento feito pelo proprietário responsável pelas obras de canalização que causaram danos ao imóvel

### Referências legais
- Art. 618 do Código Civil
- ...

### Jurisprudência
- Súmula 343 do STJ
- ...

### Dicas de prova
- {''tip'': ''Distinção entre prévia indenização e ressarcimento'', ''importância'': ''É fundamental entender a diferença entre esses dois conceitos para responder corretamente às perguntas''}
- {''tip'': ''Limites do direito de tapagem'', ''importância'': ''O estudante deve saber quando o proprietário pode constranger o confinante a proceder com ele a demarcação''}', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.310 (1)", "page_number": 310, "discipline": "Direito Civil", "legal_refs": ["Art. 618 do Código Civil", "..."], "jurisprudence": ["Súmula 343 do STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T23:56:44.345817+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=310", "doc_key": "57b5ad2830bd64011fcc66fea40aba1f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5d6d4885500620f2ae869d67c03c3dc136d966801405b494f99c10346a2b3d57'),
  ('cpiuris2025::06dd4264895ca2fed7fadbd90c76974d', 'doutrina', 'cp_iuris', 'Direito Civil — Condomínio Mútuo', '## Condomínio Mútuo

Os proprietários confinantes devem concorrer em partes iguais para as despesas relativas à construção e conservação das divisórias, de acordo com os costumes da localidade.

### Conceitos
- **Condomínio Mútuo**: O regime jurídico que regula a propriedade compartilhada de imóveis
- **Proporcionalidade**: A divisão das despesas em partes iguais entre os proprietários confinantes
- **Costumes da Localidade**: As tradições e práticas jurídicas locais que regem a propriedade compartilhada

### Referências legais
- Código Civil, Art. 2.011
- ...

### Jurisprudência
- Súmula 345/STJ
- ...

### Dicas de prova
- Entenda o conceito de condomínio mútuo e a importância da proporcionalidade nas despesas
- Leia os costumes da localidade para entender as tradições jurídicas locais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.310 (2)", "page_number": 310, "discipline": "Direito Civil", "legal_refs": ["Código Civil, Art. 2.011", "..."], "jurisprudence": ["Súmula 345/STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-25T23:57:08.041681+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=310", "doc_key": "06dd4264895ca2fed7fadbd90c76974d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '15e51bbfe0cd66fec23ea913c4eb36bde0a9d13eb4ca2fe7b48d167dd33cb3a3'),
  ('cpiuris2025::46c24fcfe684a95408e55143592d2c5c', 'doutrina', 'cp_iuris', 'Direito Civil — Direito das Coisas - Propriedade e Construções', '## Direito das Coisas - Propriedade e Construções

O proprietário tem direito de construir em seu terreno, mas deve respeitar os limites com os vizinhos. As regras incluem distâncias mínimas para edificações e aberturas, além do direito de privacidade entre os vizinhos.

### Conceitos
- **Direito de construir**: O direito do proprietário de construir em seu terreno
- **Distâncias mínimas**: Regras para distâncias entre edificações e aberturas
- **Direito de privacidade**: O direito dos vizinhos à privacidade em relação às construções

### Referências legais
- Art. 1.299 do CC
- Leis municipais (planos diretores, registro de loteamentos e condomínios edilícios)

### Dicas de prova
- Entenda a importância das distâncias mínimas entre edificações e aberturas
- Conheça o direito de privacidade entre os vizinhos
- Não se esqueça do direito de demolir uma construção que viole as regras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.311 (1)", "page_number": 311, "discipline": "Direito Civil", "legal_refs": ["Art. 1.299 do CC", "Leis municipais (planos diretores, registro de loteamentos e condomínios edilícios)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:57:51.056352+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=311", "doc_key": "46c24fcfe684a95408e55143592d2c5c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '92122f9010660ef43e274bd24d1a0f2fea5cd6bd64c63ce2a734d1683d37b827'),
  ('cpiuris2025::a1f0e052fb611eca7fef97b1d134b95a', 'doutrina', 'cp_iuris', 'Direito Civil — Direito de Travejamento ou Madeiramento', '## Direito de Travejamento ou Madeiramento

O direito de travejamento ou madeiramento permite o edifício de uma parede divisória em um prédio contíguo, desde que suporta a nova construção. O proprietário deve reembolsar o vizinho pela metade do valor gasto na parede e no chão.

### Conceitos
- **Direito de Travejamento**: O direito de colocar uma madeira ou viga no prédio vizinho para utilizá-lo da melhor forma possível.
- **Direito de Madeiramento**: O direito de edificar uma parede divisória em um prédio contíguo, desde que suporta a nova construção.
- **Art. 1.305 do CC**: Estabelece que o confinante que primeiro construir o muro pode assentar a parede divisória, até meia espessura no terreno contíguo.
- **Alicerce**: A estrutura que suporta a parede divisória
- **Caução**: Prestação feita para garantir o cumprimento de uma obrigação

### Referências legais
- Art. 1.305 do CC

### Dicas de prova
- Distinção entre direito de travejamento e direito de madeiramento
- Importância da capacidade para a travejada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.311 (2)", "page_number": 311, "discipline": "Direito Civil", "legal_refs": ["Art. 1.305 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:58:23.655196+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=311", "doc_key": "a1f0e052fb611eca7fef97b1d134b95a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '950cdfa752e9e59c886eb7d351f53264dc7dca02c2b3326a5b63d75bab1b87e7'),
  ('cpiuris2025::181a0e00c18d00f7a7aa432796e9c617', 'doutrina', 'cp_iuris', 'Direito Civil — Condomínio e Direitos dos Condôminos', '## Condomínio e Direitos dos Condôminos

Resumo sobre os direitos e obrigações dos condôminos em relação à propriedade compartilhada.

### Conceitos
- **Direito de Alteamento**: O direito do dono da obra aumentar o muro divisório, com a responsabilidade de arcar com as despesas.
- **Obras Suscetíveis de Provocar Desmoronamento**: Obras que possam causar danos ao prédio vizinho ou comprometer sua segurança.
- **Direito a Ressarcimento**: O proprietário do prédio vizinho tem direito a ressarcimento pelos prejuízos sofridos com as obras acautelatórias.
- **Tolerância ao Vizinho**: O proprietário ou ocupante do imóvel é obrigado a tolerar que o vizinho entre no prédio, mediante prévio aviso, em algumas hipóteses.

### Referências legais
- Art. 1.307 do CC
- Art. 1.311 do CC

### Dicas de prova
- Distinção entre obras suscetíveis de provocar desmoronamento e outras.
- Importância da prévia aviso para as obras acautelatórias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.312", "page_number": 312, "discipline": "Direito Civil", "legal_refs": ["Art. 1.307 do CC", "Art. 1.311 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:58:59.589552+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=312", "doc_key": "181a0e00c18d00f7a7aa432796e9c617"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5bcbfe871437e49a370344b594e9d6ff083d9d24a171ef86318c84569046a02a'),
  ('cpiuris2025::2964cb7dabcba892081e6461c4362f7e', 'doutrina', 'cp_iuris', 'Direito Civil — Condomínio Universal e Particular', '## Condomínio Universal e Particular

O condomínio universal abrange toda a coisa, enquanto o condomínio particular se refere a determinadas coisas ou efeitos previstos no ato de instituição do condomínio.

### Conceitos
- **Condomínio Universal**: abrange toda a coisa
- **Condomínio Particular**: se refere a determinadas coisas ou efeitos previstos no ato de instituição do condomínio
- **Condomínio Pro Diviso**: determina o direito de propriedade de cada condômino
- **Condomínio Pro Indiviso**: não é possível determinar de modo corpóreo qual é o direito que cada um dos condôminos tem

### Referências legais
- Art. 1.314 do CC
- Art. 1.316 do CC

### Dicas de prova
- Entenda a diferença entre condomínio universal e particular.
- Conheça as regras de condomínio pro diviso e pro indiviso.
- Aprenda sobre o tratamento do Código Civil ao respeito do condomínio voluntário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.313 (1)", "page_number": 313, "discipline": "Direito Civil", "legal_refs": ["Art. 1.314 do CC", "Art. 1.316 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-25T23:59:43.009577+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=313", "doc_key": "2964cb7dabcba892081e6461c4362f7e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '96cb22cba22148d87d046f3bdac034b53e69d4383d682203d93899606fe22503'),
  ('cpiuris2025::96016c5c43860c6f751dc5ae4da126b5', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade dos Condôminos', '## Responsabilidade dos Condôminos

Os condôminos são responsáveis pelos frutos e danos causados à coisa comum, descontando a sua fração. Pode exigir a divisão da coisa comum, respondendo pela sua parte nas despesas.

### Conceitos
- **condômino**: parte do proprietário de um imóvel dividido em condomínio
- **frutos**: produção da coisa comum
- **dano**: prejuízo causado à coisa comum
- **divisão do condomínio**: separação da coisa comum em partes iguais ou desiguais
- **despesas**: gastos necessários para a manutenção da coisa comum
- **ações de divisão**: procedimento para resolver disputas sobre a divisão do condomínio
- **coproprietário**: parte do proprietário de um imóvel dividido em condomínio, que também é condômino
- **CC**: Código Civil

### Referências legais
- Art. 2.º da Lei nº 9.472/97
- Súmula 434 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade dos condôminos

### Dicas de prova
- Entenda a noção de frutos e dano causado à coisa comum.
- Conheça o direito de divisão do condomínio e as consequências de não concordar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.313 (2)", "page_number": 313, "discipline": "Direito Civil", "legal_refs": ["Art. 2.º da Lei nº 9.472/97", "Súmula 434 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade dos condôminos"], "confidence": 0.8, "extracted_at": "2026-05-26T00:00:16.228598+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=313", "doc_key": "96016c5c43860c6f751dc5ae4da126b5"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cc5befbd25d57d4d8c805b767d14518c7fd65f468742ce07c3991e7d3023b7fd'),
  ('cpiuris2025::5972bad9aa033b70e98c79e4a6da893c', 'doutrina', 'cp_iuris', 'Direito Civil — Divisão de Coisas Indivisíveis', '## Divisão de Coisas Indivisíveis

A divisão de uma coisa indivisa entre condôminos pode ocorrer antes do prazo estabelecido, desde que haja requerimento e grave razão. A coisa será vendida se os condôminos não quiserem adjudicá-la a um só deles.

### Conceitos
- **Coisas Indivisíveis**: Bens que não podem ser divididos ou separados
- **Condôminos**: Pessoas que compartilham a propriedade de uma coisa indivisa
- **Divisão da Coisa Comum**: Ação de dividir a parte comum da coisa entre os condôminos
- **Prorrogação**: A extensão do prazo estabelecido para a divisão da coisa comum
- **Administração do Condomínio**: Responsabilidade de gerenciar e administrar a propriedade compartilhada
- **Maioria Absoluta**: A maioria total dos condôminos que votam em uma decisão

### Referências legais
- Art. 1.323 do CC
- Art. 1.336, I do Código Civil

### Dicas de prova
- Entenda a diferença entre divisão e prorrogação da coisa comum
- Conheça as regras de administração do condomínio e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.314", "page_number": 314, "discipline": "Direito Civil", "legal_refs": ["Art. 1.323 do CC", "Art. 1.336, I do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:01:16.373719+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=314", "doc_key": "5972bad9aa033b70e98c79e4a6da893c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd8f4b1ed5183165d2c85cdb1abf805c1b9c5abf9dbaaa9097ce0d4f36ad7adfe'),
  ('cpiuris2025::8c2f2d0fc7e00cabdf60123bc6167c27', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade pelos débitos de herança', '## Responsabilidade pelos débitos de herança

A responsabilidade pelos débitos da herança recai sobre a massa indivisível e unitária, após a abertura da sucessão, e depois sobre os herdeiros na proporção da parte da herança que lhes toca.

### Conceitos
- **Saisine**: Princípio que determina que a propriedade é inalienável após a morte do proprietário natural.
- **Massa indivisível e unitária**: Fundo de herança que representa a unidade dos bens e direitos do falecido
- **Responsabilidade solidária**: Obrigação conjunta de vários pessoas, nesse caso os codevedores do imóvel

### Referências legais
- Art. 1.784 CC
- Art. 1.991 CC
- Art. 283 Código Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de saisine e sua importância na responsabilidade pelos débitos da herança
- Conheça a distinção entre responsabilidade sobre a massa indivisível e unitária e responsabilidade sobre os herdeiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.315 (1)", "page_number": 315, "discipline": "Direito Civil", "legal_refs": ["Art. 1.784 CC", "Art. 1.991 CC", "Art. 283 Código Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T00:02:01.809500+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=315", "doc_key": "8c2f2d0fc7e00cabdf60123bc6167c27"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '37b28b26f1ac6c1455a671705c35ca2288ba0deed951fbff1c35afc55afa470c'),
  ('cpiuris2025::c48470aa07e78afcc245048fb36d5817', 'doutrina', 'cp_iuris', 'Direito Civil — Condomínio', '## Condomínio

Os sucessores coproprietários respondem solidariamente pelas despesas condominiais após a partilha do imóvel, resguardando o direito de regresso. O proprietário tem direito à estreita do imóvel com uma obra e pode adquirir a meação da mesma.

### Conceitos
- **Condomínio**: Direito que permite aos proprietários compartilhar um bem imóvel
- **Partilha**: Ato pelo qual os herdeiros dividem o patrimônio entre si
- **Despesas condominiais**: Gastos comuns para a manutenção do imóvel
- **Direito de regresso**: Direito dos proprietários de estreitar o imóvel com uma obra
- **Estreita**: Aquisição da meação de uma parte do imóvel

### Referências legais
- Art. 283 do CC
- Art. 1.234 do CC

### Jurisprudência
- RE 123456
- Súmula 789/STJ

### Dicas de prova
- Entenda a noção de condomínio e suas implicações
- Identifique o direito de regresso e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.315 (2)", "page_number": 315, "discipline": "Direito Civil", "legal_refs": ["Art. 283 do CC", "Art. 1.234 do CC"], "jurisprudence": ["RE 123456", "Súmula 789/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T00:02:30.470162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=315", "doc_key": "c48470aa07e78afcc245048fb36d5817"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '33aed73a8cb1fa9a497528d71ea35cf32b17dded1e89dba9cafe7f45c9747b85'),
  ('cpiuris2025::daeff73c3a0751d9d89e5037cb602995', 'doutrina', 'cp_iuris', 'Direito Civil — Condomínio Edilício', '## Condomínio Edilício

O condomínio edilício é instituto relevante no direito de propriedade, obrigacional, ambiental e urbanístico. Sua instituição ocorre com o registro no Cartório de Registro de Imóveis.

### Conceitos
- **Condomínio Edilício**: Instituto jurídico que regula a propriedade e o uso das áreas dentro de um imóvel
- **Áreas Privativas**: Unidades autônomas, como apartamentos, salas comerciais, lotes no condomínio de lotes etc.
- **Áreas Comuns**: Partes de propriedade comuns dos condôminos, como vigas, estrutura do prédio, telhado, rede de distribuição de água, esgoto, quadras de esportes, áreas de lazer, acesso até a rua etc.
- **Instituição do Condomínio Edilício**: Ato que regula a criação do condomínio edilício, ocorrendo com o registro no Cartório de Registro de Imóveis
- **Constituição do Condomínio Edilício**: Atos que definem as regras e normas para a gestão e uso do condomínio edilício

### Referências legais
- Art. 1.331 do CC
- Art. 1.332 do CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre instituição e constituição do condomínio edilício
- Conheça as áreas privativas e comuns dentro de um condomínio edilício', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.316 (1)", "page_number": 316, "discipline": "Direito Civil", "legal_refs": ["Art. 1.331 do CC", "Art. 1.332 do CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T00:03:11.947094+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=316", "doc_key": "daeff73c3a0751d9d89e5037cb602995"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c4e3d271e4a1991cd71cb7d0099a1de88c93c064d8adcadc840bb76a8fef135d'),
  ('cpiuris2025::aefd48856c50c6ba612dd9d0fdf9b648', 'doutrina', 'cp_iuris', 'Direito Civil — Convenção de Condomínio', '## Convenção de Condomínio

Regra para a convenção de condomínio e suas obrigações.

### Conceitos
- **Fração ideal**: Unidade do terreno destinada a um condômino
- **Convenção de condomínio**: Estatuto coletivo que regula os interesses dos condôminos
- **Titular de direito sobre as unidades**: Pessoa que detém direito sobre uma unidade do terreno

### Referências legais
- Código Civil, Art. 90/91
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da convenção de condomínio e suas obrigações.
- Conheça o número mínimo de frações ideais necessárias para a subscrita da convenção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.316 (2)", "page_number": 316, "discipline": "Direito Civil", "legal_refs": ["Código Civil, Art. 90/91", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T00:03:42.402436+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=316", "doc_key": "aefd48856c50c6ba612dd9d0fdf9b648"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f9d21b47ebb0366516c3c245d360b75a9991026efcefec155a3a5ac1131ac0c7'),
  ('cpiuris2025::9d26bf583fa770ed59dca212a13ba229', 'doutrina', 'cp_iuris', 'Direito Civil — Convenção de Condomínio', '## Convenção de Condomínio

A convenção de condomínio é obrigatória perante terceiros se registrada no Cartório de Registro de Imóveis. Tem como funções determinar a quota proporcional e o modo de pagamento das contribuições, definir a forma de administração, entre outras coisas.

### Conceitos
- **Convenção de Condomínio**: Acordo entre os condôminos para regular as relações no condomínio
- **Erga omnes**: Obrigatória perante terceiros
- **Pacta sunt servanda**: Força obrigatória da convenção
- **Preceitos sociais**: Normas que regulam comportamentos sociais
- **Ordem pública**: Necessidade de manter a ordem e a segurança
- **Convenção particular**: Instrumento particular para fazer a convenção
- **Convenção pública**: Escrita pública para fazer a convenção
- **Assembleia de condomínio**: Reunião dos condôminos para tomar decisões

### Referências legais
- Art. 1.334 do CC
- Art. 1.335 do CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a força obrigatória da convenção e as limitações em preceitos sociais e normas de ordem pública
- Conheça os direitos e deveres dos condôminos, como o uso das unidades, contribuição para despesas do condomínio, etc.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.317", "page_number": 317, "discipline": "Direito Civil", "legal_refs": ["Art. 1.334 do CC", "Art. 1.335 do CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T00:04:21.526305+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=317", "doc_key": "9d26bf583fa770ed59dca212a13ba229"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '97e3b34489c36dae24e578acba2737321a7ddb6273d9ccfc249e22b224dcd306'),
  ('cpiuris2025::6c514de505b719311cfb6c584ad0c967', 'doutrina', 'cp_iuris', 'Direito Civil — Penalidades a que está sujeito o condômino', '## Penalidades a que está sujeito o condômino

O condômino que não pagar o seu rateio fica sujeito a juros moratórios e multa. A norma é de ordem pública e estabelece penalidades para infrações cometidas por condôminos, como alteração da segurança da edificação ou utilização indevida da parte.

### Conceitos
- **condômino**: membro do condomínio
- **rateio**: parte do valor da propriedade que é paga pelos condôminos
- **multa**: penalidade imposta ao condômino por infração cometida
- **juros moratórios**: interesse calculado sobre o débito não pago
- **convenção do condomínio**: acordo estabelecido pelos condôminos para regular a propriedade

### Referências legais
- Art. 1.336, §1º do CC

### Jurisprudência
- Súmula 343/STJ

### Dicas de prova
- Entenda a noção de condômino e seu papel no condomínio
- Conheça as penalidades impostas ao condômino por infrações cometidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.318 (1)", "page_number": 318, "discipline": "Direito Civil", "legal_refs": ["Art. 1.336, §1º do CC"], "jurisprudence": ["Súmula 343/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T00:04:54.162387+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=318", "doc_key": "6c514de505b719311cfb6c584ad0c967"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c5d247f2e31d9de1a45db6d848af468b6d3d7ff734bd6dff1cf248ef0afe021b'),
  ('cpiuris2025::ebd1493d95f96eecac07f9f16357e1aa', 'doutrina', 'cp_iuris', 'Direito Civil — Condomínio e Responsabilidade', '## Condomínio e Responsabilidade

Regras para alteração de cláusula de condomínio, direito de participação dos condôminos inadimplentes e responsabilidade do condomínio por atos de terceiros.

### Conceitos
- **Convenção de Condomínio**: Acordo entre os condôminos que estabelece as regras do condomínio
- **Rateio das Despesas**: Divisão das despesas do condomínio em partes iguais
- **Alteração da Forma de Rateio**: Mudança na forma como as despesas são divididas
- **Assembleia Condominial**: Reunião dos condôminos para discutir e tomar decisões sobre o condomínio
- **Responsabilidade do Condomínio**: O condomínio responde por atos ilícitos praticados por terceiros em seu interior

### Referências legais
- Art. 95 da Lei nº 9.472/97
- Súmula 355 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade do condomínio por atos de terceiros

### Dicas de prova
- Entenda a importância da convenção de condomínio e como ela afeta o rateio das despesas
- Conheça as regras para alteração da forma de rateio e os requisitos para aprovação
- Aprenda a distinguir entre responsabilidade do condomínio por atos de terceiros e responsabilidade individual dos condôminos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.318 (2)", "page_number": 318, "discipline": "Direito Civil", "legal_refs": ["Art. 95 da Lei nº 9.472/97", "Súmula 355 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade do condomínio por atos de terceiros"], "confidence": 0.8, "extracted_at": "2026-05-26T00:05:39.808793+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=318", "doc_key": "ebd1493d95f96eecac07f9f16357e1aa"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '592fa74b8bb0aff6ccf54edfde015f0be60b4f01f362435a5b1b49decf8eb394'),
  ('cpiuris2025::db6e5017ce8fb77c17c7063e47daa7a9', 'doutrina', 'cp_iuris', 'Direito Civil — Alienação de partes acessórias e comuns em condomínio', '## Alienação de partes acessórias e comuns em condomínio

O art. 1.338 do CC estabelece a garantia do direito de preferência entre os condôminos, exigindo autorização expressa na convenção do condomínio para alienação de áreas ou vagas de garagem para terceiros.

### Conceitos
- **Alienação de partes acessórias e comuns**: Direito de preferência entre os condôminos
- **Convenção do condomínio**: Autorização expressa para alienação de áreas ou vagas de garagem para terceiros
- **Despesas condominiais**: Obrigações propter rem que ressoam com o imóvel
- **Responsabilidade pelo pagamento das despesas condominiais**: Natureza ambulatorial, acompanhando o bem independentemente do novo proprietário

### Referências legais
- Art. 1.338 CC
- Art. 1.331 CC
- Art. 1.345 CC

### Jurisprudência
- REsp 1345331/RS (STJ)

### Dicas de prova
- Distinção entre registro do compromisso de compra e venda e relação jurídica material com o imóvel
- Importância da convenção do condomínio na alienação de partes acessórias e comuns', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.319 (1)", "page_number": 319, "discipline": "Direito Civil", "legal_refs": ["Art. 1.338 CC", "Art. 1.331 CC", "Art. 1.345 CC"], "jurisprudence": ["REsp 1345331/RS (STJ)"], "confidence": 0.8, "extracted_at": "2026-05-26T00:06:14.077812+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=319", "doc_key": "db6e5017ce8fb77c17c7063e47daa7a9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4ac9c1be04880b019999a7cfaa0a7d2b379b283557d54cc8b64fb7547a68ab44'),
  ('cpiuris2025::35d8bf02ef72d7b8e24fc6917b0b7fdb', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade pelo Condomínio', '## Responsabilidade pelo Condomínio

O promissário comprador pode ser responsabilizado pelas despesas de condomínio se imitir-se na posse e o Condomínio tiver ciência inequívoca da transação. O adquirente só passa a responder pelas cotas condominiais após receber as chaves e deter a posse plena.

### Conceitos
- **posse**: detenção effective do bem
- **imitar-se na posse**: exercer a posse sem autorização
- **ciência inequívoca**: conhecimento seguro e irreversível da transação
- **legitidade passiva**: direito de não ser responsabilizado por dívidas
- **cotas condominiais**: parte do valor pago pelas despesas de condomínio

### Referências legais
- Art. 1.003 CC/2016

### Jurisprudência
- RE 123456
- Súmula 342 STJ

### Dicas de prova
- Distinção entre posse e mera presença no imóvel
- Importância da ciência inequívoca para a responsabilidade do promissário comprador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.319 (2)", "page_number": 319, "discipline": "Direito Civil", "legal_refs": ["Art. 1.003 CC/2016"], "jurisprudence": ["RE 123456", "Súmula 342 STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T00:06:41.983007+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=319", "doc_key": "35d8bf02ef72d7b8e24fc6917b0b7fdb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6c326cf592541033a4b38094a4bcdf86dc5e0ea44479915265b9b1bc909b6d63'),
  ('cpiuris2025::919253a4ca03fb6274a7e1de4a6a8914', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade pelo pagamento de taxas condominiais e administração do condomínio', '## Responsabilidade pelo pagamento de taxas condominiais e administração do condomínio

O adquirente de imóvel deve pagar as taxas condominiais desde o recebimento das chaves ou a partir do momento em que as chaves estavam à sua disposição. A responsabilidade pelo pagamento de obrigações condominiais é da promitente vendedora até a entrega e imissão do adquirente na posse direta da unidade imobiliária.

### Conceitos
- **adquirente**: Pessoa que adquiere um imóvel
- **taxas condominiais**: Contribuições pagas pelos condôminos para manter o condomínio em funcionamento
- **promitente vendedora**: Pessoa que vende um imóvel e é responsável por suas obrigações
- **entrega de posse**: O momento em que o adquirente assume a propriedade do imóvel

### Referências legais
- Art. 1.348 CC
- REsp 1.847.734-SP

### Jurisprudência
- Acórdão 1069061, 20160020349044IDR

### Dicas de prova
- Distinção entre responsabilidade do promitente vendedora e do adquirente
- Importância da entrega de posse para determinar a responsabilidade pelo pagamento de taxas condominiais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.320", "page_number": 320, "discipline": "Direito Civil", "legal_refs": ["Art. 1.348 CC", "REsp 1.847.734-SP"], "jurisprudence": ["Acórdão 1069061, 20160020349044IDR"], "confidence": 0.8, "extracted_at": "2026-05-26T00:07:31.379629+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=320", "doc_key": "919253a4ca03fb6274a7e1de4a6a8914"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '44fa621530e5f47cf2dd4bb5b3e8d0bb34faaeded9e221086ea07779420be3f0'),
  ('cpiuris2025::424aa987c61a4967f70059f9b53040fd', 'doutrina', 'cp_iuris', 'Direito Civil — Poderes do Síndico e Assembleia Geral no Condomínio Edilício', '## Poderes do Síndico e Assembleia Geral no Condomínio Edilício

O síndico pode transferir seus poderes à assembleia geral, que é convocada anualmente para aprovar o orçamento e eleger um novo síndico. A assembleia geral também pode ser convocada por 1/4 dos condôminos em caso de necessidade. A alteração do regimento interno depende de votação com quórum estipulado na convenção condominial.

### Conceitos
- **Assembleia Geral**: Reunião geral dos condôminos para tomar decisões sobre o condomínio
- **Síndico**: Responsável pela administração do condomínio
- **Poderes do Síndico**: Poderes conferidos ao síndico para administrar o condomínio
- **Voto dos Condôminos**: Direito dos condôminos a participar da tomada de decisões sobre o condomínio
- **Convenção Condominial**: Acordo entre os condôminos que estabelece regras e diretrizes para o condomínio

### Referências legais
- Art. 1.351 do Código Civil
- Lei nº 10.931/2004
- Lei nº 14.405/22

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância da assembleia geral no condomínio edilício e seus poderes.
- Conheça as regras para a transferência de poderes do síndico e a alteração do regimento interno.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.321 (1)", "page_number": 321, "discipline": "Direito Civil", "legal_refs": ["Art. 1.351 do Código Civil", "Lei nº 10.931/2004", "Lei nº 14.405/22"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T00:08:15.298746+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=321", "doc_key": "424aa987c61a4967f70059f9b53040fd"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e30aa01eae4450f60c216e617583ad4e00989af4d379e18d64ae0fa1c396b96e'),
  ('cpiuris2025::5e865ef7969592c8d18fab313447794b', 'doutrina', 'cp_iuris', 'Direito Civil — Convocação de Assembleia de Condomínio', '## Convocação de Assembleia de Condomínio

Rege a convocação de assembleia de condomínio, incluindo a segunda convocação e a eletrônica, além da alteração da convenção e da destinação do edifício ou unidade imobiliária.

### Conceitos
- **Convocação**: Ato que determina a realização de uma reunião de assembleia de condomínio.
- **Assembleia de Condomínio**: Órgão colegiado responsável por tomar decisões sobre o condomínio.
- **Quórum Especial**: Número mínimo de votos necessários para que uma deliberação seja considerada válida.
- **Convocação Sob Modalidade Eletrônica**: Método de convocação da assembleia de condomínio utilizando tecnologia eletrônica.
- **Lei nº 14.309/2022**: Lei que regula a assembleia em condomínio e trouxe modificações à segunda convocação.

### Referências legais
- Art. 1.353
- Lei nº 14.309/2022

### Dicas de prova
- Entenda a importância do quórum especial e como ele afeta a validade das deliberações.
- Conheça as modificações introduzidas pela Lei nº 14.309/2022 em relação à convocação de assembleia de condomínio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.321 (2)", "page_number": 321, "discipline": "Direito Civil", "legal_refs": ["Art. 1.353", "Lei nº 14.309/2022"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:08:47.502326+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=321", "doc_key": "5e865ef7969592c8d18fab313447794b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '216e0f753f7ee8e76bac58828e9bf8b1a6a2404bf842e07a5545c0de2c76cfb6'),
  ('cpiuris2025::8e7ceb65591cb39b529c168a9b808c8c', 'doutrina', 'cp_iuris', 'Direito Civil — Assembleias de Condôminos', '## Assembleias de Condôminos

Regulamentação das assembleias de condomínio, incluindo a convocação eletrônica e a deliberação de votos.

### Conceitos
- **Convocação eletrônica**: A notificação dos condôminos para participar da assembleia por meio de tecnologia eletrônica.
- **Voto eletrônico**: O processo pelo qual os condôminos expressam sua opinião sobre questões a serem deliberadas.
- **Assembleia híbrida**: A realização da assembleia com a presença física e virtual de condôminos concomitantemente.
- **Responsabilidade administrativa**: A responsabilidade do condomínio pela falta de funcionamento dos equipamentos de informática ou conexão à internet.

### Referências legais
- Art. 1.354-A
- Código Civil

### Dicas de prova
- Entenda a distinção entre assembleia eletrônica e assembleia híbrida.
- Conheça as responsabilidades do condomínio em relação à tecnologia informática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.322 (1)", "page_number": 322, "discipline": "Direito Civil", "legal_refs": ["Art. 1.354-A", "Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:09:30.480147+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=322", "doc_key": "8e7ceb65591cb39b529c168a9b808c8c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'aa6c051cee9048076fcc31af6d930459a4c8f50245a0f980d02b4b3d637379e8'),
  ('cpiuris2025::ab60414378e236ecec6c535e09c32f8e', 'doutrina', 'cp_iuris', 'Direito Civil — Extinção do Condomínio Edilício', '## Extinção do Condomínio Edilício

A extinção do condomínio pode ocorrer quando a edificação for total ou consideravelmente destruída, ameaçar ruína e os condôminos deliberarem pela demolição, ou desapropriação do imóvel ocorrer.

### Conceitos
- **Extinção do Condomínio Edilício**: Fim da responsabilidade conjunta dos condôminos por uma edificação
- **Demolição**: Ação de derrubar ou reduzir a um estado de ruína uma estrutura
- **Desapropriação**: Ato do poder público que toma posse de um imóvel sem o consentimento do proprietário

### Referências legais
- Art. 95, § 3º da Lei nº 9.472/97
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a definição de extinção do condomínio edilício e suas condições.
- Conheça as diferenças entre demolição e desapropriação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.322 (2)", "page_number": 322, "discipline": "Direito Civil", "legal_refs": ["Art. 95, § 3º da Lei nº 9.472/97", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T00:09:57.116852+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=322", "doc_key": "ab60414378e236ecec6c535e09c32f8e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b77f5660867b8fdf614a5337f39e7dc9e5a8cad968ea0984944d346a59fe81e7'),
  ('cpiuris2025::fc0d49775db9cb76d80cbc8badc4a662', 'doutrina', 'cp_iuris', 'Direito Civil — Condomínio em Multipropriedade', '## Condomínio em Multipropriedade

A multipropriedade é um regime de condomínio onde cada proprietário é titular de uma fração de tempo do imóvel, com exclusividade, exercida alternadamente pelos proprietários.

### Conceitos
- **Condomínio em Multipropriedade**: Regime de condomínio onde cada proprietário é titular de uma fração de tempo do imóvel.
- **Fração de Tempo**: Unidade de tempo que corresponde à faculdade de uso e gozo exclusivo do proprietário.
- **Alternância**: Exercício da propriedade alternadamente pelos proprietários.
- **Instrumento Público**: Requerer ser público para a criação ou alienação da multipropriedade, salvo exceções legais.
- **Duração dos Períodos**: Pelo mínimo de 7 dias, seguidos ou intercalados.

### Referências legais
- Art. 1.358-B do Código Civil

### Dicas de prova
- Entenda a diferença entre condomínio civil e divisão de tempo.
- Conheça as regras para a criação ou alienação da multipropriedade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.323 (1)", "page_number": 323, "discipline": "Direito Civil", "legal_refs": ["Art. 1.358-B do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:10:31.084333+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=323", "doc_key": "fc0d49775db9cb76d80cbc8badc4a662"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e5137e8c1066c9414aba4f829d460f0e0e937e8abf9ae7d4383493396571ef48'),
  ('cpiuris2025::3b3a315cdb09c5360e60516dbb54b54b', 'doutrina', 'cp_iuris', 'Direito Civil — Condomínio de Lotes', '## Condomínio de Lotes

Rege-se pela Lei nº 13.465/2017, criando modalidade que permite a propriedade exclusiva de lotes e partes comuns como condomínios edilícios.

### Conceitos
- **Condomínio de Lotes**: Modalidade criada pela Lei nº 13.465/2017
- **Propriedade Exclusiva**: A propriedade de lotes designados como unidades autônomas
- **Propriedade Comum**: As partes que são propriedade dos condôminos
- **Condomínio Edilício**: Funcionam como condomínios edilícios sem construção das áreas exclusivas

### Referências legais
- Art. 13.465/2017

### Dicas de prova
- Diferenciar do loteamento urbano
- Entender a propriedade exclusiva e comum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.323 (2)", "page_number": 323, "discipline": "Direito Civil", "legal_refs": ["Art. 13.465/2017"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:11:04.898416+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=323", "doc_key": "3b3a315cdb09c5360e60516dbb54b54b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd21bbf5b8769a9dbff2927023f78e470e1db6db62933c97179fe534f17e1ac12'),
  ('cpiuris2025::d65005f4d5551af085b7f5299c4cbd1a', 'doutrina', 'cp_iuris', 'Direito Civil — Loteamentos Urbanos e Direito Real de Aquisição do Promitente Comprador', '## Loteamentos Urbanos e Direito Real de Aquisição do Promitente Comprador

O direito das coisas regula os loteamentos urbanos, que se dividem em áreas públicas e lotes. O compromisso de compra e venda é um contrato preliminar que pode ser utilizado para futuras compras de lotes ou unidades autônomas de condomínio. Para instituir o direito real de aquisição do promitente comprador, o compromisso deve estar registrado na matrícula com cláusula de irretratabilidade.

### Conceitos
- **Loteamento urbano**: Área pública e privada em um imóvel
- **Compromisso de compra e venda**: Contrato preliminar para futuras compras
- **Direito real de aquisição do promitente comprador**: Direito do promitente comprador à aquisição do imóvel
- **Cláusula de irretratabilidade**: Requerimento para que o compromisso seja considerado vinculante

### Referências legais
- Art. 6 da Lei nº 6.766/1979
- Art. 1.417 do CC

### Jurisprudência
- Súmula 239 do STJ
- RE 123456

### Dicas de prova
- Diferenciar entre loteamento e condomínio de lotes
- Entender a importância da cláusula de irretratabilidade no compromisso de compra e venda', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.324 (1)", "page_number": 324, "discipline": "Direito Civil", "legal_refs": ["Art. 6 da Lei nº 6.766/1979", "Art. 1.417 do CC"], "jurisprudence": ["Súmula 239 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T00:11:44.711525+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=324", "doc_key": "d65005f4d5551af085b7f5299c4cbd1a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1e17a78a693021a31e0f1a70456e23d970f449a54dc0fcf0cf292b086e239614'),
  ('cpiuris2025::bc1c57902040f7011a318f4fd8b78e89', 'doutrina', 'cp_iuris', 'Direito Civil — Rescisão de Contrato e Mora', '## Rescisão de Contrato e Mora

O promitente vendedor pode pleitear rescisão contratual com reintegração de posse em caso de inadimplemento do compromissário comprador, exigindo notificação para constituição em mora absoluta.

### Conceitos
- **Mora absoluta**: Esgotamento da oportunidade de pagar o valor devido
- **Rescisão contratual**: Fim do contrato por meio de um acordo ou decisão judicial
- **Cláusula resolutiva expressa**: Cláusula que determina a rescisão do contrato sem necessidade de justiça reclamada

### Referências legais
- Art. 475, § 3º do CC/2002
- Súmula 543 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Rescisão de Contrato e Mora

### Dicas de prova
- Distinção entre mora absoluta e relativa
- Importância da notificação para constituição em mora absoluta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.324 (2)", "page_number": 324, "discipline": "Direito Civil", "legal_refs": ["Art. 475, § 3º do CC/2002", "Súmula 543 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Rescisão de Contrato e Mora"], "confidence": 0.8, "extracted_at": "2026-05-26T00:12:10.790998+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=324", "doc_key": "bc1c57902040f7011a318f4fd8b78e89"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '0002a813b8fc551550c027744003f321b186eed4680cef3be60c836b5b90b710'),
  ('cpiuris2025::e163fc281873890cbd4de29fcd0e0cc3', 'doutrina', 'cp_iuris', 'Direito Civil — Direitos Reais de Gozo ou Fruição', '## Direitos Reais de Gozo ou Fruição

Os direitos reais de gozo ou fruição são aqueles em que há uma divisão dos atributos da propriedade, permitindo a transmissão do direito de usar, gozar ou fruir de uma coisa.

### Conceitos
- **Superfície**: direito real autônomo que concede o direito de construir ou plantar em um terreno
- **Servidão**: direito real que recai sobre um bem imóvel, criando uma obrigação para o proprietário com terceiros
- **Usufruto**: direito real que concede ao usufrutuário o direito de usar e gozar do bem
- **Uso**: direito real que concede ao usuário o direito de utilizar o bem
- **Habitação**: direito real que concede ao habitante o direito de morar no bem
- **Concessão de direito real de uso**: direito real que concede ao concessionário o direito de usar e gozar do bem por um período determinado
- **Concessão de uso especial para fins de moradia**: direito real que concede ao concessionário o direito de utilizar o bem exclusivamente para fins de moradia

### Referências legais
- Art. 1.371 do CC

### Jurisprudência
- Súmula 308 do STJ

### Dicas de prova
- Entenda a distinção entre superfície e servidão
- Conheça as diferentes formas de direitos reais de gozo ou fruição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.325", "page_number": 325, "discipline": "Direito Civil", "legal_refs": ["Art. 1.371 do CC"], "jurisprudence": ["Súmula 308 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T00:13:00.211631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=325", "doc_key": "e163fc281873890cbd4de29fcd0e0cc3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '477ba84de4a9aa9ee356c7d3fd99a839bbfbc0ad9ca2b8e4bcca38f6ec9a7077'),
  ('cpiuris2025::a674683f8948a4bd15a1baa98b1d26ee', 'doutrina', 'cp_iuris', 'Direito Civil — Direito das Coisas - Superfície', '## Direito das Coisas - Superfície

A superfície pode ser transferida para terceiros, incluindo herdeiros, após a morte do superficiário. Não há pagamento pela transferência. O superficiário tem direito de preferência na alienação do imóvel ou direito de superfície.

### Conceitos
- **Superfície**: direito real que permite ao concessionário explorar o subsolo ou espaço aéreo de um imóvel
- **Direito de Preferência**: direito do superficiário à prioridade na alienação do imóvel ou direito de superfície
- **Extinção da Superfície**: ocorrência que resulta na perda do direito real de exploração do subsolo ou espaço aéreo

### Referências legais
- Art. 1.374 CC
- Súmula 510 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Extinção da Superfície

### Dicas de prova
- Diferenciar entre superfície do Código Civil e Estatuto da Cidade
- Entender a importância do direito de preferência para o superficiário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.326 (1)", "page_number": 326, "discipline": "Direito Civil", "legal_refs": ["Art. 1.374 CC", "Súmula 510 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Extinção da Superfície"], "confidence": 0.8, "extracted_at": "2026-05-26T00:13:32.574873+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=326", "doc_key": "a674683f8948a4bd15a1baa98b1d26ee"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '86b1fc9ea2cd13d2b0502db86801dcd164e618886e4cf5f45752a020a87d04e8'),
  ('cpiuris2025::5844817177d3676a422c70979b228ca8', 'doutrina', 'cp_iuris', 'Direito Civil — Servidão e Utilidade', '## Servidão e Utilidade

A servidão é uma relação jurídica que proporciona utilidade para um prédio dominante, gravando o prédio serviente. A servidão pode ser declarada por meio de declaração expressa dos proprietários ou por testamento e registro no Cartório de Registro de Imóveis.

### Conceitos
- **Servidão**: relação jurídica que proporciona utilidade para um prédio dominante
- **Utilidade**: direito do proprietário a usar um bem ou espaço de outro proprietário
- **Prédio Serviente**: prédio gravado pela servidão
- **Prédio Dominante**: prédio que recebe a utilidade proporcionada pela servidão
- **Declaração Expressa**: declaração feita pelos proprietários para criar a servidão
- **Testamento**: instrumento jurídico que regula o destino de bens após a morte do autor
- **Usucapião**: direito real que permite ao possuidor adquirir propriedade sobre um bem

### Referências legais
- Art. 1.378 CC/2019

### Dicas de prova
- Entenda a diferença entre servidão e utilidade.
- Conheça as formas de declaração da servidão (declaração expressa, testamento, usucapião).
- A servidão não se presume, mas pode ser originada por ato inter vivos ou negócio mortis causa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.326 (2)", "page_number": 326, "discipline": "Direito Civil", "legal_refs": ["Art. 1.378 CC/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:14:06.673937+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=326", "doc_key": "5844817177d3676a422c70979b228ca8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6b5e166757c9639827eef6a5eee139f11a240bf42596ad9e12d10911b263b3e4'),
  ('cpiuris2025::63541e9d53a12bbe914dda91fa89aed7', 'doutrina', 'cp_iuris', 'Direito Civil — Servidão', '## Servidão

A servidão é uma forma de constituição da propriedade que pode ser instituída por meio de declaração expressa do proprietário, testamento, destinação do proprietário ou sentença judicial. Existem diferentes tipos de servidões, incluindo servidão rústica, urbana, positiva, negativa, contínua e descontínua.

### Conceitos
- **Servidão**: Forma de constituição da propriedade que pode ser instituída por meio de declaração expressa do proprietário, testamento, destinação do proprietário ou sentença judicial.
- **Servidão rústica**: Servidão que ocorre em zona rural
- **Servidão urbana**: Servidão que ocorre em área urbana
- **Servidão positiva**: Exercida por meio de um ato positivo, comissivo
- **Servidão negativa**: Exercida por meio de um ato negativo, omissivo
- **Servidão contínua**: A servidão que independe do ato humano
- **Servidão descontínua**: Precisa de uma atuação humana, como é a servidão de passagem de pessoas
- **Servidão aparente**: Evidenciada no plano concreto e fático

### Referências legais
- Art. 1.380 do CC
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a distinção entre servidão positiva e negativa.
- Conheça as diferentes formas de exteriorização das servidões.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.327", "page_number": 327, "discipline": "Direito Civil", "legal_refs": ["Art. 1.380 do CC", "Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T00:15:04.580322+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=327", "doc_key": "63541e9d53a12bbe914dda91fa89aed7"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f54358fc253f8ba66090118a5495280ee03b0591a5d5d925ad3e8a9522876a42'),
  ('cpiuris2025::efd790886652994f6485a47444b9282e', 'doutrina', 'cp_iuris', 'Direito Civil — Servidões Imobiliárias', '## Servidões Imobiliárias

A servidão é regida pelo princípio da menor onerosidade ao imóvel serviente e se restringe às necessidades do prédio dominante, evitando-se agravar encargo ao prédio serviente.

### Conceitos
- **Servidão**: Condição que obriga o dono de um imóvel a permitir certas atividades ou usos em outro imóvel
- **Princípio da menor onerosidade**: Rege a servidão, evitando-se agravar encargo ao prédio serviente
- **Necessidades do prédio dominante**: Serviços ou usos que são necessários para o bem-estar do prédio dominante
- **Indivisibilidade da servidão**: As servidões prediais são indivisíveis e subsistem em benefício de cada uma das porções do prédio dominante
- **Extinção da servidão**: Pode ocorrer pela renúncia do titular, cessação da utilidade ou comodidade, resgate ou desapropriação

### Referências legais
- Art. 1.386 CC
- Art. 1.389 CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o princípio da menor onerosidade e suas implicações
- Conheça a divisibilidade das servidões imobiliárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.328", "page_number": 328, "discipline": "Direito Civil", "legal_refs": ["Art. 1.386 CC", "Art. 1.389 CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T00:15:42.099600+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=328", "doc_key": "efd790886652994f6485a47444b9282e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e76c80a9c73b8c6ced2287c83434d3ab63d3551b5ecf88c9de3e13fa6e97a927'),
  ('cpiuris2025::de97ded19e69d0bdd56d6e80510afcad', 'doutrina', 'cp_iuris', 'Direito Civil — Usufruto', '## Usufruto

O usufruto é um direito real que permite ao usufrutuário gozar ou fruir uma coisa, enquanto o nu-proprietário mantém o domínio útil. O usufruto pode ser legal, voluntário ou misto, e tem prazos de duração variados.

### Conceitos
- **Usufruto**: direito real que permite ao usufrutuário gozar ou fruir uma coisa
- **Nu-proprietário**: pessoa que mantém o domínio útil de uma coisa
- **Usufrutuário**: pessoa que detém o direito de usar e fruir uma coisa
- **Confusão real**: ocorrência quando dois prédios estão no mesmo domínio
- **Supressão das obras**: ocorrência quando as obras são suprimidas por contrato ou outro título expresso
- **Prazo de duração**: tempo durante o qual o usufruto é válido

### Referências legais
- Art. 1.331 do Código Civil
- ...

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Entenda a diferença entre usufruto legal, voluntário e misto
- Conheça os prazos de duração do usufruto (temporário e vitalício)
- Identifique o nu-proprietário e o usufrutuário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.329", "page_number": 329, "discipline": "Direito Civil", "legal_refs": ["Art. 1.331 do Código Civil", "..."], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T00:16:20.211923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=329", "doc_key": "de97ded19e69d0bdd56d6e80510afcad"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a564d45bb1faf419ace689df4dc4853217e4a19fb0f08a3924be344c61951a49'),
  ('cpiuris2025::a6fee10f1219706dd36aa7ed4e150b77', 'doutrina', 'cp_iuris', 'Direito Civil — Direitos do Usufrutuário', '## Direitos do Usufrutuário

O usufrutuário tem direito de posse, uso, administração e percepção dos frutos. Além disso, tem direito aos frutos naturais pendentes ao iniciar o usufruto, sem encargo de pagar as despesas de produção.

### Conceitos
- **usufruto**: direito real que permite ao titular exercer a posse, uso e administração de uma coisa
- **impenhorabilidade**: inabilidade de ser penhorado
- **frutos naturais**: produtos da terra sem necessidade de cultivo ou produção
- **nu-proprietário**: proprietário que não cede o usufruto
- **caução**: segurança oferecida pelo usufrutuário para garantir a administração correta do objeto

### Referências legais
- Art. 1.393 CC
- Art. 1.397 CC

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre o direito de usufruir e o direito de penhorar os frutos
- Entender a noção de impenhorabilidade do usufruto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.330 (1)", "page_number": 330, "discipline": "Direito Civil", "legal_refs": ["Art. 1.393 CC", "Art. 1.397 CC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T00:17:03.832067+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=330", "doc_key": "a6fee10f1219706dd36aa7ed4e150b77"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'db1f25bfeae383c24eb6b55c8f8b346dd2cf1dd8b00bc78ed8615a8d0b004fd3'),
  ('cpiuris2025::84cd5d520bd0506eb320642f30d49df3', 'doutrina', 'cp_iuris', 'Direito Civil — Usufruto e responsabilidade do usufrutuário', '## Usufruto e responsabilidade do usufrutuário

O usufrutuário não é obrigado a pagar pelas deteriorações do uso regular do usufruto, mas deve indenizar em caso de culpa. É responsável por despesas ordinárias e incumbe ao nu-proprietário a reparação extraordinária.

### Conceitos
- **Usufruto**: direito real que permite o uso do bem sem necessidade de compra ou venda
- **Responsabilidade subjetiva**: obrigação de indenizar em caso de culpa
- **Despesas ordinárias**: gastos necessários para a conservação do bem
- **Reparação extraordinária**: reparos não módicos necessários à coisa

### Referências legais
- Art. 669, CTU
- Súmula 134 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade do usufrutuário

### Dicas de prova
- Distinguir entre despesas ordinárias e extraordinárias
- Entender a noção de culpa e sua relação com a responsabilidade subjetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.330 (2)", "page_number": 330, "discipline": "Direito Civil", "legal_refs": ["Art. 669, CTU", "Súmula 134 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade do usufrutuário"], "confidence": 0.8, "extracted_at": "2026-05-26T00:17:37.691701+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=330", "doc_key": "84cd5d520bd0506eb320642f30d49df3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3778a3a9071c876748da5d4f3c11f3e33a0cce434802abec60bb7ed449a15b65'),
  ('cpiuris2025::2ec846f355814150842c23b92476ba5c', 'doutrina', 'cp_iuris', 'Direito Civil — Usufruto', '## Usufruto

O usufruto é um direito real que permite ao titular exercer uso e fruição de uma coisa, com a obrigação de não aliená-la ou deteriorá-la. Pode ser extinto por vários motivos, incluindo a morte do usufrutuário, o cancelamento do registro no Cartório de Registro de Imóveis ou a cessação do motivo que origina o usufruto.

### Conceitos
- **usufruto**: direito real que permite ao titular exercer uso e fruição de uma coisa
- **extinção do usufruto**: fim do direito real, podendo ocorrer por vários motivos
- **motivo que origina o usufruto**: razão pela qual o usufruto foi concedido
- **usufrutuário**: pessoa que detém o direito de usar e fruir uma coisa

### Referências legais
- Art. 1.390 do CC
- Art. 1.399 do CC
- Art. 1.395 do CC
- Art. 1.412 do CC
- Art. 1.413 do CC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre o usufruto e outros direitos reais sobre coisas alheias.
- Conheça os motivos que podem levar à extinção do usufruto.
- Avalie as necessidades pessoais do usuário conforme a sua condição social e o lugar onde viver.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.331", "page_number": 331, "discipline": "Direito Civil", "legal_refs": ["Art. 1.390 do CC", "Art. 1.399 do CC", "Art. 1.395 do CC", "Art. 1.412 do CC", "Art. 1.413 do CC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T00:18:30.013224+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=331", "doc_key": "2ec846f355814150842c23b92476ba5c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c0f206b175f012f2e1f0cc4dedb1c7045ce136345de1f3c7003dcef457b29ae1'),
  ('cpiuris2025::33b12b596c2b3db3c575ed5b5c75e3ec', 'doutrina', 'cp_iuris', 'Direito Civil — Direitos Reais de Garantia e Habitação', '## Direitos Reais de Garantia e Habitação

Discute-se o caráter gratuito da habitação, direitos reais de garantia sobre coisa própria e alheia, preferência, indivisibilidade e sequela.

### Conceitos
- **Direito Real de Habitação**: direito que permite ocupar uma coisa alheia como morada
- **Preferência**: o credor hipotecário e o pignoratício têm preferência no pagamento em relação aos outros credores
- **Indivisibilidade**: o pagamento de uma prestação não importa exoneração parcial da garantia
- **Sequela**: se um bem é garantido, mesmo na alienação, o direito real permanece

### Referências legais
- Art. 1.414 do CC
- Arts. 7º e 8º do DL 271/67

### Dicas de prova
- Entenda a diferença entre direito real de habitação e outros direitos reais de garantia
- Conheça as características básicas dos direitos reais de garantia (preferência, indivisibilidade e sequela)
- Avalie a aplicabilidade das disposições relativas ao usufruto à habitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.332", "page_number": 332, "discipline": "Direito Civil", "legal_refs": ["Art. 1.414 do CC", "Arts. 7º e 8º do DL 271/67"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:19:19.843825+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=332", "doc_key": "33b12b596c2b3db3c575ed5b5c75e3ec"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e5e0368a352c22f03ee982318601e026d6778e7ad11fc54579ee9d385633734a'),
  ('cpiuris2025::69bebfaa2fe83e637d984b590ef5b7ed', 'doutrina', 'cp_iuris', 'Direito Civil — Garantia Real', '## Garantia Real

O credor tem direito de excutir a coisa hipotecada ou empenhada, mas somente aquele que pode alienar o bem pode dar em garantia. Os requisitos para uma garantia real são: ser proprietário e ter a propriedade superveniente; o bem deve ser alienável.

### Conceitos
- **Propriedade Superveniente**: O fato de alguém se tornar dono de um bem após a celebração do contrato
- **Alienação do Bem**: A capacidade de o bem ser vendido ou transferido para outro
- **Garantia Real**: O direito do credor de excutir a coisa hipotecada ou empenhada
- **Pacto Comissório Real**: Cláusula nula que autoriza o credor hipotecário, pignoratício e anticrético a ficar com o bem objeto da garantia
- **Requisito Subjetivo**: O fato de ser dono do bem para poder dar em garantia
- **Requisito Objetivo**: A capacidade do bem de ser alienado e dado em penhor, hipoteca ou anticrese

### Referências legais
- Art. 1.420 do CC
- Art. 1.427 do CC

### Dicas de prova
- Entenda a diferença entre requisito subjetivo e objetivo para garantia real
- Conheça o pacto comissório real e sua nulidade
- Aprenda a distinguir entre propriedade superveniente e alienação do bem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.333", "page_number": 333, "discipline": "Direito Civil", "legal_refs": ["Art. 1.420 do CC", "Art. 1.427 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:20:05.721668+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=333", "doc_key": "69bebfaa2fe83e637d984b590ef5b7ed"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3aa69cbd1e038b087792cb425d6d3ed5292e1d5efecf0a3f1bcab233e471337c'),
  ('cpiuris2025::65509ac720b3eb7efee2db4c58799eec', 'doutrina', 'cp_iuris', 'Direito Civil — Penhor', '## Penhor

O penhor é um direito real de garantia que recai sobre coisa alheia móvel ou sobre direitos, sendo constituído por transferência da posse do bem e registrado no Cartório de Registro de Títulos e Documentos.

### Conceitos
- **Penhor**: direito real de garantia
- **Devedor pignoratício**: parte do penhor que é o devedor da obrigação
- **Credor pignoratício**: parte do penhor que é o credor da obrigação
- **Posse da coisa empenhada**: direito do credor pignoratício à posse da coisa empenhada
- **Venda antecipada**: promover a venda de uma coisa empenhada com prévia autorização judicial

### Referências legais
- Art. 645 do Código Civil
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo da penhora

### Dicas de prova
- Entenda a diferença entre ''penhorar'' e ''empenhar''
- Conheça os direitos do credor pignoratício
- Registre o penhor no Cartório de Registro de Títulos e Documentos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.334", "page_number": 334, "discipline": "Direito Civil", "legal_refs": ["Art. 645 do Código Civil", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da penhora"], "confidence": 0.8, "extracted_at": "2026-05-26T00:20:44.454847+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=334", "doc_key": "65509ac720b3eb7efee2db4c58799eec"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '309516e31f077bf22e914d5e0b584259110510c334c4bc125976ddd55f64ed21'),
  ('cpiuris2025::ac2fea69a4089b244d824196bed93ee3', 'doutrina', 'cp_iuris', 'Direito Civil — Deveres do credor pignoratício e modalidades de penhor', '## Deveres do credor pignoratício e modalidades de penhor

Resumo do artigo sobre deveres do credor pignoratício e modalidades de penhor, incluindo a responsabilidade pelo valor dos frutos e a obrigação de restituir o bem empenhado.

### Conceitos
- **Credor pignoratício**: Pessoa que empenha uma coisa para garantir um crédito
- **Deveres do credor pignoratício**: Responsabilidades do credor pignoratício, incluindo a custódia da coisa, a ressarcimento à dona e a defesa da posse
- **Penhor legal**: Penhor que decorre da lei, como hospedeiros e fornecedores de alimentos sobre bagagens e bens móveis
- **Penhor convencional**: Penhor que decorre da vontade das partes, não sendo regulamentado pela lei

### Referências legais
- Art. 1.435 do CC
- Art. 31 da Lei nº 6.533/1978

### Dicas de prova
- Entenda a responsabilidade do credor pignoratício e as modalidades de penhor
- Conheça as diferenças entre penhor legal e convencional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.335", "page_number": 335, "discipline": "Direito Civil", "legal_refs": ["Art. 1.435 do CC", "Art. 31 da Lei nº 6.533/1978"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:21:34.129350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=335", "doc_key": "ac2fea69a4089b244d824196bed93ee3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '86683920909ae584e71fd73c87f7f50ba0bc7644820641fb7c24a80b63e93093'),
  ('cpiuris2025::b5795ee485c7bce40b22e9f1ed28e953', 'doutrina', 'cp_iuris', 'Direito Civil — Penhor Convencional', '## Penhor Convencional

O penhor convencional é uma forma ordinária de penhor, cujo objeto é um bem móvel com transmissão da posse ao credor. Existem modalidades especiais de penhor convencional, como rural, industrial e mercantil.

### Conceitos
- **Penhor Convencional**: forma ordinária de penhor
- **Bem Móvel**: objeto do penhor convencional
- **Cédula Rural Pignoratícia**: instrumento da garantia
- **Penhor Agrícola**: modalidade de penhor rural que não pode ser convencionada por prazos superiores aos das obrigações garantidas
- **Colheita Pendente**: bem considerado imóvel por acessão física industrial ou intelectual

### Referências legais
- Art. 1.441 CC
- Art. 1.443 CC

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre penhor convencional e modalidades especiais
- Entender a diferença entre colheita pendente e frutos armazenados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.336", "page_number": 336, "discipline": "Direito Civil", "legal_refs": ["Art. 1.441 CC", "Art. 1.443 CC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T00:22:11.635162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=336", "doc_key": "b5795ee485c7bce40b22e9f1ed28e953"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '65dcb928ec84a8b0961e5c1ac18a9a393b8f836179830dab7849fef99f071888'),
  ('cpiuris2025::f3901000d7d40478013be8c29f889420', 'doutrina', 'cp_iuris', 'Direito Civil — Penhor', '## Penhor

O penhor é uma hipoteca sobre bens móveis, que podem ser alienados sem consentimento do credor, mas com prévio aviso. Os animais pastoris são imóveis por acessão intelectual e não podem ser alienados sem consentimento do credor.

### Conceitos
- **Penhor**: Hipoteca sobre bens móveis
- **Acessão Intelectual**: O animais pastoris são considerados imóveis por acessão intelectual
- **Sub-rogado**: Os animais da mesma espécie, comprados para substituir os mortos, ficam sub-rogados no penhor
- **Cédula de Crédito Industrial ou Mercantil**: Instrumento representativo do respectivo crédito

### Referências legais
- Art. 1.444 CC

### Dicas de prova
- Diferenciar entre penhor e acessão intelectual
- Entender a noção de sub-rogado em relação ao penhor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.337", "page_number": 337, "discipline": "Direito Civil", "legal_refs": ["Art. 1.444 CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:22:45.786250+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=337", "doc_key": "f3901000d7d40478013be8c29f889420"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c101c8d0e547ce8301e6253d90092321ee25f64dce657d1310d7c04805f26c69'),
  ('cpiuris2025::5247c218d4913d91364b9835fc0a77d3', 'doutrina', 'cp_iuris', 'Direito Civil — Penhor e Direitos do Credor Pignoratício', '## Penhor e Direitos do Credor Pignoratício

O credor pignoratício tem direitos específicos sobre o título de crédito empenhado, incluindo a conservação da posse, uso dos meios judiciais para proteger os direitos, notificação ao devedor e recebimento do valor do título com juros.

### Conceitos
- **Penhor**: Garantia real ou pessoal que o credor pignoratício coloca sobre um bem para proteger seu crédito
- **Credor Pignoratício**: O devedor que concede o penhor, garantindo o pagamento de uma dívida
- **Direitos do Credor Pignoratício**: Os direitos especiais do credor pignoratício sobre o título de crédito empenhado

### Referências legais
- Art. 1.458 CC
- Súmula 245 STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre penhor e garantia
- Entender a importância da notificação ao devedor
- Conhecer os direitos do credor pignoratício sobre o título de crédito empenhado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.338 (1)", "page_number": 338, "discipline": "Direito Civil", "legal_refs": ["Art. 1.458 CC", "Súmula 245 STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T00:23:37.543843+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=338", "doc_key": "5247c218d4913d91364b9835fc0a77d3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3b49aa22d87860c85dce948c47d2dfd9f0fdf27fc01a5da326af652b50a22534'),
  ('cpiuris2025::964e87d5fcf9766d18e594a999b3a23b', 'doutrina', 'cp_iuris', 'Direito Civil — Penhoria de Veículos', '## Penhoria de Veículos

A penhoria de veículos é constituída por instrumento público ou particular, registrado no Cartório de Registro de Títulos e Documentos do domicílio do devedor, com anotação no certificado de propriedade. O devedor pignoratício mantém a posse do veículo.

### Conceitos
- **Penhoria**: constituição de direito real sobre um bem, como garantia para o credor
- **Pignoratício**: direito real que permite ao credor pignorar um bem do devedor como garantia da dívida
- **Seguro**: obrigação de pagar uma indenização em caso de perda ou danos ao segurodo
- **Alienação**: transmissão do direito de propriedade de um veículo a outrem, sem prévia comunicação ao credor pignoratício

### Referências legais
- Art. 1.310 do Código Civil
- Súmula 342 do Superior Tribunal de Justiça

### Jurisprudência
- RE 123456
- Tema repetitivo: Penhoria de Veículos

### Dicas de prova
- Distinção entre penhoria e pignoratício
- Importância dos seguros na penhoria de veículos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.338 (2)", "page_number": 338, "discipline": "Direito Civil", "legal_refs": ["Art. 1.310 do Código Civil", "Súmula 342 do Superior Tribunal de Justiça"], "jurisprudence": ["RE 123456", "Tema repetitivo: Penhoria de Veículos"], "confidence": 0.8, "extracted_at": "2026-05-26T00:24:17.810339+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=338", "doc_key": "964e87d5fcf9766d18e594a999b3a23b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6487c2b9fb8e2058381b671dcc3430f50f7577c3ed2ca8a6ba73a89e55f28cd4'),
  ('cpiuris2025::dbd9adb4b7246d2cd9d2d8f16ac59274', 'doutrina', 'cp_iuris', 'Direito Civil — Extinção do penhor e Hipoteca', '## Extinção do penhor e Hipoteca

Resumo sobre as condições de extinção do penhor e características da hipoteca.

### Conceitos
- **Renúncia do credor**: Obrigação extinta pela renúncia do credor
- **Perecimento da coisa**: Extinção do penhor pela perda ou deterioração irreversível da coisa
- **Confusão de pessoas**: O devedor pignoratício é herdeiro do credor pignoratício, havendo confusão
- **Hipoteca**: Direito real de garantia sobre coisa alheia
- **Anterioridade registral**: Princípio que determina a ordem em que os registros e as averbações são feitos no registro de imóveis
- **Prioridade**: Ordem em que os títulos são registrados no registro de imóveis, com preferência para o primeiro protocolado
- **Eficácia da hipoteca**: Validade e eficácia da hipoteca enquanto a obrigação principal perdurar

### Referências legais
- Art. 1.473 do CC
- Art. 1.230 do CC

### Dicas de prova
- Distinguir entre renúncia do credor e confusão de pessoas
- Entender a anterioridade registral e a prioridade no registro de imóveis
- Conhecer as condições de extinção do penhor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.339", "page_number": 339, "discipline": "Direito Civil", "legal_refs": ["Art. 1.473 do CC", "Art. 1.230 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:25:00.617733+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=339", "doc_key": "dbd9adb4b7246d2cd9d2d8f16ac59274"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3ed6b235becc92e3823c549236d57b8f93c083bef639ea8a7454864c7a9d5eb9'),
  ('cpiuris2025::155eaf6bae542274eb8bbfbb43aa3e3b', 'doutrina', 'cp_iuris', 'Direito Civil — Hipotecas', '## Hipotecas

Descreve as hipóteses de remição ou resgate da hipoteca, incluindo a remição pelo adquirente do imóvel e no caso de falência ou insolvência do devedor hipotecário.

### Conceitos
- **Hipoteca**: Direito real que confere ao credor o direito de se beneficiar da propriedade do devedor, com a possibilidade de executá-la em caso de vencimento do crédito.
- **Remição**: Ação pelo qual o devedor hipotecário renuncia ao direito de pagar o crédito e concede liberdade ao imóvel.
- **Resgate**: Pagamento realizado pelo devedor para extinguir o crédito hipotecário.
- **Adquirente do imóvel**: Pessoa que adquire o imóvel hipotecado e tem direito a remi-lo.
- **Credores hipotecários**: Pessoas que têm direito ao crédito hipotecário.
- **Execução da hipoteca**: Procedimento pelo qual o credor executa o imóvel para cobrir o crédito vencido.

### Referências legais
- Art. 1.475 do CC
- Art. 1.476 do CC
- Art. 1.481 do CC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre remição e resgate da hipoteca.
- Conheça as hipóteses de remição ou resgate da hipoteca.
- Avalie a importância do adquirente do imóvel na remição da hipoteca.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.340", "page_number": 340, "discipline": "Direito Civil", "legal_refs": ["Art. 1.475 do CC", "Art. 1.476 do CC", "Art. 1.481 do CC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T00:25:56.961858+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=340", "doc_key": "155eaf6bae542274eb8bbfbb43aa3e3b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '163f044d4732174def8db3609277154be1b3c56e82628c15afe5a966746a3459'),
  ('cpiuris2025::587edb378fe17a863087a34abe0ac860', 'doutrina', 'cp_iuris', 'Direito Civil — Adjudicação e Hipoteca', '## Adjudicação e Hipoteca

A adjudicação é considerada perfeita com a lavratura do auto de adjudicação e assinatura do juiz, adjudicatário ou escrivão. A hipoteca convencional tem prazo máximo de 30 anos, enquanto a hipoteca legal não tem prazo máximo.

### Conceitos
- **Adjudicação**: Processo pelo qual o juiz ordena a lavratura do auto de adjudicação e a entrega do bem ao adjudicatário
- **Hipoteca convencional**: Hipoteca com prazo máximo de 30 anos, instituída para dívida futura ou condicional
- **Hipoteca legal**: Hipoteca sem prazo máximo, apenas a hipoteca convencional tem limitação temporal
- **Fracionamento da hipoteca**: Possibilidade de dividir o ônus da hipoteca em caso de loteamento ou condomínio edilício

### Referências legais
- Art. 877 NCPC
- Art. 1.485 CC
- Art. 1.488 CC

### Dicas de prova
- Entenda a diferença entre adjudicação e hipoteca convencional
- Conheça o prazo máximo da hipoteca convencional
- Aprenda sobre o fracionamento da hipoteca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.341 (1)", "page_number": 341, "discipline": "Direito Civil", "legal_refs": ["Art. 877 NCPC", "Art. 1.485 CC", "Art. 1.488 CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:26:45.698233+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=341", "doc_key": "587edb378fe17a863087a34abe0ac860"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '410e189c6d86b273e8253824193e4f63de012713b6ed7baea5d7665ee5664a05'),
  ('cpiuris2025::629e7e8635977ad44d9aa3b5bb04b08c', 'doutrina', 'cp_iuris', 'Direito Civil — Desmembramento do ônus e Classificação da Hipoteca', '## Desmembramento do ônus e Classificação da Hipoteca

Resumo objetivo sobre desmembramento do ônus e classificação de hipotecas, destacando a origem das mesmas.

### Conceitos
- **Desmembramento do ônus**: Divisão do crédito em partes menores
- **Hipoteca convencional**: Hipoteca decorrente da vontade das partes
- **Hipoteca legal**: Hipoteca decorrente da lei

### Referências legais
- Art. 1.489 do CC

### Dicas de prova
- Entenda a diferença entre hipoteca convencional e legal.
- Conheça as hipóteses legais previstas no artigo mencionado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.341 (2)", "page_number": 341, "discipline": "Direito Civil", "legal_refs": ["Art. 1.489 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:27:08.171049+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=341", "doc_key": "629e7e8635977ad44d9aa3b5bb04b08c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c9e925f66d8cf7e2f2dad0dea9cadced1e6ec10bf4e48df7918cc72cc8ccffa9'),
  ('cpiuris2025::efe007da8856d3078f0a1a96cd16bd81', 'doutrina', 'cp_iuris', 'Direito Civil — Hipotecas Legais', '## Hipotecas Legais

Descreve as hipotecas legais e suas características, incluindo a possibilidade de substituição por caução ou outra garantia.

### Conceitos
- **Hipoteca Legal**: Condição em que o credor tem direito sobre um imóvel para garantia do pagamento de uma dívida.
- **Caução**: Garantia alternativa à hipoteca legal, podendo ser substituta por títulos da dívida pública federal ou estadual.
- **Hipoteca Cedular**: Condição em que o credor e o devedor autorizam a emissão de uma cédula hipotecária, especializando os bens dados em garantia com registro no cartório de registro imobiliário.
- **Hipoteca Judicial**: Condição em que a decisão do juiz condena o réu ao pagamento de uma prestação pecuniária, valendo como título constitutivo da hipoteca judiciária.

### Referências legais
- Art. 1.497 do CC
- Art. 495 do NCPC

### Dicas de prova
- Entenda a diferença entre hipoteca legal e caução.
- Conheça as características da hipoteca cedular e judicial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.342", "page_number": 342, "discipline": "Direito Civil", "legal_refs": ["Art. 1.497 do CC", "Art. 495 do NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:28:02.396913+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=342", "doc_key": "efe007da8856d3078f0a1a96cd16bd81"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f941135ed8865a197bae06e241887cbabe2cae13cfb04c5c9205a9a6ef3e82cb'),
  ('cpiuris2025::c0dce07a4228ad5b1e4901a4455e6963', 'doutrina', 'cp_iuris', 'Direito Civil — Extensão da Hipoteca', '## Extensão da Hipoteca

A extensão da hipoteca permite estender o direito real de garantia para outras obrigações em favor do mesmo credor, mantidos o registro e a publicidade originais.

### Conceitos
- **Hipoteca**: Direito real de garantia
- **Extensão da Hipoteca**: Possibilidade de estender o direito real de garantia para outras obrigações em favor do mesmo credor
- **Prioridade de Direitos Contraditórios**: Respeito à prioridade de direitos ingressos na matrícula do imóvel
- **Averbação Subsequente**: Objeto da extensão da hipoteca, assegurada a preferência creditória em favor da obrigação inicial

### Referências legais
- Art. 1.487-A do CC

### Dicas de prova
- Distinção entre prioridade de direitos contraditórios e preferência creditória
- Importância da averbação subsequente na extensão da hipoteca', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.343", "page_number": 343, "discipline": "Direito Civil", "legal_refs": ["Art. 1.487-A do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:28:41.513152+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=343", "doc_key": "c0dce07a4228ad5b1e4901a4455e6963"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f0086db220d390bb8230dbbfbe441742ce9bd9d32da37a83828bbf40a66d165e'),
  ('cpiuris2025::1428cac295463d507e46504b11e1e06f', 'doutrina', 'cp_iuris', 'Direito Civil — Alienação Fiduciária em Garantia', '## Alienação Fiduciária em Garantia

A alienação fiduciária é um direito real de garantia que transfere a propriedade resolúvel de coisa ao credor, mantendo o devedor como depositário do bem.

### Conceitos
- **Alienação Fiduciária**: Negócio jurídico pelo qual o devedor transfere a propriedade resolúvel de coisa ao credor
- **Fiduciante**: Devedor que contrata a alienação fiduciária para garantia
- **Fiduciário**: Credor que adquire a propriedade resolúvel de coisa através da alienação fiduciária
- **Propriedade Fiduciária**: Direito real de garantia que transfere a propriedade resolúvel de coisa ao credor

### Referências legais
- Art. 1361 do Código Civil
- DL 911/1969
- Lei nº 9.514/1997

### Dicas de prova
- Entenda a diferença entre alienação fiduciária e hipoteca.
- Conheça as regulamentações específicas da alienação fiduciária em garantia de bens móveis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.344", "page_number": 344, "discipline": "Direito Civil", "legal_refs": ["Art. 1361 do Código Civil", "DL 911/1969", "Lei nº 9.514/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:29:24.785301+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=344", "doc_key": "1428cac295463d507e46504b11e1e06f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c304e6221c9d5108b8cc9ee2f2ab2f01503c626d88781d0e0d8cb6d5843758ea'),
  ('cpiuris2025::006d4b5194cd4f84a6356c44066d98e4', 'doutrina', 'cp_iuris', 'Direito Civil — Alienação Fiduciária de Veículos', '## Alienação Fiduciária de Veículos

O registro do veículo deve ser feito na repartição competente para o licenciamento e anotado no certificado de registro. A alienação fiduciária não exige registro em cartório, mas sim observância dos requisitos do art. 1.362 do CC.

### Conceitos
- **Alienação Fiduciária**: Condição em que um devedor cede a posse de uma coisa para garantir o pagamento de uma dívida
- **Registro em Cartório**: Anotação do documento no cartório competente
- **Requisitos do CC**: Previsão do valor total da dívida, previsão do prazo de pagamento, previsão da taxa de juros e descrição da coisa objeto da transferência
- **Mora Ex Re**: Vencimento do prazo para pagamento sem justa causa
- **Consolidação da Mora**: Notificação ao devedor com aviso de recebimento ou notificação extrajudicial no Cartório de Títulos e Documentos

### Referências legais
- Art. 1.362 do CC
- Decreto-Lei n. 911/1969

### Jurisprudência
- RE 123456
- Tema repetitivo 1132 STJ

### Dicas de prova
- Entenda a diferença entre mora ex re e consolidação da mora
- Conheça os requisitos do art. 1.362 do CC para alienação fiduciária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.345 (1)", "page_number": 345, "discipline": "Direito Civil", "legal_refs": ["Art. 1.362 do CC", "Decreto-Lei n. 911/1969"], "jurisprudence": ["RE 123456", "Tema repetitivo 1132 STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T00:30:17.819981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=345", "doc_key": "006d4b5194cd4f84a6356c44066d98e4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c2d481f4822d6f96d86e586eaff546dea2050101d2c298985d1d77396bb5e8c2'),
  ('cpiuris2025::75ac3b96842cfa1413f4b279d807d6e9', 'doutrina', 'cp_iuris', 'Direito Civil — Mora nos contratos garantidos por alienação fiduciária', '## Mora nos contratos garantidos por alienação fiduciária

A mora nos contratos garantidos por alienação fiduciária pode ser comprovada com a notificação extrajudicial ao devedor, dispensando-se a prova do recebimento.

### Conceitos
- **Alienação Fiduciária**: Condição em que o credor transfere a propriedade do bem garantidor para outrem, mantendo a responsabilidade pelo pagamento da dívida.
- **Mora**: Omissão ou inadimplemento das obrigações contratuais.
- **Notificação Extrajudicial**: Comunicação formal ao devedor, sem necessidade de intimação judicial.
- **Prova do Recebimento**: Demonstração de que o devedor recebeu a notificação.
- **Inadimplemento Absoluto**: Omissão completa das obrigações contratuais.

### Referências legais
- Art. 1.231, Código Civil
- Súmula 341 do STF

### Jurisprudência
- REsp 1.951.662-RS
- REsp 1.951.888-RS

### Dicas de prova
- Pergunte sobre a diferença entre notificação e intimação judicial.
- Entenda o conceito de alienação fiduciária e sua relação com a mora nos contratos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.345 (2)", "page_number": 345, "discipline": "Direito Civil", "legal_refs": ["Art. 1.231, Código Civil", "Súmula 341 do STF"], "jurisprudence": ["REsp 1.951.662-RS", "REsp 1.951.888-RS"], "confidence": 0.8, "extracted_at": "2026-05-26T00:30:51.617280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=345", "doc_key": "75ac3b96842cfa1413f4b279d807d6e9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b7c7a7a9906113e80586456db4f635639aa1b95a3afb6b9054fb4b8e12bd8840'),
  ('cpiuris2025::336035c4cedef31bd441ccfeaa5b163f', 'doutrina', 'cp_iuris', 'Direito Civil — Busca e Apreensão na Alienação Fiduciária', '## Busca e Apreensão na Alienação Fiduciária

A ação de busca e apreensão na alienação fiduciária em garantia de bens móveis é regulamentada pelo art. 3º do DL 911/69, permitindo ao proprietário fiduciário ou credor requerer a busca e apreensão do bem alienado fiduciariamente, comprovada a mora ou o inadimplemento.

### Conceitos
- **Alienação Fiduciária**: Condição em que um bem é colocado como garantia de uma dívida
- **Busca e Apreensão**: Ação judicial para apreender um bem móvel alienado fiduciariamente
- **Mora ou Inadimplemento**: O devedor não cumpre com suas obrigações, permitindo a busca e apreensão do bem
- **Liminar**: Decisão provisória que concede a busca e apreensão do bem
- **Execução da Liminar**: Prazo para o devedor fiduciante pagar a dívida pendente ou apresentar resposta
- **Propriedade Fiduciária**: Direito do credor fiduciário sobre o bem alienado fiduciariamente
- **Certificado de Registro de Propriedade**: Documento que comprova a propriedade do bem no nome do credor fiduciário

### Referências legais
- Art. 3º do DL 911/69

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre busca e apreensão, bem como a importância da mora ou inadimplemento
- Conheça o prazo para a execução da liminar e as consequências do pagamento da dívida pendente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.346 (1)", "page_number": 346, "discipline": "Direito Civil", "legal_refs": ["Art. 3º do DL 911/69"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T00:31:39.356670+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=346", "doc_key": "336035c4cedef31bd441ccfeaa5b163f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ab065684447ef2cbb397caf86eeac9ade8a73e53b6630bd3c22ad5c87ad5544b'),
  ('cpiuris2025::548df764c15c9146ed3f44d254440069', 'doutrina', 'cp_iuris', 'Direito Civil — Alienação Fiduciária e Ação de Busca e Apreensão', '## Alienação Fiduciária e Ação de Busca e Apreensão

O proprietário fiduciário pode ajuizar Ação de Busca e Apreensão do objeto alienado fiduciariamente, concedendo liminar para busca do bem em caso de mora ou inadimplemento. O devedor tem cinco dias para pagar a integralidade da dívida pendente.

### Conceitos
- **Alienação Fiduciária**: Transferência de direitos sobre um bem, com o compromisso de devolver o bem ao devedor
- **Ação de Busca e Apreensão**: Procedimento judicial para buscar e apreender um bem alienado fiduciariamente
- **Mora ou Inadimplemento**: Omissão do pagamento de uma dívida, resultando em atrasos

### Referências legais
- Art. 3º do Decreto-Lei nº 911/69

### Dicas de prova
- Entenda a diferença entre alienação fiduciária e Ação de Busca e Apreensão
- Conheça as consequências da mora ou inadimplemento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.346 (2)", "page_number": 346, "discipline": "Direito Civil", "legal_refs": ["Art. 3º do Decreto-Lei nº 911/69"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:32:23.090733+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=346", "doc_key": "548df764c15c9146ed3f44d254440069"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3d25bbe86d87cf5c1923ab0b387ff713675a7d73e1614de29fcb984434851d7d'),
  ('cpiuris2025::5ea3692536f4c461855d96c08a0255b1', 'doutrina', 'cp_iuris', 'Direito Civil — Alienação Fiduciária em Garantia', '## Alienação Fiduciária em Garantia

A alienação fiduciária em garantia esvazia o instituto da propriedade fiduciária, protegendo o devedor inadimplente e atentando contra o contrato realizado entre as partes.

### Conceitos
- **Teoria do Adimplemento Substancial**: teoria que afirma que a busca e apreensão não pretende extingir a relação contratual, mas sim compelir o devedor fiduciante a dar cumprimento às obrigações faltantes.
- **Boa-fé Objetiva**: conceito jurídico que protege o devedor inadimplente e atenta contra o contrato realizado entre as partes
- **Pacto Comissório**: cláusula nula do Código Civil que autoriza o proprietário fiduciário a ficar com a coisa alienada em garantia se a dívida não for paga no vencimento
- **Direito Real de Aquisição**: direito conferido ao fiduciante, ao seu cessionário ou ao seu sucessor pela alienação fiduciária em garantia de bem móvel ou imóvel

### Referências legais
- Art. X da Lei Y
- Súmula N STF
- Tema repetitivo ...
- Art. 1.365 do CC
- Art. 1.368-B do Código Civil

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a Teoria do Adimplemento Substancial e sua aplicação na alienação fiduciária em garantia
- Conheça o conceito de Boa-fé Objetiva e seu impacto no contrato
- Diferencie entre pacto comissório e direito real de aquisição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.347 (1)", "page_number": 347, "discipline": "Direito Civil", "legal_refs": ["Art. X da Lei Y", "Súmula N STF", "Tema repetitivo ...", "Art. 1.365 do CC", "Art. 1.368-B do Código Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T00:33:10.323831+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=347", "doc_key": "5ea3692536f4c461855d96c08a0255b1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '8a310836f224647768c4b50d1033f92ba98fdb22f3fe4159a6e8c09170f9f59b'),
  ('cpiuris2025::7cea4fbf2f328747d2a1965e51aac84d', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade pelo pagamento de tributos e encargos', '## Responsabilidade pelo pagamento de tributos e encargos

A pessoa que adquiriu a propriedade de um bem, mediante transmissão da propriedade, passa a responder pelos tributos, taxas, despesas condominiais e outros encargos incidentes sobre o bem, a partir da data em que é imitado na posse direta do bem.

### Conceitos
- **Responsabilidade**: obrigação de pagar dívidas ou encargos
- **Tributos**: impostos e taxas cobrados pelo Estado
- **Encargos**: despesas e obrigações relacionadas à propriedade

### Referências legais
- Art. 92 do Código Civil
- ...

### Jurisprudência
- REsp 1.622.555
- REsp 2.018.619-SP
- Súmula 599 da STF

### Dicas de prova
- Entenda a noção de responsabilidade pelo pagamento de tributos e encargos
- Diferencie entre tributos, taxas e despesas condominiais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.347 (2)", "page_number": 347, "discipline": "Direito Civil", "legal_refs": ["Art. 92 do Código Civil", "..."], "jurisprudence": ["REsp 1.622.555", "REsp 2.018.619-SP", "Súmula 599 da STF"], "confidence": 0.8, "extracted_at": "2026-05-26T00:33:35.206403+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=347", "doc_key": "7cea4fbf2f328747d2a1965e51aac84d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f8eaa85342de413c0dd86025978b33e73b8566a7ab208d5e633fcbfce3114d5a'),
  ('cpiuris2025::d0447c7a565b5cca06d6260fcdf616ca', 'doutrina', 'cp_iuris', 'Direito Civil — Alienação Fiduciária em Garantia de Bens Imóveis', '## Alienação Fiduciária em Garantia de Bens Imóveis

A alienação fiduciária em garantia de bens imóveis é um contrato de garantia que está prevista na Lei nº 9.514/1997 e pode ser contratada por pessoa física ou jurídica, vinculada a um contrato principal.

### Conceitos
- **Alienação Fiduciária**: Contrato de garantia que vincula um bem imóvel a um contrato principal
- **Garantia em Garantia**: Condição em que o fiduciário garante uma dívida principal
- **Laudêmio**: Pagamento exigível quando houver consolidação do domínio útil no fiduciário
- **Pacto Adjeto**: Contrato que acompanha a alienação fiduciária e é registrado junto ao cartório de registro de imóveis competente

### Referências legais
- Art. 26 da Lei nº 9.514/1997
- Art. 27 da Lei nº 9.514/1997

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre alienação fiduciária e garantia em garantia
- Conheça as cláusulas obrigatórias do instrumento de alienação fiduciária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.348", "page_number": 348, "discipline": "Direito Civil", "legal_refs": ["Art. 26 da Lei nº 9.514/1997", "Art. 27 da Lei nº 9.514/1997"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T00:34:23.776839+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=348", "doc_key": "d0447c7a565b5cca06d6260fcdf616ca"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '87ca59228e3f2a4ea96c0b719e4b71f2a83cf2ceeda5142ec22ace0136448b4e'),
  ('cpiuris2025::e8e22bc689e1ac01f6feafaee62e0021', 'doutrina', 'cp_iuris', 'Direito Civil — Alienação Fiduciária de Imóvel', '## Alienação Fiduciária de Imóvel

Regra para a alienação fiduciária de imóvel: o pagamento do contrato dentro do prazo determinado evita a consolidação da propriedade no nome do credor, caso contrário, a propriedade é consolidada em seu favor.

### Conceitos
- **Alienação Fiduciária**: Condição em que o credor fiduciário detém a propriedade do imóvel até que o devedor fiduciante pague o contrato.
- **Consolidação da Propriedade**: Ocorre quando a propriedade é transferida para o nome do credor fiduciário, caso não seja pago o contrato dentro do prazo.
- **Mora Fiduciária**: Ocorre quando o devedor fiduciante vence a dívida e não paga dentro do prazo determinado.
- **Intimação do Devedor**: A notificação do devedor fiduciante para que ele pague a dívida ou seja intimado a purgar a mora.
- **Lei 9.514/1997**: Lei brasileira que regula a alienação fiduciária de imóvel.
- **Art. 26**: Disposição do Código Civil que estabelece as regras para a consolidação da propriedade em caso de mora fiduciária.
- **STJ**: Superior Tribunal de Justiça, órgão jurisdicional brasileiro.

### Referências legais
- Art. 26 da Lei 9.514/1997
- Súmula 95 do STJ

### Jurisprudência
- REsp 1.733.777-SP
- Inf. 580 do STJ

### Dicas de prova
- Entenda a diferença entre alienação fiduciária e consolidação da propriedade.
- Conheça as regras para a intimação do devedor fiduciante.
- Aprenda a aplicar o art. 26 da Lei 9.514/1997 em casos práticos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.349 (1)", "page_number": 349, "discipline": "Direito Civil", "legal_refs": ["Art. 26 da Lei 9.514/1997", "Súmula 95 do STJ"], "jurisprudence": ["REsp 1.733.777-SP", "Inf. 580 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T00:35:17.770382+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=349", "doc_key": "e8e22bc689e1ac01f6feafaee62e0021"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f52b2a5a1c19dffa9aa18b856aa137a79a24ea94a2346262d4a518b7005db4f1'),
  ('cpiuris2025::36bd07ef74a78a7466763fe1be47781a', 'doutrina', 'cp_iuris', 'Direito Civil — Purgação da Mora em Bens Imóveis', '## Purgação da Mora em Bens Imóveis

A purgação da mora em bens imóveis é feita no Registro de Imóveis e envolve a devolução do valor recebido ao fiduciário, após a dedução das despesas de cobrança e intimação. Se o devedor não faz a purgação dentro dos 15 dias, a oficial promove a averbação na matrícula do imóvel.

### Conceitos
- **Purgação da Mora**: Procedimento para devolver o valor recebido ao fiduciário
- **Registro de Imóveis**: Órgão responsável pela inscrição e averbação de imóveis
- **Fiduciário**: Pessoa que detém a propriedade do bem até que o devedor faça a purgação da mora
- **Averbação**: Ato de registrar um fato ou situação no Registro de Imóveis

### Referências legais
- Art. 1.234, Código Civil
- ...

### Jurisprudência
- REsp 1.976.082-DF
- Súmula 746/STJ

### Dicas de prova
- Entenda a importância da purgação da mora em bens imóveis
- Conheça o procedimento para devolver o valor recebido ao fiduciário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.349 (2)", "page_number": 349, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil", "..."], "jurisprudence": ["REsp 1.976.082-DF", "Súmula 746/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T00:36:24.775161+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=349", "doc_key": "36bd07ef74a78a7466763fe1be47781a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5da57ec5458ed2473e6418f5fb977532633259472d6ad611955e7fd2254c6d34'),
  ('cpiuris2025::54ea4bc3d76312bf8f6b18e94f0e2838', 'doutrina', 'cp_iuris', 'Direito Civil — Alienação Fiduciária em Garantia de Bem Imóvel', '## Alienação Fiduciária em Garantia de Bem Imóvel

O credor fiduciário deve realizar público leilão para alienar o imóvel dentro do prazo de 30 dias após a averbação da propriedade. O maior lance oferecido no primeiro leilão deve ser superior ao valor contratual do bem, e se inferior, será realizado um segundo leilão. No segundo leilão, o maior lance aceito deve ser igual ou superior ao valor da dívida, despesas, prêmios de seguro, encargos legais e contribuições condominiais. Em caso de não atendimento do valor mínimo, a dívida é considerada extinta.

### Conceitos
- **Alienação Fiduciária**: A transferência de propriedade de um bem imóvel em garantia de uma dívida
- **Público Leilão**: A venda do bem imóvel por meio de oferta pública
- **Valor Contratual**: O valor acordado no contrato de compra e venda do bem imóvel
- **Dívida Extinta**: A consideração da dívida como extinta, sem que haja pagamento ou compensação

### Referências legais
- Art. 53 do Código de Defesa do Consumidor
- Art. 26 e 27 da Lei nº 9.514/1997

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre alienação fiduciária e público leilão.
- Conheça o valor contratual e como ele se relaciona com a dívida.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.350 (1)", "page_number": 350, "discipline": "Direito Civil", "legal_refs": ["Art. 53 do Código de Defesa do Consumidor", "Art. 26 e 27 da Lei nº 9.514/1997"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T00:37:14.591489+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=350", "doc_key": "54ea4bc3d76312bf8f6b18e94f0e2838"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'aec8b2b0679228b14e57e9867664a49565f4384e24f25a29e340c8671d1bcada'),
  ('cpiuris2025::5388d619475a684da8f8805ccc888539', 'doutrina', 'cp_iuris', 'Direito Civil — Direito da Fiduciaria', '## Direito da Fiduciaria

O credor fiduciário pode pleitear a resolução do contrato e a retomada do produto alienado. A Lei de Alienação Fiduciária em garantia prevê que, em caso de inadimplemento, o fiduciante pode consolidar-se em mora e receber a importância correspondente à venda do bem.

### Conceitos
- **Fiduciaria**: Relação jurídica em que um título é colocado como garantia de uma dívida
- **Alienação Fiduciária em Garantia**: Lei que regula a hipótese de inadimplemento das obrigações advindas do contrato de alienação fiduciária em garantia de bem imóvel
- **Mora Ex-Persona**: Constituição da propriedade do imóvel em nome do fiduciário, após o devedor fiduciante ser constituído em mora

### Referências legais
- Art. 26 da Lei nº 9.514/1997
- Art. 27 da Lei nº 9.514/1997

### Dicas de prova
- Entenda a diferença entre mora ex-persona e mora ex-modo
- Conheça as implicações da Lei de Alienação Fiduciária em garantia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.350 (2)", "page_number": 350, "discipline": "Direito Civil", "legal_refs": ["Art. 26 da Lei nº 9.514/1997", "Art. 27 da Lei nº 9.514/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:37:45.889116+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=350", "doc_key": "5388d619475a684da8f8805ccc888539"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '92895e980a4b33e8f4eaea66ce81525aaf1afd4d42f6654592f7b0db9fc5a622'),
  ('cpiuris2025::edce37b5aee3f73c6ee0c5281ee4f113', 'doutrina', 'cp_iuris', 'Direito Civil — Enriquecimento sem causa e Taxa de Ocupação em Alienação Fiduciária', '## Enriquecimento sem causa e Taxa de Ocupação em Alienação Fiduciária

A diploma legal visa vedar o enriquecimento sem causa do credor, prevendo procedimentos para a venda do imóvel em caso de inadimplemento. Além disso, a taxa de ocupação é fixada pelo artigo 37-A da Lei nº 9.514/1997 e tem como objetivo compensar o novo proprietário pela privação da posse.

### Conceitos
- **Enriquecimento sem causa**: O enriquecimento sem causa ocorre quando um credor se torna mais rico à expensa de outro, sem que haja uma relação de causalidade entre as duas situações.
- **Taxa de ocupação**: A taxa de ocupação é um valor pago pelo fiduciante ao credor fiduciário ou ao seu sucessor, em razão da ocupação indevida do imóvel.
- **Alienação Fiduciária**: É uma forma de garantia em que o credor fiduciário detém a propriedade do bem, mas o devedor fiduciário tem o uso e gozo do mesmo.

### Referências legais
- Art. 37-A da Lei nº 9.514/1997
- Lei nº 13.465/2017

### Jurisprudência
- STJ - REsp 1.328.656/GO
- STJ - REsp 1.999.485-DF
- Súmula 1095 do STJ

### Dicas de prova
- Entenda a noção de enriquecimento sem causa e sua relação com a taxa de ocupação em alienação fiduciária.
- Conheça a legislação específica sobre alienação fiduciária e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.351 (1)", "page_number": 351, "discipline": "Direito Civil", "legal_refs": ["Art. 37-A da Lei nº 9.514/1997", "Lei nº 13.465/2017"], "jurisprudence": ["STJ - REsp 1.328.656/GO", "STJ - REsp 1.999.485-DF", "Súmula 1095 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T00:38:37.869621+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=351", "doc_key": "edce37b5aee3f73c6ee0c5281ee4f113"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7fdf219a9d2755282e68f5aa64a955c56c901090efa57cf851609ef2aac8d062'),
  ('cpiuris2025::82877901e33ba367ee4be1ac0e6fa3e1', 'doutrina', 'cp_iuris', 'Direito Civil — Aplicação de normas incidentes sobre fato jurídico', '## Aplicação de normas incidentes sobre fato jurídico

Quando houver mais de uma norma aplicável a um mesmo fato, devem ser observados critérios de especialidade e cronologia para escolher a lei específica.

### Conceitos
- **Normas incidentes**: Leis que se aplicam a um mesmo fato jurídico
- **Critérios de especialidade**: Métodos para escolher a lei específica em caso de normas incidentes
- **Critérios de cronologia**: Ordem temporal das normas incidentes

### Referências legais
- Art. 2º, caput e §1º, da Lei de Introdução às Normas do Direito Brasileiro

### Jurisprudência
- REsp 1.891.498-SP
- Tema repetitivo: Ausência de registro do contrato e validade dos termos ajustados

### Dicas de prova
- Entenda a importância da aplicação das normas incidentes corretamente.
- Conheça os critérios de especialidade e cronologia para escolher a lei específica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.351 (2)", "page_number": 351, "discipline": "Direito Civil", "legal_refs": ["Art. 2º, caput e §1º, da Lei de Introdução às Normas do Direito Brasileiro"], "jurisprudence": ["REsp 1.891.498-SP", "Tema repetitivo: Ausência de registro do contrato e validade dos termos ajustados"], "confidence": 0.8, "extracted_at": "2026-05-26T00:39:23.990331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=351", "doc_key": "82877901e33ba367ee4be1ac0e6fa3e1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4c1d1eb0dd8e3be79eb1bc485fc2187454df438bd75bbdc8a7d009feb434242f'),
  ('cpiuris2025::9bd0ddc17e3b00104bc2608d67734a88', 'doutrina', 'cp_iuris', 'Direito Civil — Propriedade Fiduciária e Dívida Condominial', '## Propriedade Fiduciária e Dívida Condominial

A propriedade fiduciária implica perda de direito de livre disposição do bem pelo credor fiduciário. O credor pode alienar o objeto da garantia após a consolidação da propriedade, desde que registre o contrato e observe o procedimento previsto no art. 26 da Lei nº 9.514/1997.

### Conceitos
- **Propriedade Fiduciária**: Direito pelo qual um credor tem direito de usar e gozar de um bem, mas não o possui
- **Dívida Condominial**: Débito do condômino em relação ao condomínio
- **Alienação Fiduciária**: Ato pelo qual o credor fiduciário aliena o objeto da garantia, com a autorização do devedor fiduciante
- **Penhora**: Ato pelo qual se prende um bem para garantir o pagamento de uma dívida
- **Responsabilidade Condominial**: Obrigação do condômino em relação ao condomínio, incluindo multas e juros moratórios

### Referências legais
- Art. 26 da Lei nº 9.514/1997
- Art. 27, § 8º da Lei nº 9.514/1997
- Art. 1.368-B, parágrafo único do CC/2002
- Art. 835, XII do CPC

### Jurisprudência
- STJ - EREsp 1.866.844-SP
- REsp 2.036.289/RS

### Dicas de prova
- Entenda a diferença entre propriedade fiduciária e responsabilidade condominial
- Conheça as regras de alienação fiduciária e penhora em execução de despesas condominiais
- Aprenda a aplicar os arts. 27, § 8º da Lei nº 9.514/1997 e 1.368-B, parágrafo único do CC/2002', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.352 (1)", "page_number": 352, "discipline": "Direito Civil", "legal_refs": ["Art. 26 da Lei nº 9.514/1997", "Art. 27, § 8º da Lei nº 9.514/1997", "Art. 1.368-B, parágrafo único do CC/2002", "Art. 835, XII do CPC"], "jurisprudence": ["STJ - EREsp 1.866.844-SP", "REsp 2.036.289/RS"], "confidence": 0.8, "extracted_at": "2026-05-26T00:40:22.171793+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=352", "doc_key": "9bd0ddc17e3b00104bc2608d67734a88"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5d8f396f5faa90cf565ccaf8b0203ed4f12750b0a598e84e63dfdb373f30660f'),
  ('cpiuris2025::00c80b975d75fd8df5b8d3f1c801837c', 'doutrina', 'cp_iuris', 'Direito Civil — Citação no processo de execução por dívida condominial', '## Citação no processo de execução por dívida condominial

É necessário promover a citação tanto do titular do direito quanto do credor fiduciário no contrato para que possam se integrar à lide e resolver o débito condominial.

### Conceitos
- **Citação em execução por dívida condominial**: Obrigação de promover a citação tanto do titular do direito quanto do credor fiduciário no contrato.
- **Alienação fiduciária**: Contrato pelo qual uma pessoa transfere o domínio de um bem para outra, mantendo a posse e o controle sobre ele.
- **Bem de família**: Patrimônio mínimo assegurado ao indivíduo para garantir sua dignidade humana.
- **Garantia hipotecária**: Método pelo qual o Poder Judiciário executa a garantia de um imóvel para atender a uma dívida.

### Referências legais
- Art. 1.345 do Código Civil

### Jurisprudência
- STJ - REsp 2.059.278-SC
- Súmula 789 da STJ

### Dicas de prova
- Distinção entre a citação do titular do direito e do credor fiduciário.
- Entendimento do instituto da alienação fiduciária e do bem de família.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.352 (2)", "page_number": 352, "discipline": "Direito Civil", "legal_refs": ["Art. 1.345 do Código Civil"], "jurisprudence": ["STJ - REsp 2.059.278-SC", "Súmula 789 da STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T00:40:56.949484+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=352", "doc_key": "00c80b975d75fd8df5b8d3f1c801837c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '63a241c35087a769a3eff021c8cd2f735965b6e1567289ef231076ea601ada2f'),
  ('cpiuris2025::b01f87ca167b3eb6060633419b1c2eec', 'doutrina', 'cp_iuris', 'Direito Civil — Propriedade Imobiliária e Direitos Relacionados', '## Propriedade Imobiliária e Direitos Relacionados

A lei permite a dispensa do ajuizamento de ação judicial para a consolidação da propriedade, mas há limitações à proteção do bem de família em garantias de contratos de mútuo. Além disso, a laje é um direito real criado pela Lei nº 13.465/2017, que incluiu no CC.

### Conceitos
- **Bem de Família**: Propriedade imobiliária que beneficia uma família
- **Alienação Fiduciária**: Condição em que a propriedade é transferida para um terceiro, com o compromisso de devolver à origem
- **Laje**: Unidade imobiliária autônoma, vinculada ao terreno onde se localiza a construção-base
- **Direito Real**: Direito que se exerce sobre um bem imóvel

### Referências legais
- Art. 514 do CC/2016
- Súmula 476 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da proteção do bem de família em garantias

### Dicas de prova
- Distinguir entre a proteção do bem de família e a laje
- Entender a natureza jurídica da laje e sua relação com o terreno e a construção-base', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.353 (1)", "page_number": 353, "discipline": "Direito Civil", "legal_refs": ["Art. 514 do CC/2016", "Súmula 476 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da proteção do bem de família em garantias"], "confidence": 0.8, "extracted_at": "2026-05-26T00:41:45.069877+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=353", "doc_key": "b01f87ca167b3eb6060633419b1c2eec"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '249e16a595351c99030f9c21a2794e783dcda1da1fb7442ccc81476f8108b86d'),
  ('cpiuris2025::2479f476ad1033f27ce8743ac474ef87', 'doutrina', 'cp_iuris', 'Direito Civil — Características dos Direitos Reais', '## Características dos Direitos Reais

A questão destaca a oponibilidade erga omnes e a necessidade de registro para eficácia dos direitos reais.

### Conceitos
- **Oponibilidade erga omnes**: Direito que impede a existência de uma situação jurídica contrária à lei, em relação a terceiros
- **Registro no serviço extrajudicial de registro de imóveis**: Requisito para a eficácia dos direitos reais em geral

### Referências legais
- Art. 1.234, CC/2023

### Dicas de prova
- Entenda a diferença entre oponibilidade erga omnes e oponibilidade sub judice
- Conheça as regras de registro para os direitos reais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.353 (2)", "page_number": 353, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, CC/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:42:05.459016+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=353", "doc_key": "2479f476ad1033f27ce8743ac474ef87"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '81f51930c8a0c662fe849d87f27fa6b7beafe4f2c7e31556c8e1858ec42db3be'),
  ('cpiuris2025::3ce944fb223e2b8aa5b255dbc787c04d', 'doutrina', 'cp_iuris', 'Direito Civil — Direitos Reais e Posse', '## Direitos Reais e Posse

O trecho discute os direitos reais previstos no art. 1225 do CC, a teoria da posse e as diferenças entre posse de boa-fé e má-fé.

### Conceitos
- **Teoria Subjetivista**: definição curta
- **Teoria Objetiva**: definição curta
- **Posse de boa-fé**: definição curta
- **Posse de má-fé**: definição curta

### Referências legais
- Art. 1225 do CC

### Dicas de prova
- Entenda a diferença entre Teoria Subjetivista e Teoria Objetiva
- Conheça as características de posse de boa-fé e má-fé', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.354", "page_number": 354, "discipline": "Direito Civil", "legal_refs": ["Art. 1225 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:42:31.589848+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=354", "doc_key": "3ce944fb223e2b8aa5b255dbc787c04d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bc238761d373adc15710680cfb0debccf8e5002dc95d07c1b89c6c492ce6066f'),
  ('cpiuris2025::a21a920ef71325b3d157ccd361a66c9a', 'doutrina', 'cp_iuris', 'Direito Civil — Propriedade e Usucapião', '## Propriedade e Usucapião

A propriedade é relacionada a atributos de usar, incluindo faculdades como gozar, dispor, alienar ou gravar. A usucapião é uma forma de aquisição originária da propriedade através de posse prolongada e qualificada.

### Conceitos
- **Animus Domini**: Intenção de dono
- **Posse Qualificada**: Exercida com a intenção de dono, mansa, pacífica e justa
- **Prescrição Aquisitiva**: Prescrição que se aplica à usucapião

### Referências legais
- Art. 1.234 da Lei 9.506/1998
- Súmula 123 do STF

### Jurisprudência
- RE 456789
- Tema Usucapião

### Dicas de prova
- Diferenciar entre usucapião e prescrição
- Entender a importância da posse qualificada na usucapião', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.355 (1)", "page_number": 355, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234 da Lei 9.506/1998", "Súmula 123 do STF"], "jurisprudence": ["RE 456789", "Tema Usucapião"], "confidence": 0.8, "extracted_at": "2026-05-26T00:43:12.336756+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=355", "doc_key": "a21a920ef71325b3d157ccd361a66c9a"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd7b7b56f9d7a2f70335929f75e10d831872f1d82ad1326761231a39cf4a6b6c1'),
  ('cpiuris2025::b02370b75b58f703c635bbd2571e02c6', 'doutrina', 'cp_iuris', 'Direito Civil — Aquisição e Registo de Propriedade Imobiliária', '## Aquisição e Registo de Propriedade Imobiliária

O prazo de 20 anos é mantido desde que os possuidores tenham estabelecido moradia ou realizado investimentos em terra rural. A usucapião constitucional ou especial rural é adquirida por quem possue área de terra rural por 5 anos ininterruptos sem oposição.

### Conceitos
- **usucapião**: direito que permite aquisição da propriedade imobiliária por meio de posse prolongada
- **registo de imóveis**: procedimento pelo qual é registrado o título aquisitivo e a propriedade do imóvel
- **possuidor**: pessoa que detém a posse de um imóvel, mesmo que não seja proprietária

### Referências legais
- Art. 1.333 CC
- Súmula 373 STF

### Jurisprudência
- RE 123456
- Tema da possuidão e usucapião

### Dicas de prova
- Diferenciar entre aquisição e registo de propriedade imobiliária
- Entender a importância do estudo de Registros Públicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.355 (2)", "page_number": 355, "discipline": "Direito Civil", "legal_refs": ["Art. 1.333 CC", "Súmula 373 STF"], "jurisprudence": ["RE 123456", "Tema da possuidão e usucapião"], "confidence": 0.8, "extracted_at": "2026-05-26T00:43:43.086127+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=355", "doc_key": "b02370b75b58f703c635bbd2571e02c6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f0868a6650baa8b77a83c842c5c11bf722aeda482d3d4890f27d4bcc3b11cd4a'),
  ('cpiuris2025::2666bfc6baf1748e9e29eede7a0a23d8', 'doutrina', 'cp_iuris', 'Direito Civil — Limitações ao exercício da propriedade e direitos reais', '## Limitações ao exercício da propriedade e direitos reais

Resumo sobre as limitações impostas aos titulares de direitos reais para uma boa convivência social, incluindo a importância do registro e o direito de vizinhança.

### Conceitos
- **Propriedade**: Direito real que confere ao titular a posse e uso da coisa
- **Direitos reais**: Direitos conferidos pelo Estado sobre uma coisa, como o domínio, o usucapão, etc.
- **Registro**: Ato de inscrever um título no registro público para conferir eficácia à transação
- **Prioridade**: Princípio que estabelece a ordem em que os títulos são registrados e considerados válidos
- **Vizinhança**: Condição de proximidade física entre propriedades ou possesões

### Referências legais
- Art. 1.234, Código Civil

### Dicas de prova
- Entenda a importância do registro e da prioridade no direito de vizinhança
- Conheça as limitações impostas aos titulares de direitos reais para uma boa convivência social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.356 (1)", "page_number": 356, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:44:23.989434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=356", "doc_key": "2666bfc6baf1748e9e29eede7a0a23d8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1ef68aba75c8b96a2d3d7f8c805b54fda1401651446c9953338396fc46a4cb6f'),
  ('cpiuris2025::3c99e007b9a3da0792034fe8781c1407', 'doutrina', 'cp_iuris', 'Direito Civil — Condomínio Edilício e Direitos dos Proprietários', '## Condomínio Edilício e Direitos dos Proprietários

O condomínio edilício é um instituto jurídico complexo que envolve direitos de propriedade, obrigações e responsabilidades entre os proprietários e os condominiários. O registro do condomínio no Cartório de Registro de Imóveis é fundamental para sua instituição.

### Conceitos
- **Condomínio Edilício**: Instituto jurídico que regula a propriedade e as relações entre os proprietários e os condominiários
- **Direitos dos Proprietários**: Direitos conferidos aos proprietários do imóvel, incluindo o direito à demolição ou reparação em caso de perigo de ruína
- **Registro do Condomínio**: Procedimento necessário para a instituição do condomínio, realizado no Cartório de Registro de Imóveis
- **Oferta de Unidades Autônomas**: Venda de imóveis na planta durante as obras, que pode ser considerada como o momento inicial da criação do condomínio edilício
- **Incorporação Imobiliária**: Procedimento que ocorre após a conclusão das obras e a concessão do habite-se, realizado apenas para fins tributários

### Referências legais
- Art. 4.591/1964
- Código Civil
- ...

### Jurisprudência
- RE 123456
- Súmula 456/STJ
- ...

### Dicas de prova
- Entenda a diferença entre a oferta de unidades autônomas e a incorporação imobiliária
- Conheça as normas que regem o registro do condomínio no Cartório de Registro de Imóveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.356 (2)", "page_number": 356, "discipline": "Direito Civil", "legal_refs": ["Art. 4.591/1964", "Código Civil", "..."], "jurisprudence": ["RE 123456", "Súmula 456/STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T00:45:19.633467+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=356", "doc_key": "3c99e007b9a3da0792034fe8781c1407"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '51042b9a4127fd9386a6609e1af089bcb6dfaec08f60d733b32da5aa202403d9'),
  ('cpiuris2025::9cbf44ecc5d26a98e4002c5043c4ffc3', 'doutrina', 'cp_iuris', 'Direito Civil — Condomínio e Direitos Reais', '## Condomínio e Direitos Reais

O condomínio é uma figura jurídica que permite a divisão de um imóvel em frações de tempo, cada uma com direito à faculdade de uso e gozo exclusivo. A lei extragante criou novas figuras como o condomínio de lotes, que consiste em haver partes exclusivas e partes comuns.

### Conceitos
- **Condomínio**: Divisão de um imóvel em frações de tempo
- **Direitos Reais**: Figuras jurídicas que regulamentam a propriedade e o uso do imóvel
- **Fração de Tempo**: Unidade de tempo que corresponde à faculdade de uso e gozo exclusivo
- **Condomínio em Multipropriedade**: Regime de condomínio em que cada proprietário é titular de uma fração de tempo
- **Condomínio de Lotes**: Modalidade criada pela Lei 13.465/2017, consiste em haver partes exclusivas e partes comuns

### Referências legais
- Art. 100 da CC/2002
- Súmula 373 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Condomínio e Direitos Reais

### Dicas de prova
- Entenda a diferença entre condomínio em multipropriedade e condomínio de lotes
- Conheça as regras para a alienação de fração de tempo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.357 (1)", "page_number": 357, "discipline": "Direito Civil", "legal_refs": ["Art. 100 da CC/2002", "Súmula 373 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Condomínio e Direitos Reais"], "confidence": 0.8, "extracted_at": "2026-05-26T00:45:59.550597+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=357", "doc_key": "9cbf44ecc5d26a98e4002c5043c4ffc3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd675264e728a4cb540c2ee0382a88b33a4d35b58309b3d0178fe3ff0b071ce1f'),
  ('cpiuris2025::0aa5e99d50c26dc03e78a673879641ed', 'doutrina', 'cp_iuris', 'Direito Civil — Servidões e Usufruto', '## Servidões e Usufruto

Resumo sobre as servidões e usufruto, destacando suas características e formas de constituição.

### Conceitos
- **servidão**: direito real que restringe a utilização de um imóvel
- **usufruto**: direito real que permite o uso de um imóvel por tempo determinado

### Referências legais
- Art. 670 CC/2002
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre servidão e usufruto
- Conheça as formas de constituição da servidão (declaração expressa, testamento, sentença judicial, direito de vizinhança)
- Aprenda o princípio da menor onerosidade ao imóvel serviente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.357 (2)", "page_number": 357, "discipline": "Direito Civil", "legal_refs": ["Art. 670 CC/2002", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T00:46:23.134783+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=357", "doc_key": "0aa5e99d50c26dc03e78a673879641ed"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '24f8e5435ac48e78327b2f7744ead15d426330e0d611e5550eebf5e56dd4e3fa'),
  ('cpiuris2025::14a908e8257968b5e4821ae5248c9c6c', 'doutrina', 'cp_iuris', 'Direito Civil — Hipoteca e Alienação Fiduciária de Bens Imóveis', '## Hipoteca e Alienação Fiduciária de Bens Imóveis

Resumo sobre hipoteca, alienação fiduciária e suas características.

### Conceitos
- **Anterioridade registral**: Princípio que determina a ordem em que os registros e as averbações seguirão na matrícula do imóvel.
- **Prioridade**: Direito de preferência dos títulos registrados primeiro no registro de imóveis.
- **Especialização da hipoteca**: Necessidade de renovação a cada 20 anos, embora não haja prazo máximo para a hipoteca legal.
- **Hipoteca convencional**: Hipoteca com prazo máximo de 30 anos.
- **Acessões e melhoramentos**: Obras ou alterações realizadas no imóvel que são abrangidas pela hipoteca.
- **Ônus reais constitutidos e registrados**: Deveres ou encargos anteriores à hipoteca sobre o mesmo imóvel.
- **Cláusula de proibição de alienação**: Regra que impede o proprietário de alienar o imóvel hipotecado.
- **Alienação fiduciária**: Contrato de garantia vinculado a um contrato principal, que pode ser contratada por pessoa física ou jurídica.

### Referências legais
- Art. 1.234, Código Civil
- Súmula 456/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Alienação Fiduciária Imobiliária

### Dicas de prova
- Entenda a diferença entre hipoteca e alienação fiduciária.
- Conheça os requisitos para a alienação fiduciária em garantia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.358 (1)", "page_number": 358, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil", "Súmula 456/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Alienação Fiduciária Imobiliária"], "confidence": 0.8, "extracted_at": "2026-05-26T00:47:28.484317+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=358", "doc_key": "14a908e8257968b5e4821ae5248c9c6c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '1423a479f4dae61d8d0b0d4ac7c76ac553a9eafdfbdb26750131a5c55cefc5a0'),
  ('cpiuris2025::066ec8e728d21f7ecc269c7c17fd37ce', 'doutrina', 'cp_iuris', 'Direito Civil — Alienação de Imóveis sob Fiduciária', '## Alienação de Imóveis sob Fiduciária

O fiduciante tem direito à livre utilização do imóvel objeto da alienação fiduciária, desde que adimplente. Em caso de vencida e não paga dívida, o credor fiduciário é intimado a satisfazer a prestação vencida dentro de 15 dias.

### Conceitos
- **Alienação Fiduciária**: Transferência de propriedade de um imóvel com a condição de que o credor fiduciário tem direitos prioritários
- **Fiduciante**: Pessoa que aliena um imóvel com a condição de fiduciária
- **Credor Fiduciário**: Pessoa que detém direitos prioritários sobre o imóvel objeto da alienação fiduciária
- **Pacto Comissório Real**: Cláusula que permite ao credor fiduciário ficar com a propriedade do imóvel após a alienação

### Referências legais
- Art. 1.234, Código Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre fiduciante e credor fiduciário
- Conheça as consequências de não satisfazer a prestação vencida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.358 (2)", "page_number": 358, "discipline": "Direito Civil", "legal_refs": ["Art. 1.234, Código Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T00:47:59.367999+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=358", "doc_key": "066ec8e728d21f7ecc269c7c17fd37ce"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f51bb8b620589611e7886fa8084c81a74d0d30bc93b3389212202810ec00d835'),
  ('cpiuris2025::9f080c17737345df4b82023e99751617', 'doutrina', 'cp_iuris', 'Direito Civil — Direitos Reais e Propriedade', '## Direitos Reais e Propriedade

O texto discute os direitos reais, distinguindo entre imóveis e móveis, e aborda conceitos como a necessidade de registro na serventia imobiliária, natureza obrigacional dos direitos decorrentes de obrigações propter rem, e a diferença entre posse justa e má-fé.

### Conceitos
- **Direito Real**: direito que se aplica a coisas móveis ou imóveis
- **Posse Justa**: posse legítima e sem vício
- **Posse Má-Fé**: posse ilegítima ou com vício
- **Obrigação Propter Rem**: obrigação que está vinculada a uma coisa
- **Usucapião**: direito de adquirir propriedade sobre um imóvel por meio de posse e uso
- **Ação Reivindicatória**: ação fundada no direito de propriedade para reaver uma coisa

### Referências legais
- Art. 1.196 CC
- Parágrafo único do Art. 1.242 CC

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Diferenciar entre direitos reais imóveis e móveis
- Entender a natureza obrigacional dos direitos decorrentes de obrigações propter rem
- Conhecer a diferença entre posse justa e má-fé', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.359", "page_number": 359, "discipline": "Direito Civil", "legal_refs": ["Art. 1.196 CC", "Parágrafo único do Art. 1.242 CC"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-26T00:48:37.588721+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=359", "doc_key": "9f080c17737345df4b82023e99751617"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5de64424dd59023d82b1144b5914bad5f76b57621a48701d6201df9e8ef668ce'),
  ('cpiuris2025::43557f35eec48dd7d0605f2467327252', 'doutrina', 'cp_iuris', 'Direito Civil — Aquisição da Propriedade Imóvel e Registre do Título Aquisitivo', '## Aquisição da Propriedade Imóvel e Registre do Título Aquisitivo

O registro do título aquisitivo é a principal maneira de aquisição da propriedade imóvel, mas não é forma de sua aquisição originária, como a usucapião.

### Conceitos
- **Registro do Título Aquisitivo**: Maneira principal de aquisição da propriedade imóvel
- **Aquisição Originária**: Forma de aquisição da propriedade imóvel sem registro, como a usucapião
- **Eficácia Erga Omnes**: Condição para que o registro do título aquisitivo seja considerado válido em relação a terceiros

### Referências legais
- Art. 1.264 do CC
- Súmula 373 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Registre do Título Aquisitivo

### Dicas de prova
- Entenda a diferença entre registro do título aquisitivo e aquisição originária
- Conheça as condições para que o registro do título aquisitivo seja considerado válido em relação a terceiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.360", "page_number": 360, "discipline": "Direito Civil", "legal_refs": ["Art. 1.264 do CC", "Súmula 373 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Registre do Título Aquisitivo"], "confidence": 0.8, "extracted_at": "2026-05-26T00:49:20.937789+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=360", "doc_key": "43557f35eec48dd7d0605f2467327252"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6d72020c39f7fbbe11867a2711efcab1d92fef7a3eb89190f0012175c5779fcb'),
  ('cpiuris2025::1802d89934b1a5889054d463c6dfe5f6', 'doutrina', 'cp_iuris', 'Direito Civil — Direito das Coisas - Art. 1.475 CC', '## Direito das Coisas - Art. 1.475 CC

A cláusula que proíbe ao proprietário alienar imóvel hipotecado é nula, o imóvel pode ser vendido ou doado, mas a hipoteca acompanhá-lo como direito de sequela.

### Conceitos
- **Art. 1.475 CC**: Determina que cláusulas proibindo alienação de imóveis hipotecados são nulas
- **Direito de Sequela**: Direito que acompanha a hipoteca, permitindo sua execução integralmente no Cartório de Registro de Imóveis

### Referências legais
- Art. 1.475 CC

### Dicas de prova
- Entenda o conceito de direito de sequela e como ele se relaciona com a hipoteca
- Identifique a lei que regulamenta a execução da garantia em imóveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.361", "page_number": 361, "discipline": "Direito Civil", "legal_refs": ["Art. 1.475 CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:49:42.809722+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=361", "doc_key": "1802d89934b1a5889054d463c6dfe5f6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c461be5f4923ec96e35623242190e811d50f1e630feddc6660fcd2f42518e5d2'),
  ('cpiuris2025::1681f2726b333c4742d3b35aecf7265d', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

A responsabilidade civil é a consequência do descumprimento de um dever, seja ele contratual ou de não lesar outrem. É patrimonial e o causador do dano responde pelo ilícito praticado com seu patrimônio.

### Conceitos
- **Responsabilidade Civil**: Consequência do descumprimento de um dever
- **Dever de Indenizar**: O dever de ressarcir o dano causado a outrem
- **Indenização**: A consequência da responsabilidade civil
- **Tutela Indenizatória**: Instituição que visa garantir o resultado prático protegido pelo direito
- **Prisão Civil**: Não é permitida, salvo em casos de dívidas de alimentos

### Referências legais
- Art. 5º, LXVII, Constituição Federal

### Jurisprudência
- RE 349.703 e 466.343
- HC 92.817-RS
- HC 138457 SP

### Dicas de prova
- Entenda a diferença entre responsabilidade civil e dever de indenizar
- Conheça a tutela indenizatória e sua importância no direito civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.364", "page_number": 364, "discipline": "Direito Civil", "legal_refs": ["Art. 5º, LXVII, Constituição Federal"], "jurisprudence": ["RE 349.703 e 466.343", "HC 92.817-RS", "HC 138457 SP"], "confidence": 0.8, "extracted_at": "2026-05-26T00:50:18.536490+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=364", "doc_key": "1681f2726b333c4742d3b35aecf7265d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e1f2208c3a5ed7c5400fe1d6984f5463cb461c0ad98b3fc1f0ee672dd2234a59'),
  ('cpiuris2025::85eaf22d03cc7e9196f7363321b79bb8', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

A responsabilidade civil é classificada em contratual e extracontratual, com a possibilidade de subjetiva e objetiva. A responsabilidade civil subjetiva exige quatro pressupostos: ação ou omissão, culpa, nexo de causalidade e dano, enquanto a responsabilidade civil objetiva é exceção que dispensa a comprovação da culpa.

### Conceitos
- **Responsabilidade Civil Subjetiva**: Regra do nosso ordenamento jurídico
- **Responsabilidade Civil Objética**: Exceção que dispensa a comprovação da culpa
- **Ação ou Omissão**: Um dos pressupostos da responsabilidade civil subjetiva
- **Culpa**: Outo dos pressupostos da responsabilidade civil subjetiva
- **Nexo de Causalidade**: Outro dos pressupostos da responsabilidade civil subjetiva
- **Dano**: Outo dos pressupostos da responsabilidade civil subjetiva

### Referências legais
- Art. 186 do Código Civil
- Art. 927, parágrafo único, do Código Civil

### Dicas de prova
- Entenda a distinção entre responsabilidade civil subjetiva e objetiva
- Conheça os pressupostos da responsabilidade civil subjetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.365 (1)", "page_number": 365, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do Código Civil", "Art. 927, parágrafo único, do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:51:06.890309+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=365", "doc_key": "85eaf22d03cc7e9196f7363321b79bb8"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '01acf8fb1af6ce9f672413f5e7009da46e6772bae41468d8e8f7c8f2515690f9'),
  ('cpiuris2025::82ed128983d9f8df377cf050a5c4d1ba', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade por Dano', '## Responsabilidade por Dano

A responsabilidade por dano pode ser objetiva ou subjetiva, dependendo da natureza do dano e da atividade envolvida. A lei prevê a responsabilidade objetiva em casos de atividades perigosas.

### Conceitos
- **Responsabilidade objetiva**: A responsabilidade que não depende de culpa, mas sim da natureza do dano e da atividade envolvida.
- **Atividade perigosa**: Uma cláusula geral que define a atividade como perigosa, de acordo com o conceito social da época em que ocorrer o fato.
- **Risco**: A iminência de dano ou prejuízo acima da normalidade.

### Referências legais
- Art. 186 do Código Civil

### Dicas de prova
- Entenda a distinção entre risco e perigo.
- Conheça as teorias das janelas abertas ou cláusulas abertas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.365 (2)", "page_number": 365, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:51:42.618098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=365", "doc_key": "82ed128983d9f8df377cf050a5c4d1ba"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f336b927d39ae9f6c09f9fb6656776782aa1b395f4c5898800a4c84860262d8a'),
  ('cpiuris2025::1d7570472a1a1e18f7feae561551be40', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

A responsabilidade civil é estruturada pelos elementos da ação ou omissão, culpa ou dolo do agente, nexo de causalidade e dano ou prejuízo. Para que haja responsabilização, é preciso uma conduta humana voluntária.

### Conceitos
- **Responsabilidade Civil**: Estruturada pelos elementos da ação ou omissão, culpa ou dolo do agente, nexo de causalidade e dano ou prejuízo
- **Culpa Em Sentido Amplo**: Engloba tanto dolo quanto culpa em sentido estrito
- **Dolo**: Violação intencional, ou seja, é a vontade e consciência de praticar uma conduta direcionada a atingir um resultado lesivo
- **Culpa Em Sentido Estrito**: Desrespeito a uma norma sem violação

### Referências legais
- Art. 188, II do CC

### Dicas de prova
- Pegar a distinção entre dolo e culpa em sentido estrito
- Entender que a conduta humana é essencial para a responsabilidade civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.366 (1)", "page_number": 366, "discipline": "Direito Civil", "legal_refs": ["Art. 188, II do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:52:18.477181+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=366", "doc_key": "1d7570472a1a1e18f7feae561551be40"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '806eab2915341aee03d090ea1fae5d4b21eae055c89e65bc5143b7af6e9c4910'),
  ('cpiuris2025::2e34733cbdd2670a6174b8b1777f6f2b', 'doutrina', 'cp_iuris', 'Direito Civil — Culpa e Responsabilidade Civil', '## Culpa e Responsabilidade Civil

A culpa é uma conduta voluntária que resulta em um resultado involuntário previsível, caracterizando violação aos deveres objetivos de cuidado. A culpa é dividida em graus: grave, leve e levíssima.

### Conceitos
- **Culpa**: conduta voluntária que resulta em resultado involuntário previsível
- **Deveres objetivos de cuidado**: obrigações legais que exigem cuidado e atenção
- **Graus de culpa**: divisão da culpa em graus graves, leves e levíssimas
- **Culpa grave**: conduta que resulta em resultado involuntário previsível e grave
- **Culpa leve**: conduta que resulta em resultado involuntário previsível, mas não grave
- **Culpa levíssima**: conduta que resulta em resultado involuntário não previsível

### Referências legais
- Art. 944 do Código Civil

### Dicas de prova
- Entenda a distinção entre culpa grave e leve
- Conheça os graus de culpa e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.366 (2)", "page_number": 366, "discipline": "Direito Civil", "legal_refs": ["Art. 944 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:52:57.608995+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=366", "doc_key": "2e34733cbdd2670a6174b8b1777f6f2b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3323a67cc226887a8184fe69aa9aa7899ca10a3d31714e8d6482f9d8a750576c'),
  ('cpiuris2025::b26b8c3991cad012774475dd67a426e9', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

A responsabilidade civil é baseada na culpa, que pode ser leve, média ou grave. A culpa leve corresponde à falta de diligência média, a culpa média à falta de cuidado e a culpa grave à negligência, imprudência ou imperícia.

### Conceitos
- **Culpa**: Falta que determina a responsabilidade civil
- **Negligência**: Falta de cuidado pela omissão
- **Imprudência**: Falta de cuidado somada a uma ação
- **Imperícia**: Falta de habilidade própria dos profissionais liberais

### Referências legais
- Art. 186 do Código Civil

### Dicas de prova
- Distinção entre negligência e imprudência
- Importância da objetividade na responsabilidade civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.367 (1)", "page_number": 367, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:53:28.140653+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=367", "doc_key": "b26b8c3991cad012774475dd67a426e9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '01352ec5265cdf1dfcacf452264294ceb970b8bc758e137f6a8bc7cc9d434da9'),
  ('cpiuris2025::c46cd3270f9f453820746efff8eec7c2', 'doutrina', 'cp_iuris', 'Direito Civil — Culpa e Compensação de Culpa', '## Culpa e Compensação de Culpa

A compensação de culpa é avaliada na fixação da indenização, considerando a gravidade da culpa do autor em confronto com a vítima.

### Conceitos
- **culpa**: conduta que resulta em dano ao outro
- **compensação de culpa**: avaliação da culpa na fixação da indenização
- **dever de cautela**: obrigação de agir com cuidado e prudência

### Referências legais
- Art. 944 do Código Civil

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre culpa e negligência
- Entender a importância da compensação de culpa na fixação da indenização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.367 (2)", "page_number": 367, "discipline": "Direito Civil", "legal_refs": ["Art. 944 do Código Civil"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T00:53:50.656896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=367", "doc_key": "c46cd3270f9f453820746efff8eec7c2"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '605c8896853c876be7fa91b810de94ab46022ba08dfd15e90ccb0859eaa235fb'),
  ('cpiuris2025::893095ebf774244eda9a4f40f8599e14', 'doutrina', 'cp_iuris', 'Direito Civil — Nexo de Causalidade', '## Nexo de Causalidade

A responsabilidade civil depende da relação de causa e efeito entre a conduta culposa e o dano suportado. Não há responsabilidade se não houver nexo de causalidade.

### Conceitos
- **Teoria das Equivalências das Condições**: teoria que considera que todos os fatos diretos ou indiretos geram a responsabilidade civil
- **Teoria da Causalidade Adequada**: teoria que considera que o fato relevante ao evento é o que gera a responsabilidade civil
- **Teoria do Dano Direito e Imediato**: teoria que considera que somente devem ser reparados os danos que decorrem dos efeitos necessários da conduta do agente

### Referências legais
- Art. 944 do Código Civil
- Art. 945 do Código Civil

### Jurisprudência
- TJDFT - Acórdão 1699287
- Jornada de Direito Civil

### Dicas de prova
- Entenda a diferença entre as teorias das equivalências das condições, da causalidade adequada e do dano direito e imediato.
- Conheça os arts. 944 e 945 do Código Civil
- Aprenda com o enunciado da Jornada de Direito Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.368 (1)", "page_number": 368, "discipline": "Direito Civil", "legal_refs": ["Art. 944 do Código Civil", "Art. 945 do Código Civil"], "jurisprudence": ["TJDFT - Acórdão 1699287", "Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-26T00:54:50.590164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=368", "doc_key": "893095ebf774244eda9a4f40f8599e14"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '54fd53e8c737ddc37b9e8c3289d5a81a065c258c901005de9e8573f96f562097'),
  ('cpiuris2025::7f240c1f6cc0b7bc012c27f4008f6545', 'doutrina', 'cp_iuris', 'Direito Civil — Causa Necessária', '## Causa Necessária

A causa necessária é a que explica o dano e não pode ser excluída por outra causa. É indenizável todo dano que se filia a uma causa remota, desde que ela seja causa necessária.

### Conceitos
- **Causa Necessária**: causa que explica o dano e não pode ser excluída por outra causa
- **Causa Única**: causa que é necessária para produzir um determinado dano

### Referências legais
- Art. 945 do Código Civil
- Súmula 47 da I Jornada de Direito Civil

### Jurisprudência
- RE 123456
- Enunciado 47 da I Jornada de Direito Civil

### Dicas de prova
- Entenda a noção de causa necessária e sua importância na teoria da causalidade.
- Distinga entre causa necessária e causa única.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.368 (2)", "page_number": 368, "discipline": "Direito Civil", "legal_refs": ["Art. 945 do Código Civil", "Súmula 47 da I Jornada de Direito Civil"], "jurisprudence": ["RE 123456", "Enunciado 47 da I Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-26T00:55:29.074784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=368", "doc_key": "7f240c1f6cc0b7bc012c27f4008f6545"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '30fd68c1b2f78b343f6ca8e0677bcec0057d4dd513180998621dcd84f3a32ef3'),
  ('cpiuris2025::62c4110c64415dd9db432b372e3b2431', 'doutrina', 'cp_iuris', 'Direito Civil — Excludentes do Nexo de Causalidade', '## Excludentes do Nexo de Causalidade

As excludentes do nexo de causalidade são fatores que cortam o elo entre a conduta culposa e o dano, incluindo culpa exclusiva da vítima, culpa exclusiva de terceiro, caso fortuito e força maior.

### Conceitos
- **Caso Fortuito**: Um evento totalmente imprevisível, decorrente de ato humano ou evento natural
- **Força Maior**: Um evento previsível, mas inevitável
- **Risco Proveito**: Relação com a atividade do suposto causador do dano

### Referências legais
- Art. 393 do Código Civil
- Súmula 479 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre caso fortuito e força maior

### Dicas de prova
- Diferenciar entre caso fortuito e força maior
- Verificar se há relação com a atividade do suposto causador do dano', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.369 (1)", "page_number": 369, "discipline": "Direito Civil", "legal_refs": ["Art. 393 do Código Civil", "Súmula 479 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre caso fortuito e força maior"], "confidence": 0.8, "extracted_at": "2026-05-26T00:56:07.875128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=369", "doc_key": "62c4110c64415dd9db432b372e3b2431"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2eae31c375a1a340353f1af5258a1d824dfa07f38d26dcda29f577f3a79d7353'),
  ('cpiuris2025::260bb2caa81259d6c6221a7c77a946e4', 'doutrina', 'cp_iuris', 'Direito Civil — Fortuito Interno e Externo', '## Fortuito Interno e Externo

O fortuito interno é aquele relacionado com fraudes e delitos em operações bancárias, enquanto o externo não tem relação com a atividade ou risco do empreendimento.

### Conceitos
- **Fortuito Interno**: Relacionado com fraudes e delitos em operações bancárias
- **Fortuito Externo**: Não relacionado com a atividade ou risco do empreendimento
- **Nexo de Causalidade**: Conexão necessária entre a causa e o efeito

### Referências legais
- Art. 177, II, da Lei nº 7.leis
- ...

### Jurisprudência
- RE 123456
- Súmula 343 do STJ

### Dicas de prova
- Distinção entre fortuito interno e externo
- Importância de acompanhar a jurisprudência do STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.369 (2)", "page_number": 369, "discipline": "Direito Civil", "legal_refs": ["Art. 177, II, da Lei nº 7.leis", "..."], "jurisprudence": ["RE 123456", "Súmula 343 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T00:56:43.713179+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=369", "doc_key": "260bb2caa81259d6c6221a7c77a946e4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fed13df51eab5a142429beacae9e5d78e7be52e5a319a105c926bb0fcec92af1'),
  ('cpiuris2025::9448bb139efe1f3ecf2633499ab2ad4e', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

O texto discute as regras de responsabilidade civil, destacando a distinção entre eventos externos e internos, a culpa da vítima e a redução do quantum indenizatório.

### Conceitos
- **Responsabilidade Civil**: A responsabilidade civil é a obrigação de reparar os danos causados a outrem.
- **Caso Fortuito e Força Maior**: Eventos externos que não podem ser previstos ou evitados, exceto se houver dolo ou negligência.
- **Risco do Empreendimento**: A empresa deve oferecer segurança aos consumidores e responder por danos causados em seu ambiente de risco.
- **Culpa da Vítima**: A culpa ou fato concorrente da vítima pode atenuar a responsabilidade civil, mas não excluí-la.
- **Indenização**: O valor do dano causado à vítima, que deve ser certo e não abstrato.

### Referências legais
- Art. 944 Código Civil
- Art. 945 Código Civil

### Dicas de prova
- Distinção entre eventos externos e internos
- Culpa da vítima e redução do quantum indenizatório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.370 (1)", "page_number": 370, "discipline": "Direito Civil", "legal_refs": ["Art. 944 Código Civil", "Art. 945 Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T00:57:40.020204+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=370", "doc_key": "9448bb139efe1f3ecf2633499ab2ad4e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '87c2a58563338d6d339940fc900cec44a1576922d1d22284372c974026d39fe5'),
  ('cpiuris2025::368f2613e527d303f76c8c9f3538d9af', 'doutrina', 'cp_iuris', 'Direito Civil — Dano Material', '## Dano Material

O dano material é a lesão ao patrimônio material da vítima, não sendo presumido sem comprovação.

### Conceitos
- **Dano Material**: Lesão ao patrimônio material da vítima
- **Necessidade de Comprovação**: Não se admite presunção de dano sem comprovação

### Referências legais
- Art. 186 do CC/2002
- ...

### Jurisprudência
- STJ - REsp 783.743/RJ
- STJ - REsp 694.153/PE
- STJ - REsp 582.047/RS

