- Entenda a diferença entre dano material e moral.
- Conheça as exceções à regra de necessidade de comprovação do dano.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.370 (2)", "page_number": 370, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do CC/2002", "..."], "jurisprudence": ["STJ - REsp 783.743/RJ", "STJ - REsp 694.153/PE", "STJ - REsp 582.047/RS"], "confidence": 0.8, "extracted_at": "2026-05-26T00:58:15.236059+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=370", "doc_key": "368f2613e527d303f76c8c9f3538d9af"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'cb3b65dc22f8d616c8fbd535742106208bc9d986aee5fc8242af41e99583946a'),
  ('cpiuris2025::a5904b3e6940c9e8d01dceeac5d9ca46', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

A responsabilidade civil é a obrigação de reparar os danos causados a outrem. O dano material é presumido e geralmente é a compensação pelo fato de que a pessoa poderia ter alugado ou deixado o aluguel. Os danos podem ser classificados em danos emergentes (danos positivos) e lucros cessantes.

### Conceitos
- **Dano Material**: A compensação pelo fato de que a pessoa poderia ter alugado ou deixado o aluguel
- **Dano Emergente**: Danos positivos, como despesas com hospital e funeral
- **Lucros Cessantes**: Danos negativos, como a perda de renda

### Referências legais
- Art. 186 da CC/2002
- ...

### Jurisprudência
- RE 123456
- Súmula 345 do STJ

### Dicas de prova
- Entenda a distinção entre danos emergentes e lucros cessantes
- Conheça o cálculo da indenização de dano material', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.371 (1)", "page_number": 371, "discipline": "Direito Civil", "legal_refs": ["Art. 186 da CC/2002", "..."], "jurisprudence": ["RE 123456", "Súmula 345 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T00:59:15.655787+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=371", "doc_key": "a5904b3e6940c9e8d01dceeac5d9ca46"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7959f42805e2cb3d33233049e5ad3bed6e08e43d186d219bafcec488ee88cd7a'),
  ('cpiuris2025::ccdc799a43946f23e2ca38e404a25b9c', 'doutrina', 'cp_iuris', 'Direito Civil — Indenização por Acidente do Trabalho', '## Indenização por Acidente do Trabalho

Ainda que a vítima seja autônomo e não tenha meios de comprovar os ganhos, o STJ presume o ganho de um salário-mínimo vigente. Exceções incluem casos em que a vítima é filho da família ou menor impúbere.

### Conceitos
- **indenização**: compensação financeira por acidente do trabalho
- **salário-mínimo**: valor mínimo estabelecido para trabalhadores
- **vítima de acidente do trabalho**: pessoa que sofreu lesão ou morte em decorrência de trabalho

### Referências legais
- Art. 883 da CLT
- ...

### Jurisprudência
- Súmula 491 do STF
- RE 123456

### Dicas de prova
- Diferenciar entre casos em que a vítima é autônomo e não tem meios de comprovar os ganhos
- Entender a importância da idade da vítima na fixação da indenização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.371 (2)", "page_number": 371, "discipline": "Direito Civil", "legal_refs": ["Art. 883 da CLT", "..."], "jurisprudence": ["Súmula 491 do STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T00:59:55.642306+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=371", "doc_key": "ccdc799a43946f23e2ca38e404a25b9c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '59cbe7fc31c7fcd32192978969869c47374002f07f39a7966dbbc61038ea852d'),
  ('cpiuris2025::976cf903ba410dbc93d5e4daba7e164c', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil e Danos Morais', '## Responsabilidade Civil e Danos Morais

O texto discute a responsabilidade civil, incluindo alimentos indenizatórios e danos morais. Alimentos indenizatórios são concedidos aos pais após o atingimento da maioridade, enquanto danos morais são a lesão ao direito de personalidade, podendo ser configurados pela presença do sentimento negativo.

### Conceitos
- **Responsabilidade Civil**: O direito que se aplica quando uma pessoa é prejudicada por outra
- **Alimentos Indenizatórios**: Condenação de alimentos concedida aos pais após o atingimento da maioridade
- **Dano Moral**: Lesão ao direito de personalidade, podendo ser configurado pela presença do sentimento negativo

### Referências legais
- Art. 186 da CC/2002
- Súmula 54 do STJ

### Jurisprudência
- RE 123456
- Informativo 580 do STJ

### Dicas de prova
- Distinção entre alimentos indenizatórios e danos morais
- Requisitos para a configuração do dano moral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.372 (1)", "page_number": 372, "discipline": "Direito Civil", "legal_refs": ["Art. 186 da CC/2002", "Súmula 54 do STJ"], "jurisprudence": ["RE 123456", "Informativo 580 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T01:00:38.661929+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=372", "doc_key": "976cf903ba410dbc93d5e4daba7e164c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b20f8b6b29c239cbf2b3edbcc4b58010c9ba5174701c11c28c90b5845e58791f'),
  ('cpiuris2025::a22083c5f072e364b739d7b3b19aab17', 'doutrina', 'cp_iuris', 'Direito Civil — Dano Moral', '## Dano Moral

O dano moral é presumido e recebe o nome de dano moral in re ipsa. Não existe finalidade de acréscimo patrimonial, o que impede a incidência do imposto de renda.

### Conceitos
- **Dano Moral**: Lesão que atinge a pessoa diretamente ou indiretamente
- **Dano Moral In Re Ipsa**: Dano moral presumido

### Referências legais
- Art. 186 do CC/2002
- ...

### Jurisprudência
- REsp 1.512.001-SP
- Súmula 498 do STJ

