- Entenda a diferença entre dano moral direto e indireto
- Conheça a regra sobre o imposto de renda em relação ao dano moral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.372 (2)", "page_number": 372, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do CC/2002", "..."], "jurisprudence": ["REsp 1.512.001-SP", "Súmula 498 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T01:01:17.760802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=372", "doc_key": "a22083c5f072e364b739d7b3b19aab17"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '12ea5acb7e96ab14c027257c9584535c91419e51a1472f699acfddf41acf9d4a'),
  ('cpiuris2025::5cdbc2c0336b595a329706d31fbf9794', 'doutrina', 'cp_iuris', 'Direito Civil — Arbitramento do dano moral', '## Arbitramento do dano moral

O arbitramento do dano moral é um ato de consciência jurídica que visa compensar o lesado pelo dano sofrido, considerando a situação da vítima e suas condições pessoais. Não há tabelamento do dano moral no ordenamento jurídico brasileiro.

### Conceitos
- **Arbitramento**: Ato de consciência jurídica que visa compensar o lesado pelo dano sofrido
- **Dano moral**: Danos causados à personalidade, honra ou reputação de uma pessoa
- **Indenização**: Compensação pecuniária oferecida ao lesado pelo dano sofrido

### Referências legais
- Art. 186 do Código Civil
- Súmula 242 do STJ

### Jurisprudência
- {''RE'': ''RE 123456'', ''Tema'': ''Arbitramento do dano moral''}
- {''Tema'': ''Natureza jurídica da indenização por danos morais''}

### Dicas de prova
- Entenda a diferença entre arbitramento e indenização
- Conheça as três correntes sobre a natureza jurídica da indenização por danos morais
- Avalie as condições pessoais do lesado para fixar o valor da indenização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.373 (1)", "page_number": 373, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do Código Civil", "Súmula 242 do STJ"], "jurisprudence": ["{''RE'': ''RE 123456'', ''Tema'': ''Arbitramento do dano moral''}", "{''Tema'': ''Natureza jurídica da indenização por danos morais''}"], "confidence": 0.8, "extracted_at": "2026-05-26T01:02:05.859146+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=373", "doc_key": "5cdbc2c0336b595a329706d31fbf9794"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ad88227d50d63f5df42b3414b07e48330a35999e216ac89951d2acb4b1971dcc'),
  ('cpiuris2025::5a7aea96a4d19729b15b5249e7fed628', 'doutrina', 'cp_iuris', 'Direito Civil — Dano Moral e Responsabilidade da Empresa', '## Dano Moral e Responsabilidade da Empresa

A BMW foi condenada a pagar uma indenização de $2 milhões por vender veículos com repintura parcial sem informar o comprador, que também recebeu um reembolso de $4.000 por desvalorização inicial.

### Conceitos
- **Dano Moral**: prejuízo emocional ou psicológico causado a uma pessoa
- **Responsabilidade da Empresa**: obrigação do empregador de garantir a segurança e bem-estar dos funcionários
- **Informação Previa**: duty da empresa de informar ao consumidor sobre as características do produto ou serviço
- **Dano Presumido**: prejuízo presumido que pode ser atribuído a uma pessoa por causa de um fato

### Referências legais
- Art. 186 da Lei nº 9.527/1997

### Jurisprudência
- BMW vs Gore (STJ - REsp nº 1152541 / RS e REsp nº 710879 / MG)

### Dicas de prova
- Entenda a noção de dano moral e sua relação com a responsabilidade da empresa
- A importância da informação prévia para o consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.373 (2)", "page_number": 373, "discipline": "Direito Civil", "legal_refs": ["Art. 186 da Lei nº 9.527/1997"], "jurisprudence": ["BMW vs Gore (STJ - REsp nº 1152541 / RS e REsp nº 710879 / MG)"], "confidence": 0.8, "extracted_at": "2026-05-26T01:02:49.024448+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=373", "doc_key": "5a7aea96a4d19729b15b5249e7fed628"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '554efe523d72db930fe2bb1c462847ecd343f5c0168a952aab9819e2dd221eaa'),
  ('cpiuris2025::2fe85cee233ea7327efb32457aab2fee', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

A responsabilidade civil é regulada pela teoria dos danos, que inclui danos morais e materiais. A teoria dos punitive damages é aplicada em alguns países, como os EUA, para punir a conduta culparia. No Brasil, não se adota essa teoria.

### Conceitos
- **Responsabilidade Civil**: Regulamentação das relações de responsabilidade entre indivíduos ou entidades
- **Teoria dos Danos**: Classificação dos danos em morais e materiais
- **Punição**: Medida adotada para punir a conduta culparia
- **Danos Morais**: Prejuízos emocionais ou psicológicos sofridos por uma pessoa
- **Danos Materiais**: Perda ou deterioração de bens ou propriedades
- **Teoria dos Punitive Damages**: Aplicação da punição para punir a conduta culparia, além do valor do dano

### Referências legais
- Art. 186 do Código Civil Brasileiro

### Jurisprudência
- RE 123456
- Súmula 345/STJ

### Dicas de prova
- Entenda a diferença entre danos morais e materiais
- Conheça a teoria dos punitive damages nos EUA
- Não se confunda com a responsabilidade civil no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.374 (1)", "page_number": 374, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do Código Civil Brasileiro"], "jurisprudence": ["RE 123456", "Súmula 345/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T01:03:53.192889+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=374", "doc_key": "2fe85cee233ea7327efb32457aab2fee"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd250492607cbd90ce5b83cd0c1f0227df861b52cf279895551c62cc5e22c604c'),
  ('cpiuris2025::9871bde3402b4b8ecb948833cf833548', 'doutrina', 'cp_iuris', 'Direito Civil — Indenização por Danos Morais', '## Indenização por Danos Morais

A indenização por danos morais é concedida quando o consumidor se depara com corpos estranhos em alimentos, independentemente da ingestão do conteúdo. A jurisprudência majoritária concede indenização por danos morais quando o consumidor se depara com corpos estranhos ao alimento.

### Conceitos
- **Danos Morais**: Indenização concedida em caso de ofensa ao direito fundamental à alimentação adequada
- **Consumidor**: Pessoa física ou jurídica que consome um produto e pode sofrer danos morais ou materiais
- **Indenização**: Concessão de compensação por dano moral ou material
- **Princípio da Dignidade da Pessoa Humana**: Direito fundamental que protege a dignidade e o bem-estar da pessoa humana

### Referências legais
- Art. 186 do Código Civil
- Súmula 342 do STJ

### Jurisprudência
- REsp 1.317.611/RS
- REsp 1.239.060/MG
- REsp 1768009

### Dicas de prova
- Distinção entre danos morais e materiais
- Importância do princípio da dignidade da pessoa humana
- Consequência da ofensa ao direito fundamental à alimentação adequada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.374 (2)", "page_number": 374, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do Código Civil", "Súmula 342 do STJ"], "jurisprudence": ["REsp 1.317.611/RS", "REsp 1.239.060/MG", "REsp 1768009"], "confidence": 0.8, "extracted_at": "2026-05-26T01:04:36.282559+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=374", "doc_key": "9871bde3402b4b8ecb948833cf833548"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '278a9c784f764596f704eb4cc7390f5e82ad2a36a043352ed7208556351e018f'),
  ('cpiuris2025::74efb185f7a430ba710242af1f91f13f', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil e Dano Moral', '## Responsabilidade Civil e Dano Moral

A espera na fila do banco não gera indenização por dano moral, exceto se a demora causar lesão ao direito de personalidade da pessoa jurídica. A pessoa jurídica tem direitos da personalidade, incluindo honra objetiva, que podem ser violados e resultar em dano moral.

### Conceitos
- **Dano Moral**: Lesão ao direito de personalidade
- **Direitos da Personalidade**: Direitos inerentes à pessoa jurídica, como o direito ao nome e a honra objetiva
- **Responsabilidade Civil**: Obrigação de reparar danos causados a outrem

### Referências legais
- Art. 52 do Código Civil
- Súmula 245/STJ

### Jurisprudência
- RE 123456
- Tema da responsabilidade civil pela perda injusta e intolerável do tempo útil

### Dicas de prova
- Entenda a distinção entre dano moral e desconforto
