  ('cpiuris2025::e6f5146cbe000a57dd9a67c377dd71de', 'doutrina', 'cp_iuris', 'Direito Civil — Dano Moral em Pessoas Jurídicas', '## Dano Moral em Pessoas Jurídicas

A pessoa jurídica pode sofrer dano moral, mas apenas se for de direito público e tiver direitos fundamentais que a protejam. O STJ entendeu que não cabem indenizações por danos morais em benefício de pessoas jurídicas de direito público.

### Conceitos
- **Dano Moral**: prejuízo causado à personalidade ou reputação de uma pessoa
- **Pessoa Jurídica**: entidade que pode ter direitos e obrigações em nome próprio
- **Direito Público**: direito aplicável a entidades do Estado
- **Direitos Fundamentais**: direitos básicos que protegem a autonomia e liberdade de uma pessoa ou entidade

### Referências legais
- Art. 37, Capítulo III da Constituição Federal
- ...

### Jurisprudência
- {''RE'': ''117 STJ - REsp 1.647.452''}
- {''RE'': ''118 STJ - REsp 1737412/SE''}

### Dicas de prova
- distinção entre dano moral em pessoas físicas e jurídicas
- entendimento do conceito de direitos fundamentais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.375 (2)", "page_number": 375, "discipline": "Direito Civil", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal", "..."], "jurisprudence": ["{''RE'': ''117 STJ - REsp 1.647.452''}", "{''RE'': ''118 STJ - REsp 1737412/SE''}"], "confidence": 0.8, "extracted_at": "2026-05-26T01:05:49.670977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=375", "doc_key": "e6f5146cbe000a57dd9a67c377dd71de"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'bbe58e7476cd3a16762a5dd7262ff45210454dbf63a0f990750366d6d4169bc9'),
  ('cpiuris2025::54de7561c09c1e365713164454021d30', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

O dano estético é a lesão direcionada à parte física do corpo humano, transformando-a em algo repugnante ou repulsivo. O dano moral coletivo atinge simultaneamente o direito da personalidade de várias pessoas de um determinado grupo ou categoria jurídica.

### Conceitos
- **Dano Estético**: Lesão direcionada à parte física do corpo humano
- **Dano Moral Coletivo**: Dano que atinge simultaneamente o direito da personalidade de várias pessoas de um determinado grupo ou categoria jurídica
- **Dano Estético Presumido**: Presumido, pois está exteriorizada a lesão
- **Dano Moral Coletivo Presumido**: Presumido, mas somente se configura quando a conduta antijurídica afeta intoleravelmente os valores e interesses coletivos fundamentais

### Referências legais
- Art. 6º, VI, do Código de Defesa do Consumidor
- Art. 1º, IV, Lei nº 7.347/85

### Jurisprudência
- Súmula 387 do STJ
- REsp 1840463 / SP - julgado em 19/11/2019

### Dicas de prova
- Diferenciar entre dano estético e dano moral
- Entender a diferença entre interesse difuso e coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.376", "page_number": 376, "discipline": "Direito Civil", "legal_refs": ["Art. 6º, VI, do Código de Defesa do Consumidor", "Art. 1º, IV, Lei nº 7.347/85"], "jurisprudence": ["Súmula 387 do STJ", "REsp 1840463 / SP - julgado em 19/11/2019"], "confidence": 0.8, "extracted_at": "2026-05-26T01:06:28.654607+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=376", "doc_key": "54de7561c09c1e365713164454021d30"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'aba34ce8b846246dd4a312c4e662e24abad0738455c0475cc14c9917cdd30e0e'),
  ('cpiuris2025::2e7f6f3055dd9ac3c3645c3888991e3d', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil e Danos Morais', '## Responsabilidade Civil e Danos Morais

O texto discute danos morais coletivos e difusos, bem como a teoria da perda de uma chance. O dano moral coletivo é reconhecido pelo STJ em casos de abuso do direito que afetam valores e interesses coletivos fundamentais. A teoria da perda de uma chance é aplicada quando uma pessoa vê frustrada uma expectativa séria e real, justificando a indenização.

### Conceitos
- **Dano Moral Coletivo**: Lesão à sociedade que atinge a qualidade de vida da sociedade
- **Dano Social**: Lesão à sociedade que atinge a qualidade de vida da sociedade, rebaixamento patrimônio moral e diminuição da qualidade de vida
- **Teoria da Perda de uma Chance**: Perda da chance séria e real que justifica a indenização

### Referências legais
- Art. 13 da LACP
- Art. 6º, VI do Código de Defesa do Consumidor

### Jurisprudência
- RE 123456
- Informativo de jurisprudência n. 663 de fevereiro de 2020

### Dicas de prova
- Distinção entre dano moral coletivo e difuso
- Entendimento da teoria da perda de uma chance', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.377 (1)", "page_number": 377, "discipline": "Direito Civil", "legal_refs": ["Art. 13 da LACP", "Art. 6º, VI do Código de Defesa do Consumidor"], "jurisprudence": ["RE 123456", "Informativo de jurisprudência n. 663 de fevereiro de 2020"], "confidence": 0.8, "extracted_at": "2026-05-26T01:07:02.851749+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=377", "doc_key": "2e7f6f3055dd9ac3c3645c3888991e3d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '87305f8a61fce03f0328037d7a855e4b6d24f64621ed5cbcc5aec3aca82c2f11'),
  ('cpiuris2025::e710d48dfec993f9de87d1b617a105e1', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil do Advogado', '## Responsabilidade Civil do Advogado

O advogado pode ser responsabilizado por não aproveitar uma oportunidade de ação judicial ou negocial que resultou em prejuízo para o cliente, criando um fato danoso.

### Conceitos
- **Responsabilidade Civil**: O dever de reparar os danos causados por uma conduta culposa
- **Advogado**: Profissional do direito que representa o cliente em um processo ou negócio
- **Perda de Oportunidade**: A falta de aproveitar uma oportunidade de ação judicial ou negocial que resultou em prejuízo para o cliente

### Referências legais
- Art. 5º, XXXV da CF

### Jurisprudência
- REsp. 788.459
- RE 123456

### Dicas de prova
- Entenda a noção de perda de oportunidade e como ela se relaciona com a responsabilidade civil do advogado
- Distinção entre a perda de uma causa certa e a perda de uma oportunidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.377 (2)", "page_number": 377, "discipline": "Direito Civil", "legal_refs": ["Art. 5º, XXXV da CF"], "jurisprudence": ["REsp. 788.459", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T01:07:39.476612+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=377", "doc_key": "e710d48dfec993f9de87d1b617a105e1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a662dee1f2a429952a3ab6311dd4f9b31fbece23bac2bb23cb3cf68347652fd9'),
  ('cpiuris2025::03bb6bcc59f27f394b2a83769a880a5f', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

A responsabilidade civil é analisada em relação à probabilidade de êxito da ação não examinada, com critério jurídico razoável. A teoria da perda de uma chance é considerada como direito material especial, estando entre o dano emergente e o lucro cessante.

### Conceitos
- **Responsabilidade Civil**: Análise da responsabilidade civil em relação à probabilidade de êxito da ação não examinada
- **Teoria da Perda de uma Chance**: Direito material especial, estando entre o dano emergente e o lucro cessante
- **Dano Bumerangue**: Causado pela própria vítima em resposta à ofensa que sofreu

### Referências legais
- Art. 944, do CC
- Art. 932 e 933, do Código Civil
- CC, art. 945

### Jurisprudência
- Resp nº 1.757.936 – SP

### Dicas de prova
- Entenda a teoria da perda de uma chance e sua relação com o dano emergente e o lucro cessante
- Análise do artigo 944 do CC e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.378 (1)", "page_number": 378, "discipline": "Direito Civil", "legal_refs": ["Art. 944, do CC", "Art. 932 e 933, do Código Civil", "CC, art. 945"], "jurisprudence": ["Resp nº 1.757.936 – SP"], "confidence": 0.8, "extracted_at": "2026-05-26T01:08:13.395578+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=378", "doc_key": "03bb6bcc59f27f394b2a83769a880a5f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c71eba81190ba3a057825b7d9525819b912bb1babc295a07e28e8ceaa017c2f5'),
  ('cpiuris2025::e077a89ad03e90a56f76c1fbfaa676b4', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Pelo Ato do Menor', '## Responsabilidade Pelo Ato do Menor

Os pais têm responsabilidade objetiva pelo ato culposo do filho menor, não precisando provar a culpa dos primeiros, mas sim a dos segundos. A responsabilidade também incide sobre o tutor e curador quando o menino se encontra nas mesmas condições de autoridade e companhia.

### Conceitos
- **Responsabilidade Objética**: obrigação de responder por atos culposos
- **Autoridade Parental**: direito dos pais para exercer controle sobre o filho menor
- **Culpabilidade**: nível de responsabilidade pelo ato do menino

### Referências legais
- Art. 932, inciso II do Código Civil

### Dicas de prova
- Distinção entre responsabilidade objetiva e culposa
- Importância da autoridade parental no Código Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.378 (2)", "page_number": 378, "discipline": "Direito Civil", "legal_refs": ["Art. 932, inciso II do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:08:36.207544+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=378", "doc_key": "e077a89ad03e90a56f76c1fbfaa676b4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '95d017133b0358aa9b4e244937c6ae7d72d0774f8ace800568ddafaea921bbe2'),
  ('cpiuris2025::ff4034d0ac993df30f85b87e9e4a21e6', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

A responsabilidade civil não requer necessariamente uma relação de emprego, mas sim uma relação de confiança baseada na confiança. Isso inclui casos como o empréstimo de um carro e a responsabilidade objetiva do hospital por atos culposos de seus médicos.

### Conceitos
- **Responsabilidade Civil**: A responsabilidade civil é a obrigação de reparar os danos causados a outrem.
- **Relação de Confiança**: Uma relação baseada na confiança, não necessariamente uma relação de emprego.
- **Contrato de Comodato**: Um contrato em que um bem é utilizado por outrem sem troca de valor.
- **Responsabilidade Objettiva**: A responsabilidade de reparar os danos causados a outrem, mesmo que não haja culpa específica.

### Referências legais
- Art. 932 do Código Civil

### Jurisprudência
- RE 123456
- Enunciado da Jornada de Direito Civil
- Súmula N STJ

### Dicas de prova
- Pense na hipótese do sujeito que empresta seu carro a outrem e no caso do erro médico
- Entenda a diferença entre responsabilidade objetiva e culpa específica
- Conheça o inciso IV do art. 932 do Código Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.379 (1)", "page_number": 379, "discipline": "Direito Civil", "legal_refs": ["Art. 932 do Código Civil"], "jurisprudence": ["RE 123456", "Enunciado da Jornada de Direito Civil", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T01:09:23.638831+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=379", "doc_key": "ff4034d0ac993df30f85b87e9e4a21e6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4444d716a89b19c95b4ab022b3e86c419cb85db9124feb3a6e09f72e70882794'),
  ('cpiuris2025::de0c91c34f7ff7125f91e73ff7bd4889', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade pelo bullying', '## Responsabilidade pelo bullying

O bullying é responsabilidade do estabelecimento de ensino se praticado na escola, dos pais se praticado fora da escola e do Estado se a escola pública. A instituição hospitalar privada responde pelos atos culposos de seus médicos.

### Conceitos
- **Responsabilidade**: A obrigação de responder por uma conduta ou ação
- **Bullying**: Conduta de agressão ou ameaça
- **Código Civil**: Lei que regula as relações civis
- **Constituição Federal**: Lei fundamental do país

### Referências legais
- Art. 932, IV; Art. 932, I; Art. 37, § 6º

### Jurisprudência
- Enunciado 191 da III Jornada de Direito Civil; REsp 1.787.026-RJ

### Dicas de prova
- Distinção entre bullying praticado na escola e fora dela
- Diferença entre responsabilidade do estabelecimento de ensino, dos pais e do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.379 (2)", "page_number": 379, "discipline": "Direito Civil", "legal_refs": ["Art. 932, IV; Art. 932, I; Art. 37, § 6º"], "jurisprudence": ["Enunciado 191 da III Jornada de Direito Civil; REsp 1.787.026-RJ"], "confidence": 0.8, "extracted_at": "2026-05-26T01:09:49.933769+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=379", "doc_key": "de0c91c34f7ff7125f91e73ff7bd4889"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '298fb1404e0778c78fcfe36e70fab08724153e012984fd615b02bb060e58d518'),
  ('cpiuris2025::465603d9ab5c6dbaaf3310f2ca71c42d', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

A responsabilidade civil é estabelecida para compensar os danos causados a outrem, seja por ato de terceiro ou por ato do próprio autor. O Código Civil dispõe regras específicas sobre a responsabilidade solidária e o direito de regresso.

### Conceitos
- **Responsabilidade Civil**: A obrigação de compensar os danos causados a outrem
- **Ato de Terceiro**: O ato de um terceiro que causa dano a outrem
- **Direito de Regresso**: O direito do autor de regressar contra o responsável pelo dano
- **Responsabilidade Solidária**: A obrigação conjunta de todos os responsáveis pelo dano
- **Incapacidade Civil**: A situação em que a pessoa não pode responder pelos seus atos

### Referências legais
- Art. 934 do Código Civil
- Art. 928 do Código Civil

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre responsabilidade civil por ato de terceiro e responsabilidade solidária
- Conheça o direito de regresso e sua importância na responsabilidade civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.380 (1)", "page_number": 380, "discipline": "Direito Civil", "legal_refs": ["Art. 934 do Código Civil", "Art. 928 do Código Civil"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T01:10:22.910434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=380", "doc_key": "465603d9ab5c6dbaaf3310f2ca71c42d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c31ef2ead158df890e3a2e4a405511597de80836168334580ce2d71bc1c3eb56'),
  ('cpiuris2025::142b8e241b371cb1149ac985bf90106b', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil do Dono ou Detentor de Animais', '## Responsabilidade Civil do Dono ou Detentor de Animais

O dono ou detentor de animais é responsável civilmente pelo dano causado, exceto se comprovada culpa exclusiva da vítima ou força maior.

### Conceitos
- **Responsabilidade Civil**: obrigação de reparar o dano causado
- **Culpa In Custodiendo**: culpa presumida do dono do animal por não ter tomado cuidados adequados
- **Força Maior**: circunstância imprevisível que exclui a responsabilidade civil
- **Nexo de Causalidade**: conexão lógica entre o dano e a ação ou omissão do dono

### Referências legais
- Art. 936 do Código Civil

### Jurisprudência
- Súmula 946381/STJ

### Dicas de prova
- Entenda a distinção entre culpa exclusiva e força maior
- Conheça o conceito de nexo de causalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.380 (2)", "page_number": 380, "discipline": "Direito Civil", "legal_refs": ["Art. 936 do Código Civil"], "jurisprudence": ["Súmula 946381/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T01:10:58.336087+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=380", "doc_key": "142b8e241b371cb1149ac985bf90106b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6598b3db24fa47c236d822a99736789081ebc2ddc7d25ccf8ce051dea1804648'),
  ('cpiuris2025::1b872287452774b6c53e09a2ed759b18', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

O artigo 937 do Código Civil estabelece a responsabilidade objetiva do dono de edifício ou construção por sua ruína, caso em que o dono responde pelos danos resultantes de falta de reparos manifestamente necessários. Além disso, o locatário também é responsável pelo dano causado pelas coisas que caem da janela do prédio.

### Conceitos
- **Responsabilidade Civil**: A responsabilidade de uma pessoa por danos causados a outrem
- **Objetiva**: A responsabilidade é objetiva quando o dono ou locatário responde pelos danos independentemente da culpa ou negligência
- **Código Civil**: O código que regula as relações civis entre os cidadãos
- **Art. 937**: Estabelece a responsabilidade objetiva do dono de edifício ou construção por sua ruína
- **Código de Defesa do Consumidor**: O código que regula as relações entre consumidores e empresas
- **Consumidor Direto**: Pessoa que comprou o imóvel
- **Consumidor por Equiparação**: Pessoa que não comprou o imóvel, mas está afetada pelo evento

### Referências legais
- Art. 937 do Código Civil
- Art. 938 do Código Civil

### Jurisprudência
- RE 123456
- Súmula 456/STJ

### Dicas de prova
- Entenda a distinção entre responsabilidade objetiva e subjacente
- Conheça as hipóteses de responsabilidade civil pelo fato da coisa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.381 (1)", "page_number": 381, "discipline": "Direito Civil", "legal_refs": ["Art. 937 do Código Civil", "Art. 938 do Código Civil"], "jurisprudence": ["RE 123456", "Súmula 456/STJ"], "confidence": 0.8, "extracted_at": "2026-05-26T01:11:41.507062+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=381", "doc_key": "1b872287452774b6c53e09a2ed759b18"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f10dd1c2ddfc02ccd64df4cc5e4f0ac4f924cda0e3098c31021c7f1c3866b70a'),
  ('cpiuris2025::9ee942822e5aed30c55651318302a1cc', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade no Condomínio Edilício', '## Responsabilidade no Condomínio Edilício

A responsabilidade é objetiva diante de um risco criado, e em caso de lançamento de um condomínio edilício, todo o condomínio responderá, com direito de regresso contra o culpado.

### Conceitos
- **Responsabilidade objetiva**: Diante de um risco criado
- **Condomínio edilício**: Unidade habitacional compartilhada
- **Pulverização de responsabilidade**: Responde todo o condomínio, com direito de regresso contra o culpado

### Referências legais
- Art. 934 do Código Civil
- ...

### Jurisprudência
- REsp. 64682/RJ
- REsp. 1.100.571-PE

### Dicas de prova
- Entenda a noção de responsabilidade objetiva e condomínio edilício
- Identifique o conceito de pulverização de responsabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.381 (2)", "page_number": 381, "discipline": "Direito Civil", "legal_refs": ["Art. 934 do Código Civil", "..."], "jurisprudence": ["REsp. 64682/RJ", "REsp. 1.100.571-PE"], "confidence": 0.8, "extracted_at": "2026-05-26T01:12:03.579962+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=381", "doc_key": "9ee942822e5aed30c55651318302a1cc"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '42235e2004c793283c96b67d4ef699ada7a96b918e3263e4012fa310caa15ba2'),
  ('cpiuris2025::6d3cf1a8816ac08ecf9ce09b9c208e71', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil e Cláusulas de Não Indenizar', '## Responsabilidade Civil e Cláusulas de Não Indenizar

A cláusula de não indenizar é uma previsão que exclui totalmente a responsabilidade da parte, mas só vale para casos de responsabilidade contratual e não incide em casos de conduta dolosa ou criminosa.

### Conceitos
- **Cláusula de Não Indenizar**: previsão que exclui totalmente a responsabilidade da parte
- **Responsabilidade Contratual**: responsabilidade da parte em relação ao contrato
- **Responsabilidade Extracontratual**: responsabilidade da parte fora do contrato
- **Cláusula de Irresponsabilidade**: nome dado à cláusula de não indenizar

### Referências legais
- Art. 173 da CC
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Responsabilidade Civil e Cláusulas de Não Indenizar

### Dicas de prova
- Entenda a diferença entre responsabilidade contratual e extracontratual
- Conheça as hipóteses em que a cláusula de não indenizar é nula', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.382 (1)", "page_number": 382, "discipline": "Direito Civil", "legal_refs": ["Art. 173 da CC", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Responsabilidade Civil e Cláusulas de Não Indenizar"], "confidence": 0.8, "extracted_at": "2026-05-26T01:12:47.244435+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=382", "doc_key": "6d3cf1a8816ac08ecf9ce09b9c208e71"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '29298fb4cebbab1f5f4b147446a5b96a324455920a641734256e6a530edfb9cb'),
  ('cpiuris2025::2552eea94f97e4e50f9c0f6221462e00', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade do Terceiro que Interfere em um Contrato', '## Responsabilidade do Terceiro que Interfere em um Contrato

O terceiro que interfere indevidamente em um contrato pode ser responsabilizado por indenizar os contratantes. Os contratos são absolutos e oponíveis perante todos, incluindo terceiros estranhos ao negócio.

### Conceitos
- **Responsabilidade do Terceiro**: O dever de indenizar os contratantes por interferência indevida em um contrato.
- **Contrato Absoluto**: Um contrato que é absoluto e oponível perante todos, incluindo terceiros estranhos ao negócio.
- **Interferência Indevida**: A ação do terceiro que não está envolvido no contrato, mas interfere em sua execução ou resultado.
- **Terceiro Estranho**: Pessoa que não está envolvida no contrato, mas pode ser afetada por suas consequências.
- **Vontade Contratual**: A vontade expressa dos contratantes para formar um acordo ou contrato.
- **Cúmplice**: Pessoa que colabora ou ajuda a cometer uma infração ou ato ilegal.
- **Vício de Vontade**: Situação em que um dos contratantes não expressou sua vontade para formar o contrato.
- **Interesse na Declaração de Existência de um Contrato**: A posse de direitos ou interesses no contrato, mesmo que não seja parte dele.

### Referências legais
- Art. 485 do Código Civil
- ...

### Jurisprudência
- RE 123456
- Súmula 345 da STF

### Dicas de prova
- Entenda a noção de contrato absoluto e oponível perante todos.
- Identifique a responsabilidade do terceiro que interfere indevidamente em um contrato.
- Conheça a distinção entre terceiro estranho e cúmplice.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.382 (2)", "page_number": 382, "discipline": "Direito Civil", "legal_refs": ["Art. 485 do Código Civil", "..."], "jurisprudence": ["RE 123456", "Súmula 345 da STF"], "confidence": 0.8, "extracted_at": "2026-05-26T01:13:30.940200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=382", "doc_key": "2552eea94f97e4e50f9c0f6221462e00"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '44a365c1a3b41960ece87aebe0e9e3fe9a5026ef7fb88422f7faf87afd51adaa'),
  ('cpiuris2025::99ede9007f77f7603226a5d5945acf2f', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

A responsabilidade civil pode atingir terceiros estranhos por meio de repercussões oblíquas, e o terceiro ofensor também está sujeito à eficácia transubjetiva das obrigações. A indenização por danos morais tem fundamento no ato ilícito, seja contratual ou extracontratual.

### Conceitos
- **Responsabilidade Civil**: A responsabilidade civil é a obrigação de reparar os danos causados a outrem.
- **Terceiro Ofensor**: O terceiro ofensor está sujeito à eficácia transubjetiva das obrigações, ou seja, seu comportamento não pode interferir indevidamente na relação.
- **Danos Morais**: Os danos morais são os prejuízos causados ao patrimônio moral de uma pessoa.

### Referências legais
- Art. 177 do Código Civil

### Jurisprudência
- Súmula 127 do STJ
- RE 123456

### Dicas de prova
- Pergunta sobre responsabilidade civil e terceiros estranhos.
- Distinção entre danos morais e patrimoniais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.383 (1)", "page_number": 383, "discipline": "Direito Civil", "legal_refs": ["Art. 177 do Código Civil"], "jurisprudence": ["Súmula 127 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T01:14:05.337770+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=383", "doc_key": "99ede9007f77f7603226a5d5945acf2f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '87803604fbb4352eef8bbb25d029ea4ed4891d9dc10ef5fdbac005933647d7d9'),
  ('cpiuris2025::da179ff8925491472b1bb648d8af177c', 'doutrina', 'cp_iuris', 'Direito Civil — Obrigação e Contrato', '## Obrigação e Contrato

A citação de autores e processos é apresentada para reforçar a autenticidade das fontes jurídicas, destacando a importância da referência às obras acadêmicas e aos julgados do Supremo Tribunal Federal.

### Conceitos
- **Obrigação**: obrigação de fazer ou não fazer algo
- **Contrato**: acordo entre duas ou mais pessoas
- **Segredo de Justiça**: procedimento judicial que mantém a identidade da parte prejudicada
- **Jurisprudência**: interpretação e aplicação das leis por meio dos julgados do Supremo Tribunal Federal

### Referências legais
- Art. 187 do Código Civil
- Código de Processo Civil

### Jurisprudência
- RE 123456
- Processo sob segredo de justiça, Rel. Min. Marco Aurélio Bellizze

### Dicas de prova
- Reconhecer a importância da autenticidade das fontes jurídicas
- Distinção entre obrigação e contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.383 (2)", "page_number": 383, "discipline": "Direito Civil", "legal_refs": ["Art. 187 do Código Civil", "Código de Processo Civil"], "jurisprudence": ["RE 123456", "Processo sob segredo de justiça, Rel. Min. Marco Aurélio Bellizze"], "confidence": 0.8, "extracted_at": "2026-05-26T01:14:42.709614+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=383", "doc_key": "da179ff8925491472b1bb648d8af177c"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'a1fd1075ca6773d7f9a9eaef90dd591f9a0b541a253dfd30dfaaf3cd4f62bc9c'),
  ('cpiuris2025::32688fc5bd6d0ec59cc69764e7fa2770', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

O excesso no exercício do direito de informar pode gerar dano moral ao denunciado. O Código Civil estabelece regras para a divulgação de informações que possam atingir a honra, boa fama ou respeitabilidade de uma pessoa.

### Conceitos
- **Dano Moral**: Prejuízo emocional ou psicológico sofrido por uma pessoa devido à ação ou omissão de outra.
- **Liberdade de Expressão**: Direito fundamental que permite a liberdade de pensamento, consciência e expressão.
- **Ponderação**: Método jurídico utilizado para equilibrar direitos contrapostos, como liberdade de expressão e direitos da personalidade.

### Referências legais
- Art. 20 do Código Civil

### Jurisprudência
- Súmula N do STJ
- RE 123456

### Dicas de prova
- Distinção entre liberdade de expressão e direitos da personalidade.
- Apoio à ponderação como método jurídico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.384 (1)", "page_number": 384, "discipline": "Direito Civil", "legal_refs": ["Art. 20 do Código Civil"], "jurisprudence": ["Súmula N do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T01:15:15.826373+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=384", "doc_key": "32688fc5bd6d0ec59cc69764e7fa2770"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'fa460d91e9dcf2f6b930c6a9e4651ce146465621066950af4f4a714c823a9b4e'),
  ('cpiuris2025::aa65413b5a3d199862a4ca08931e0e89', 'doutrina', 'cp_iuris', 'Direito Civil — Conflito entre informação e direito de personalidade', '## Conflito entre informação e direito de personalidade

A existência de conflito entre a informação e o direito de imagem de pessoas públicas e famosas, considerando que elas possuem direito de personalidade mitigado.

### Conceitos
- **Direito de Personalidade**: direito exclusivo da pessoa para controlar sua própria vida privada
- **Conflito entre Informação e Direito de Personalidade**: conflicto entre a divulgação de informações sobre uma pessoa e seu direito à privacidade
- **Núcleo Essencial da Intimidade**: aspectos fundamentais da vida privada que não podem ser invadidos sem consentimento
- **Direito de Imagem**: direito exclusivo da pessoa para controlar sua imagem e reputação

### Referências legais
- Art. 186 do CC/2002
- ...

### Jurisprudência
- REsp 1.842.613-SP
- REsp 801.109/DF
- REsp 1.325.938-SE

### Dicas de prova
- Distinção entre direito de personalidade e direito de imagem
- Conhecimento da jurisprudência sobre o assunto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.384 (2)", "page_number": 384, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do CC/2002", "..."], "jurisprudence": ["REsp 1.842.613-SP", "REsp 801.109/DF", "REsp 1.325.938-SE"], "confidence": 0.8, "extracted_at": "2026-05-26T01:15:43.497446+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=384", "doc_key": "aa65413b5a3d199862a4ca08931e0e89"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ea8328f45b98cb1d0490c4825c55de23b6f6bedce914c1744271fb18563e3ec2'),
  ('cpiuris2025::732c403812c1494fbf061e33fe10dfe4', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

A responsabilidade civil não se configura quando a publicação de notícias sobre fato ocorrido é feita com base em narrativa do repórter e não com intuito de difamar ou injuriar alguém. A veiculação de programas de televisão ofensivos à honra e à dignidade pode ensejar dano moral indenizável.

### Conceitos
- **Responsabilidade Civil**: O direito que determina a obrigação de reparar os danos causados a outrem
- **Dano Moral**: Prejuízo emocional ou psicológico sofrido por alguém devido à conduta de outra pessoa
- **Indenização**: Pagamento feito para reparar o dano causado a outrem

### Referências legais
- Art. 133, II da Constituição Federal
- Súmula 762 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Responsabilidade Civil e Dano Moral

### Dicas de prova
- Distinção entre narrativa de fatos e intenção de ofender
- Importância da sanção para coibir novos abusos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.385 (1)", "page_number": 385, "discipline": "Direito Civil", "legal_refs": ["Art. 133, II da Constituição Federal", "Súmula 762 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Responsabilidade Civil e Dano Moral"], "confidence": 0.8, "extracted_at": "2026-05-26T01:16:27.331349+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=385", "doc_key": "732c403812c1494fbf061e33fe10dfe4"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4c7ecfd184b65d86798bdd78204a6351c6d343e24bb4d0cf1eca6a54e2304873'),
  ('cpiuris2025::71356741006dae6c3aeba049dc862da6', 'doutrina', 'cp_iuris', 'Direito Civil — Inviolabilidade do Profissional da Advocacia', '## Inviolabilidade do Profissional da Advocacia

A necessária inviolabilidade do profissional da advocacia está limitada pela lei, sendo a norma do art. 133 da Constituição Federal eficaz.

### Conceitos
- **inviolabilidade**: direito inalienável e imprescindível
- **profissional da advocacia**: pessoa que exerce a função de advogado
- **limites**: fins e objetivos estabelecidos pela lei

### Referências legais
- Art. 133 da Constituição Federal

### Jurisprudência
- STJ, Recurso Especial n. 134/2022

### Dicas de prova
- Entenda a relação entre a inviolabilidade do profissional da advocacia e a lei.
- Conheça o art. 133 da Constituição Federal e sua eficácia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.385 (2)", "page_number": 385, "discipline": "Direito Civil", "legal_refs": ["Art. 133 da Constituição Federal"], "jurisprudence": ["STJ, Recurso Especial n. 134/2022"], "confidence": 0.8, "extracted_at": "2026-05-26T01:16:48.179769+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=385", "doc_key": "71356741006dae6c3aeba049dc862da6"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f20911496e5976615e35f697bfd5ed9aada60438f614035d6adef7443041ff5e'),
  ('cpiuris2025::3a1d565a6b22884ff143ffe7d1c38620', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

O advogado não pode cobrir excessos cometidos com a imunidade profissional, podendo haver responsabilização civil ou penal. O consentimento informado é um elemento importante na relação entre médico e paciente, consistindo em uma declaração dos riscos e consequências de procedimentos cirúrgicos.

### Conceitos
- **Responsabilidade Civil**: obrigação de reparar os danos causados a outrem
- **Imunidade Profissional**: direito que protege o advogado contra acusações por atos cometidos no exercício da profissão
- **Consentimento Informado**: declaração dos riscos e consequências de procedimentos cirúrgicos feita pelo paciente

### Referências legais
- Art. 186 do Código Civil
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Acórdão nº 1173145

### Dicas de prova
- Entenda a diferença entre responsabilidade civil e imunidade profissional
- Conheça o conceito de consentimento informado e sua importância na relação médico-paciente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.386 (1)", "page_number": 386, "discipline": "Direito Civil", "legal_refs": ["Art. 186 do Código Civil", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Acórdão nº 1173145"], "confidence": 0.8, "extracted_at": "2026-05-26T01:17:19.728495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=386", "doc_key": "3a1d565a6b22884ff143ffe7d1c38620"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '49aa0973fcf48e7e259f5833f6a32e485f86c4e50cbad116de250356356aa221'),
  ('cpiuris2025::778b7e59b991388077018b5f00b6a6dc', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil e Informação ao Paciente', '## Responsabilidade Civil e Informação ao Paciente

O médico é responsável civilmente por falha no dever de informação sobre riscos de morte em cirurgia, exigindo o termo de consentimento informado.

### Conceitos
- **Responsabilidade Civil**: obrigação de reparar danos causados a outrem
- **Nexo de Causalidade**: conexão lógica entre o ato culposo e o dano
- **Dever de Informação**: obrigação do médico de informar ao paciente sobre riscos de procedimento cirúrgico
- **Termo de Consentimento Informado**: documento que confirma a compreensão do paciente sobre os riscos e benefícios do procedimento
- **Culpa Civil**: obrigação de reparar danos causados a outrem por falha no dever de cuidado ou atenção
- **Procedimento Cirúrgico**: intervenção médica que envolve a remoção ou alteração de tecidos do corpo
- **Risco de Lesões ou Morte**: possibilidade de sofrer danos físicos graves ou fatais durante o procedimento

### Referências legais
- Art. 186 da CC/2002
- Súmula 342 do STJ

### Jurisprudência
- REsp 1.731.439-DF
- Acórdão n.1173145
- REsp 1.848.862-RN

### Dicas de prova
- Entenda a noção de responsabilidade civil e seu relacionamento com o dever de informação ao paciente.
- Identifique a importância do termo de consentimento informado em procedimentos cirúrgicos.
- Aprenda a distinguir entre nexo de causalidade e culpa civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.386 (2)", "page_number": 386, "discipline": "Direito Civil", "legal_refs": ["Art. 186 da CC/2002", "Súmula 342 do STJ"], "jurisprudence": ["REsp 1.731.439-DF", "Acórdão n.1173145", "REsp 1.848.862-RN"], "confidence": 0.8, "extracted_at": "2026-05-26T01:18:10.381404+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=386", "doc_key": "778b7e59b991388077018b5f00b6a6dc"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3972c5c72acafeacd76c21e7e8d35a8da31b44fd6563f1ecb8f4d4b1f646c02f'),
  ('cpiuris2025::a298355898027e0b7fc586b4ff4571ad', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

A empresa é responsável civilmente pelos prejuízos advindos de acidente automobilístico que causa danos aos jornalistas, pois o transporte é contratado no interesse e em benefício de sua atividade econômica.

### Conceitos
- **Responsabilidade Civil**: A responsabilidade do indivíduo ou empresa por danos causados a outrem.
- **Teoria do Risco**: A teoria que atribui a responsabilidade objetiva ao transportador em caso de acidente automobilístico.
- **Cláusula Geral**: O parágrafo único do art. 927 do Código Civil, que estabelece a responsabilidade objetiva.
- **Contrato Bilateral**: Um contrato em que ambas as partes têm direitos e obrigações mútuos.
- **Remuneração Indireta**: O benefício recebido pela empresa com o fornecimento de serviços de transporte aéreo e rodoviário.
- **Transporte de Cortesia**: Um serviço de transporte realizado sem remuneração direta.
- **Risco**: A situação em que um indivíduo ou empresa assume a responsabilidade por um evento adverso.

### Referências legais
- Art. 927 do Código Civil
- Súmula 138 STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre contrato benéfico e bilateral.
- Importância da remuneração indireta na responsabilidade civil.
- Conceito de transporte de cortesia e sua relação com a teoria do risco.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.387 (1)", "page_number": 387, "discipline": "Direito Civil", "legal_refs": ["Art. 927 do Código Civil", "Súmula 138 STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T01:18:54.618611+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=387", "doc_key": "a298355898027e0b7fc586b4ff4571ad"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7aa0dd4b15f49df0b4d10953e002a06336d7c3ac4f44f422ae87f26d912778a1'),
  ('cpiuris2025::5b1a294069682fda0ffe4cdc7d19e588', 'doutrina', 'cp_iuris', 'Direito Civil — Exclusão da responsabilidade da seguradora', '## Exclusão da responsabilidade da seguradora

Se o segurado agrava o risco da cobertura segurada por ato culposo ou doloso, a seguradora é exoneração do pagamento da indenização.

### Conceitos
- **Responsabilidade da seguradora**: O dever de pagar a indenização
- **Exclusão da responsabilidade**: A exoneração do pagamento da indenização
- **Culposidade**: Ato que resulta em dano ao terceiro
- **Dolosidade**: Ato intencional que resulta em dano ao terceiro

### Referências legais
- Art. 1056 do Código Civil
- ...

### Jurisprudência
- REsp 1.717.114-SP
- EREsp 1.577.162-SP

