- Distinção entre ato culposo e doloso
- Importância da cautela razoável para a seguradora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.387 (2)", "page_number": 387, "discipline": "Direito Civil", "legal_refs": ["Art. 1056 do Código Civil", "..."], "jurisprudence": ["REsp 1.717.114-SP", "EREsp 1.577.162-SP"], "confidence": 0.8, "extracted_at": "2026-05-26T01:19:19.608798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=387", "doc_key": "5b1a294069682fda0ffe4cdc7d19e588"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'e9e57da0ef94594cf6f43bf32698dfa26d477d6be8a0442b407119c35dda72e9'),
  ('cpiuris2025::0ec7355136c1333f48bba027ca65cf04', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

O texto discute a responsabilidade civil no contrato de locação e arrendamento mercantil, destacando a atuação indevida do locador que proíbe o funcionamento de um restaurante localizado em seu imóvel durante a pandemia. O STJ decidiu que o locador deve indenizar o locatário pelos danos sofridos.

### Conceitos
- **Responsabilidade Civil**: O direito de uma pessoa para exigir indenização por danos causados a outra
- **Locação**: Contrato pelo qual um bem é cedido por um tempo determinado em troca de prestações periódicas
- **Arrendamento Mercantil**: Contrato pelo qual o arrendatário adquire o direito de usar um bem por um período determinado
- **Dano Moral**: Prejuízo não material, como dor, angústia ou prejuízo à dignidade

### Referências legais
- Art. 927 c/c 402 do Código Civil

### Jurisprudência
- Súmula 140 do STJ

### Dicas de prova
- Entenda a responsabilidade civil no contrato de locação e arrendamento mercantil
