  ('cpiuris2025::2c342cc17e7f0e113f88b9afffa45fd6', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade do Transportador Aéreo', '## Responsabilidade do Transportador Aéreo

O transportador é responsável pelos danos causados às pessoas transportadas e suas bagagens, salvo motivo de força maior, de acordo com o art. 734 do CC/2002.

### Conceitos
- **Responsabilidade objetiva**: A responsabilidade do transportador é imposta pelo risco da atividade
- **Força maior**: Motivo que exclui a responsabilidade do transportador
- **Cláusula excludente de responsabilidade**: Cláusula que tenta evitar a responsabilidade do transportador

