O texto discute a responsabilidade civil das instituições financeiras e a aplicação do Código de Defesa do Consumidor nas relações bancárias. A responsabilidade é objetiva, pois envolve atividades de risco que podem causar danos a terceiros.

### Conceitos
- **Responsabilidade Civil**: A responsabilidade por danos causados a terceiros
- **Código de Defesa do Consumidor**: Lei que regula as relações entre consumidores e empresas
- **Risco da Atividade**: A teoria que visa proteger o interesse das vítimas de danos causados pela atividade exercida pelas instituições financeiras
- **Nexo de Causalidade**: A conexão entre a ação da instituição financeira e os danos causados ao terceiro

