  ('cpiuris2025::820dd3e81889d185d44d7a1c49776bbb', 'doutrina', 'cp_iuris', 'Direito Civil — Fraude e Responsabilidade Civil', '## Fraude e Responsabilidade Civil

A fraude é caracterizada como fortuito interno, não afastando a responsabilidade civil prevista no artigo 14 da Lei nº 8.078/90.

### Conceitos
- **Fortuito Interno**: Ocorre quando o risco é integrado à atividade empresarial
- **Responsabilidade Civil**: Previsada no artigo 14 da Lei nº 8.078/90
- **Fraude**: Prática que caracteriza fortuito interno e não afasta a responsabilidade civil

### Referências legais
- Art. 14 da Lei nº 8.078/90

### Jurisprudência
- Súmula 479 do STJ

