  ('cpiuris2025::3af0210b83085d93101ad02c04d5da35', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

Instituições financeiras respondem objetivamente por danos causados por fraudes e delitos de terceiros em operações bancárias, especialmente golpes de falsa central de atendimento.

### Conceitos
- **Responsabilidade objetiva**: Instituições financeiras respondem objetivamente por danos causados por fraudes e delitos de terceiros em operações bancárias.
- **Golpe da falsa central de atendimento**: Fraude na qual o estelionatário se passa por funcionário da instituição financeira e induz o correntista a realizar movimentações financeiras em favor de grupo criminoso.
- **Spoofing**: Alteração do número da chamada telefônica para enganar a vítima.

### Referências legais
- Art. 8º do Código de Defesa do Consumidor

### Jurisprudência
- Súmula 479
- Acórdão 1729740

### Dicas de prova
- Distinção entre responsabilidade objetiva e subjetiva
- Caracterização do golpe da falsa central de atendimento
- Importância do spoofing na fraude', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.390 (1)", "page_number": 390, "discipline": "Direito Civil", "legal_refs": ["Art. 8º do Código de Defesa do Consumidor"], "jurisprudence": ["Súmula 479", "Acórdão 1729740"], "confidence": 0.9, "extracted_at": "2026-05-26T01:22:11.799212+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=390", "doc_key": "3af0210b83085d93101ad02c04d5da35"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'ba82b6a6948f0ee744c6a6a2e2d50b76ededb79a7210b5d23360b205c638b02a'),
  ('cpiuris2025::2ec14bbd0dd905dc8f1af795ea31e7ce', 'doutrina', 'cp_iuris', 'Direito Civil — Culpa concorrente do consumidor em golpes de cartão de crédito', '## Culpa concorrente do consumidor em golpes de cartão de crédito

A jurisprudência considera culpa concorrente do consumidor ao entregar voluntariamente cartão e senha ao golpista, mesmo sem comprovar a posse de dados sigilosos.

### Conceitos
- **Culpa concorrente**: Condição em que ambas as partes (consumidor e golpista) são consideradas culpáveis pelo dano causado
- **Golpe de cartão de crédito**: Tipo de golpe em que o golpista se faz passar por funcionário do banco para obter informações confidenciais do consumidor
- **Nexo de causalidade**: Condição necessária para a responsabilidade civil, que exige uma conexão lógica entre o ato doloso e o dano causado

### Referências legais
- Súmula 1392967/DFT
- Súmula 1399264/DFT

### Jurisprudência
- RE 123456
- Acórdão 1392967/2021
- Acórdão 1399264/2022

### Dicas de prova
- Distinção entre culpa concorrente e exclusiva
- Importância do nexo de causalidade na responsabilidade civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.390 (2)", "page_number": 390, "discipline": "Direito Civil", "legal_refs": ["Súmula 1392967/DFT", "Súmula 1399264/DFT"], "jurisprudence": ["RE 123456", "Acórdão 1392967/2021", "Acórdão 1399264/2022"], "confidence": 0.8, "extracted_at": "2026-05-26T01:22:41.596913+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=390", "doc_key": "2ec14bbd0dd905dc8f1af795ea31e7ce"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '9a01ac640fe102fb79abd31352be220cbbb8f01966b274876f34cecccaaecd50'),
  ('cpiuris2025::d1a53120bea0a2cdeb0ec729cec56768', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil', '## Responsabilidade Civil

O golpe do falso boleto é uma modalidade de estelionato que visa induzir a vítima a pagar valores que caem diretamente na conta do golpista. A responsabilidade civil pode ser dividida em culpa concorrente e culpa exclusiva da vítima, dependendo da negligência do consumidor em entregar dados bancários ao golpista.

### Conceitos
- **Culpa Concorrente**: Responsabilidade compartilhada entre o golpista e a vítima
- **Culpa Exclusiva**: Responsabilidade única da vítima por não avaliar corretamente os dados fornecidos
- **Nexo de Causalidade**: Conexão lógica entre a ação do golpista e o dano causado à vítima
- **Excludentes do Nexo de Causalidade**: Institutos jurídicos que podem afastar a responsabilidade da instituição financeira por não terem cumprido seu dever de segurança

### Referências legais
- Art. 1778, CTN
- Súmula 177/STJ
- TJDFT - Acórdão 1778807

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade civil em estelionato

### Dicas de prova
- Distinção entre culpa concorrente e exclusiva
- Importância do nexo de causalidade
- Excludentes do nexo de causalidade: dever de segurança da instituição financeira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.391 (1)", "page_number": 391, "discipline": "Direito Civil", "legal_refs": ["Art. 1778, CTN", "Súmula 177/STJ", "TJDFT - Acórdão 1778807"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade civil em estelionato"], "confidence": 0.8, "extracted_at": "2026-05-26T01:23:31.926814+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=391", "doc_key": "d1a53120bea0a2cdeb0ec729cec56768"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '5af473f26085d6643c1798afeda4f4f912a7ef4d3fe3f3c2dca9105579edf718'),
  ('cpiuris2025::8a0eaa2a0e0565d5b23b5776dc1196bb', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade do Correntista em Operações Bancárias', '## Responsabilidade do Correntista em Operações Bancárias

O correntista é responsável por sua senha e cartão bancário, e deve tomar medidas para evitar que terceiros o façam acessar. A instituição financeira não precisa comprovar a participação pessoal do correntista no saque.

### Conceitos
- **Responsabilidade do Correntista**: O correntista é responsável por sua senha e cartão bancário.
- **Negligência**: A instituição financeira não precisa comprovar a participação pessoal do correntista no saque, apenas que o saque foi feito com o cartão e a senha cadastrada.
- **Imperícia**: A instituição financeira tem a obrigação de tomar medidas para evitar a continuação da fraude.
- **Prudência**: A instituição financeira é responsável por sua prudência na entrega do dinheiro.
- **Zelo**: O correntista deve mostrar zelo em proteger seu cartão e senha bancários.
- **Falha no Serviço**: A instituição financeira é responsável por sua falha no serviço de segurança.
- **Serviço Digno do Consumidor**: A instituição financeira tem a obrigação de fornecer um serviço digno ao consumidor.

### Referências legais
- Art. 49 da Lei nº 9.454/1997
- ...

### Jurisprudência
- STJ - AgInt no AREsp 1.728.279-SP
- STJ - REsp 1.898.812-SP

### Dicas de prova
- Pergunte se o correntista é responsável por sua senha e cartão bancário.
- Verifique se a instituição financeira tem a obrigação de tomar medidas para evitar a continuação da fraude.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.391 (2)", "page_number": 391, "discipline": "Direito Civil", "legal_refs": ["Art. 49 da Lei nº 9.454/1997", "..."], "jurisprudence": ["STJ - AgInt no AREsp 1.728.279-SP", "STJ - REsp 1.898.812-SP"], "confidence": 0.8, "extracted_at": "2026-05-26T01:24:12.095306+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=391", "doc_key": "8a0eaa2a0e0565d5b23b5776dc1196bb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '29b575880ed63e207939ab0c2cf2348ff082d5994ea52de9ad2baf44c1687f76'),
  ('cpiuris2025::a8e8da3fecb45c86678161ec16f863f9', 'doutrina', 'cp_iuris', 'Direito Civil — Responsabilidade Civil e Direito de Família', '## Responsabilidade Civil e Direito de Família

O Direito de Família é um ramo do Direito Civil que está em constante evolução, afetado pelas mudanças sociais. É necessário compreender os princípios e a legislação para solucionar casos concretos.

### Conceitos
- **Princípios do direito de família**: Normas jurídicas que incorporam exigências de justiça e valores éticos
- **Regras legais**: Normas jurídicas específicas que compõem o ordenamento jurídico positivo
- **Justiça**: Exigência fundamental do direito
- **Valores éticos**: Conceitos morais que influenciam a aplicação da lei
- **Diferença entre princípios e regras**: Princípios são normas jurídicas mais gerais, enquanto regras são específicas

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre princípios e regras no Direito de Família
- Conheça os valores éticos que influenciam a aplicação da lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.393", "page_number": 393, "discipline": "Direito Civil", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T01:24:47.229512+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=393", "doc_key": "a8e8da3fecb45c86678161ec16f863f9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c6ac07692b4546aa6b4510fbb5054653d972254118b6946207c1f7d03d0f6b12'),
  ('cpiuris2025::2ff3e2eb0a3a5832d82f3fd3c3eeb5db', 'doutrina', 'cp_iuris', 'Direito Civil — Princípios do Direito de Família', '## Princípios do Direito de Família

O texto destaca a importância dos princípios no Direito de Família, destacando a solidariedade familiar como um princípio fundamental que abrange aspectos materiais e afetivos, sociais, morais, patrimoniais e espirituais. Os princípios são aplicados em diferentes questões relacionadas ao direito de família, como responsabilidade civil dos pais, comunhão de vida, mútua assistência entre cônjuges e companheiros, colaboração nos assuntos da família e obrigação dos cônjuges.

### Conceitos
- **Princípio da solidariedade familiar**: A ideia de que todos os membros de uma entidade familiar respondem por todos os demais e por cada um, de forma recíproca
- **Regras vs Princípios**: As regras são normas que incidem sob a forma ''tudo ou nada'', enquanto os princípios têm um grau generalizante e são aplicáveis em diferentes questões do direito de família
- **Dignidade da pessoa humana**: Fundamento do Estado Democrático de Direito, que fundamenta todas as relações entre pessoas, especialmente aquelas que integram uma entidade familiar

### Referências legais
- artigo 1º, III, da CF

### Dicas de prova
- Entenda a distinção entre regras e princípios no Direito de Família
- Conheça o princípio da solidariedade familiar e sua aplicação em diferentes questões do direito de família', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.394 (1)", "page_number": 394, "discipline": "Direito Civil", "legal_refs": ["artigo 1º, III, da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:25:37.612083+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=394", "doc_key": "2ff3e2eb0a3a5832d82f3fd3c3eeb5db"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'f356b186dcbd1da9f98f4555f41ae93f21e114151551b5334c0da3d265d22bfe'),
  ('cpiuris2025::a13ac9d7e5e8515a4aae46f44b0341d1', 'doutrina', 'cp_iuris', 'Direito Civil — Dobro Virtute e Poder Familiar', '## Dobro Virtute e Poder Familiar

Regras sobre o poder familiar, incluindo alimentos, habitação e adoção.

### Conceitos
- **Poder Familiar**: direito que permite ao cônjuge ou companheiro exercer controle sobre a vida do outro
- **Dobro Virtute**: direito que se origina da virtude ou vício de alguém em relação a outrem
- **Alimentos**: dever de prestar alimentos aos parentes, cônjuges ou companheiros
- **Direito Real de Habitação**: proteção do direito de moradia do cônjuge supérstite

### Referências legais
- Art. 1.568
- Art. 1.618
- Art. 1.630
- Art. 1.640
- Art. 1.694
- Art. 1.725
- Art. 1.831

### Dicas de prova
- Entenda a diferença entre poder familiar e dobro virtute
- Conheça as regras sobre alimentos e direito real de habitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.394 (2)", "page_number": 394, "discipline": "Direito Civil", "legal_refs": ["Art. 1.568", "Art. 1.618", "Art. 1.630", "Art. 1.640", "Art. 1.694", "Art. 1.725", "Art. 1.831"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:26:03.861642+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=394", "doc_key": "a13ac9d7e5e8515a4aae46f44b0341d1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '4fc7ca3a6a39893554f032f95e6a958a2f872b8f0778637b10c734d3e72614f2'),
  ('cpiuris2025::2038ac8ca9b032b2ab0558700b34c5ca', 'doutrina', 'cp_iuris', 'Direito Civil — Princípios da Família', '## Princípios da Família

Resumo do texto sobre princípios da família, incluindo solidariedade, igualdade entre filhos e cônjuges/companheiros.

### Conceitos
- **Solidariedade**: Princípio que prevalece mesmo diante da culpa em relação aos alimentos devidos pelo cônjuge/inocente ao culpado.
- **Igualdade entre filhos**: Princípio que estabelece os mesmos direitos e qualificações para os filhos, independentemente da origem da concepção ou adoção.
- **Igualdade entre cônjuges e companheiros**: Princípio que estabelece a isonomia substancial entre os cônjuges e companheiros de uma entidade familiar, resolvendo questões de forma igualitária.

### Referências legais
- Art. 227, §6º, da CF
- Súmula N STJ

### Jurisprudência
- RE 1.624.050/MG
- Recurso Especial nº 1.624.050/MG, 18/06/2018

### Dicas de prova
- Entenda a solidariedade em relação aos alimentos devidos pelo cônjuge/inocente ao culpado.
- Aplique o princípio da igualdade entre filhos e cônjuges/companheiros para resolver questões familiares.
- Análise criteriosa é necessária para fixar valores de alimentos de forma igualitária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.395 (1)", "page_number": 395, "discipline": "Direito Civil", "legal_refs": ["Art. 227, §6º, da CF", "Súmula N STJ"], "jurisprudence": ["RE 1.624.050/MG", "Recurso Especial nº 1.624.050/MG, 18/06/2018"], "confidence": 0.8, "extracted_at": "2026-05-26T01:26:42.321475+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=395", "doc_key": "2038ac8ca9b032b2ab0558700b34c5ca"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'aa9a15dff02b6754c122aa2f931506671c9e4cecbc489071416f1ec5dedcab57'),
  ('cpiuris2025::adb187524bfe2cfaad1a8f254c655589', 'doutrina', 'cp_iuris', 'Direito Civil — Princípios da Família', '## Princípios da Família

Resumo do texto: Discute os princípios da família, incluindo não intervenção, maior interesse da criança e do adolescente, e a importância da liberdade familiar.

### Conceitos
- **Princípio da Não Intervenção**: Protege a liberdade da família e proíbe interferência em sua comunhão de vida
- **Maior Interesse da Criança e do Adolescente**: Garantia dos direitos das crianças e adolescentes em todos os níveis de convivência
- **Liberdade Familiar**: Direito à liberdade para escolher o planejamento familiar

### Referências legais
- Art. 226, caput, da CF
- Art. 1.513 do CC
- Lei nº 9.623/1996

### Dicas de prova
- Entenda a diferença entre não intervenção e interferência na família
- Conheça os direitos das crianças e adolescentes em relação à família', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.395 (2)", "page_number": 395, "discipline": "Direito Civil", "legal_refs": ["Art. 226, caput, da CF", "Art. 1.513 do CC", "Lei nº 9.623/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:27:19.637373+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=395", "doc_key": "adb187524bfe2cfaad1a8f254c655589"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '07edcedc7884f7c6e8f3d4478f4c9856629ed6380cb1cc1741f5f30c4c40f87d'),
  ('cpiuris2025::95dc10014c38ab70e6813516b5b75bf1', 'doutrina', 'cp_iuris', 'Direito Civil — Princípio do Maior Interesse da Criança e do Adolescente', '## Princípio do Maior Interesse da Criança e do Adolescente

O princípio do maior interesse da criança e do adolescente é consagrado no art. 227 da CF, estabelecendo prioridade para a proteção de direitos como vida, saúde, educação, entre outros.

### Conceitos
- **Maior Interesse**: Princípio que prioriza o bem-estar e os direitos da criança e do adolescente
- **Criança**: Pessoa com idade compreendida entre 0 e 12 anos
- **Adolescente**: Pessoa com idade compreendida entre 13 e 18 anos, mas também pode ser considerada como jovem até os 29 anos
- **Guarda Compartilhada**: Forma de guarda em que ambos os pais ou responsáveis compartilham a custódia da criança ou adolescente
- **Unilateral**: Forma de guarda em que um dos pais ou responsáveis tem exclusiva custódia da criança ou adolescente

### Referências legais
- Art. 227 da CF

### Dicas de prova
- Entenda o conceito de maior interesse e sua aplicação na guarda
- Conheça a diferença entre criança, adolescente e jovem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.396 (1)", "page_number": 396, "discipline": "Direito Civil", "legal_refs": ["Art. 227 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:27:52.427872+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=396", "doc_key": "95dc10014c38ab70e6813516b5b75bf1"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'c5903233a1f215ec2f2566f5ce25568a6d44321698eae6c8b6641550f9437f0b'),
  ('cpiuris2025::ab87bd14094e5dc8031e6a07b604fc1c', 'doutrina', 'cp_iuris', 'Direito Civil — O Princípio da Afetividade', '## O Princípio da Afetividade

A discussão sobre a possibilidade de o Estado impor sentimento nas relações familiares, afirmando que o afeto não pode ser imposto e que suas consequências devem ser tuteladas pelo Estado.

### Conceitos
- **Afetividade**: O princípio que afirma que o afeto não pode ser imposto pelo Estado
- **Liberdade do Ser Humano**: O direito fundamental de cada pessoa a escolher seu próprio caminho em suas relações
- **Paternidade Socioafetiva**: Relação entre pai e filho baseada no afeto

### Referências legais
- CARNACCHIONI, 2018, p. 1460

### Jurisprudência
- RE 123456
- ...

