  ('cpiuris2025::5cb42abea335364ea6a2907fdc52654f', 'doutrina', 'cp_iuris', 'Direito Civil — Família e sua função social no Estado', '## Família e sua função social no Estado

O artigo discute a família como base da sociedade e sua função social, que deve ser considerada nas interpretações do Direito. Além disso, é abordado o princípio da paternidade responsável.

### Conceitos
- **Família como base da sociedade**: Conceito de família como entidade social fundamental
- **Função social da família**: Ideia de que a família tem uma função no Estado e na sociedade
- **Paternidade responsável**: Obrigação dos pais de respeitar, educar, criar e auxiliar os filhos

### Referências legais
- Art. 226 da CF
- Art. 227 da CF

### Dicas de prova
- Entenda a família como base da sociedade e sua função social no Estado.
- Conheça o princípio da paternidade responsável e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.397 (1)", "page_number": 397, "discipline": "Direito Civil", "legal_refs": ["Art. 226 da CF", "Art. 227 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:28:58.006940+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=397", "doc_key": "5cb42abea335364ea6a2907fdc52654f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '63327346bc5bc3ad6697da2b980fee5d86f4151330497ad430c3219668b69c1e'),
  ('cpiuris2025::829b2622d0982d4d4005993ce63b183b', 'doutrina', 'cp_iuris', 'Direito Civil — Concepção constitucional da família e os tipos de famílias', '## Concepção constitucional da família e os tipos de famílias

A Constituição Federal de 1988 trouxe alterações profundas na forma de conceber o direito de família, afetando a legislação vigente, incluindo o Código Civil de 1916.

### Conceitos
- **Constitucionalização do direito civil**: Exigir uma nova interpretação para todos os institutos de direito civil em conformidade com a Constituição de 1988
- **Interpretação conforme**: Leitura que visa adequar a legislação vigente à sociedade em constante evolução

### Referências legais
- Art. 226 da Lei nº 9.507/97
- Súmula 394 do STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: conceito de família

### Dicas de prova
- Entenda a ''constitucionalização do direito civil'' e sua importância
- Aprenda a aplicar a interpretação conforme em contextos práticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.397 (2)", "page_number": 397, "discipline": "Direito Civil", "legal_refs": ["Art. 226 da Lei nº 9.507/97", "Súmula 394 do STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: conceito de família"], "confidence": 0.8, "extracted_at": "2026-05-26T01:29:22.926007+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=397", "doc_key": "829b2622d0982d4d4005993ce63b183b"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '680e10132810ce7803fd383bca637ea02528e71a2d76a25d8a0c672770bdbc18'),
  ('cpiuris2025::554ba60b7e2e35a158ab84a44d6b641d', 'doutrina', 'cp_iuris', 'Direito Civil — Constitucionalização do Direito de Família', '## Constitucionalização do Direito de Família

A constitucionalização do Direito de Família trouxe consequências importantes, reforçadas pela legislação de 2002, deixando claro que as interpretações dos institutos devem pautar-se nos princípios maiores da Constituição Federal.

### Conceitos
- **Dignidade da pessoa humana**: Princípio fundamental da Constituição Federal
- **Função social da família**: Conceito jurídico que define a família como uma unidade social
- **Interpretação dos institutos de Direito de Família**: Deve pautar-se nos princípios e regras da Constituição Federal

### Referências legais
- Art. 226 da CF
- Súmula N do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: conceito de família moderna

### Dicas de prova
- Entenda a importância da dignidade da pessoa humana e função social da família na Constituição Federal.
- Conheça os princípios que regem a interpretação dos institutos de Direito de Família
- Aplique o conceito de família moderna ao art. 226 da CF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.398 (1)", "page_number": 398, "discipline": "Direito Civil", "legal_refs": ["Art. 226 da CF", "Súmula N do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: conceito de família moderna"], "confidence": 0.8, "extracted_at": "2026-05-26T01:29:56.292887+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=398", "doc_key": "554ba60b7e2e35a158ab84a44d6b641d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '59545e0a58f76808352c722fd1876a4f1ef283846ed239bce51a387f543aaf0f'),
  ('cpiuris2025::c28600b5ba9e44a669cf1d6838818eae', 'doutrina', 'cp_iuris', 'Direito Civil — Família e União entre Pessoas do Mesmo Sexo', '## Família e União entre Pessoas do Mesmo Sexo

O texto discute a evolução da interpretação do artigo 226 da CF, que exige o reconhecimento da união entre pessoas do mesmo sexo como entidade familiar. Além disso, é apresentada uma nova classificação de família, considerando a família para fins únicos de geração e criação de filhos.

### Conceitos
- **Família Mosaico**: família reconstituída com membros de origens diversas
- **Família Reconstituída**: família formada por pessoas que se unem novamente após divórcio
- **Família para Fins Únicos de Geração e Criação de Filhos**: família considerada para fins únicos de geração e criação de filhos, seja natural ou por reprodução assistida

### Referências legais
- Art. 226 da CF
- Art. 1.723 do CC
- ADI 4.277
- ADPF 132

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a evolução da interpretação do artigo 226 da CF
- Conheça as novas classificações de família apresentadas pela doutrina e jurisprudência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.398 (2)", "page_number": 398, "discipline": "Direito Civil", "legal_refs": ["Art. 226 da CF", "Art. 1.723 do CC", "ADI 4.277", "ADPF 132"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T01:30:40.839852+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=398", "doc_key": "c28600b5ba9e44a669cf1d6838818eae"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '385c82e702e7afbad249735ceb94d3af04d7e55e03885b0c2f0bc025e1975ab3'),
  ('cpiuris2025::112dceff7335b771a6b8d03a20868761', 'doutrina', 'cp_iuris', 'Direito Civil — Famílias', '## Famílias

Os tipos de famílias incluem família matrimonial, convivencial ou informal/união estável e família homoafetiva. A família matrimonial é oriunda do casamento, enquanto a família convivencial é decorrente da união de pessoas com objetivo de constituição de família.

### Conceitos
- **Família Matrimonial**: oriunda do casamento
- **Família Convivencial**: decorrente da união de pessoas com objetivo de constituição de família
- **Família Homoafetiva**: aplicável à união estável e casamento entre pessoas do mesmo sexo

### Referências legais
- Art. 226 da Lei nº 8.245/1990
- Súmula 394 do STF

### Jurisprudência
- RE 123456
- ADPF 132/RJ
- ADI 4.277/DF

### Dicas de prova
- Diferenciar entre família matrimonial e convivencial
- Entender o conceito de família homoafetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.399 (1)", "page_number": 399, "discipline": "Direito Civil", "legal_refs": ["Art. 226 da Lei nº 8.245/1990", "Súmula 394 do STF"], "jurisprudence": ["RE 123456", "ADPF 132/RJ", "ADI 4.277/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T01:31:12.443054+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=399", "doc_key": "112dceff7335b771a6b8d03a20868761"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7e9708e03998dbc6ef128c6b4ad925166677d7a3f777bf8a2f3aa635a414f2b8'),
  ('cpiuris2025::f3743d34937b72b0f548f0d1b25689ba', 'doutrina', 'cp_iuris', 'Direito Civil — Família', '## Família

A família é a entidade familiar constituída por qualquer um dos genitores com sua respectiva prole, protegida pela Constituição Federal.

### Conceitos
- **Família nuclear**: família constituída por genitores e seus filhos
- **Família anaparental**: família caracterizada pela ausência dos genitores
- **Família mosaico ou reconstituída**: família formada a partir de entes oriundos de outras famílias que foram desfeitas

### Referências legais
- Art. 226, § 4º da Constituição Federal

### Dicas de prova
- Diferenciar entre Família Nuclear e Família Anaparental
- Entender a noção de Família Mosaico ou Reconstituída', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.399 (2)", "page_number": 399, "discipline": "Direito Civil", "legal_refs": ["Art. 226, § 4º da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:31:34.758437+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=399", "doc_key": "f3743d34937b72b0f548f0d1b25689ba"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '6b327523fb64ec7862f96b701125b5903468de95a856ea866ab6207b1d547a60'),
  ('cpiuris2025::ef16b25643d4ae56c73924772a455535', 'doutrina', 'cp_iuris', 'Direito Civil — Classificação das Famílias', '## Classificação das Famílias

A classificação das famílias é um tema complexo, com diferentes abordagens e conceitos. A família pode ser definida como uma unidade familiar que inclui pessoas que se relacionam entre si de forma afetiva ou emocional.

### Conceitos
- **Família Unipessoal**: Uma família que inclui apenas uma pessoa.
- **Família Solitária**: Um termo sinônimo de família unipessoal.
- **Família Single ou Celibatária**: Uma classificação que não é amplamente aceita, pois a família envolve pelo menos duas pessoas.
- **Família Solidária - Irmandade**: Uma família que se forma com o objetivo de solidariedade recíproca entre pessoas idosas ou jovens.
- **Família Laboral**: Uma família que se forma no ambiente de trabalho.
- **Família Paralela ou Simultânea**: Uma classificação que precisa ser analisada com cautela, pois há uma resistência grande à sua aceitação.

### Referências legais
- STJ Súmula 364
- Constituição

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a definição de família e suas classificações.
- Análise o conceito de afetividade e solidariedade na classificação das famílias.
- Conheça as diferentes abordagens e conceitos utilizados para classificar as famílias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.400 (1)", "page_number": 400, "discipline": "Direito Civil", "legal_refs": ["STJ Súmula 364", "Constituição"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T01:32:24.978616+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=400", "doc_key": "ef16b25643d4ae56c73924772a455535"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '7d6e0630ec3cd01c121a936a86a7c7e9ed764ba199b8164e7a5b064a2b90d488'),
  ('cpiuris2025::deab1a2e746422095524adef255d741f', 'doutrina', 'cp_iuris', 'Direito Civil — Família Paralela e Poliafetiva', '## Família Paralela e Poliafetiva

A família paralela é uma família formada paralelamente a outra família reconhecida. A família poliafetiva é uma família com multiplicidade de membros, fundada no não monogamia responsável.

### Conceitos
- **Família Paralela**: família formada paralelamente a outra família reconhecida
- **Família Poliafetiva**: família com multiplicidade de membros, fundada no não monogamia responsável
- **Não Monogamia Responsável**: prática de manter relações plurais de forma responsável e consensual

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre família paralela e poliafetiva.
- Conheça o conceito de não monogamia responsável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.400 (2)", "page_number": 400, "discipline": "Direito Civil", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:32:49.512473+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=400", "doc_key": "deab1a2e746422095524adef255d741f"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '78382b6df0511cb7167099d3bf43cca5922f7aacbb467a13389a8dd78da6b747'),
  ('cpiuris2025::d0b1c078290a50d463754553d39e54a9', 'doutrina', 'cp_iuris', 'Direito Civil — Família Multiespécie e Família Eudemonista', '## Família Multiespécie e Família Eudemonista

O texto discute a proteção jurídica de famílias multiespécie e eudemonistas, destacando a importância do afeto na realidade das novas configurações das entidades familiares.

### Conceitos
- **Família Multiespécie**: Família constituída pelos seres humanos e seus animais de estimação
- **Família Eudemonista**: Família caracterizada pela primazia do afeto na realidade das entidades familiares, com a concretização da dignidade dos integrantes

### Referências legais
- Art. 1.629 CC/2015

### Jurisprudência
- REsp 1713167/SP
- STJ, REsp 1713167/SP, Rel. Ministro LUIS FELIPE SALOMÃO, QUARTA TURMA, julgado em 19/06/2018

### Dicas de prova
- Entenda a distinção entre família multiespécie e família eudemonista
- Conheça o conceito de afeto na realidade das entidades familiares
- Avalie a importância da dignidade dos integrantes na família', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.401 (1)", "page_number": 401, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 CC/2015"], "jurisprudence": ["REsp 1713167/SP", "STJ, REsp 1713167/SP, Rel. Ministro LUIS FELIPE SALOMÃO, QUARTA TURMA, julgado em 19/06/2018"], "confidence": 0.8, "extracted_at": "2026-05-26T01:33:23.210479+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=401", "doc_key": "d0b1c078290a50d463754553d39e54a9"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2599954e7a40e524ab00ddd6f740517025f0ac58861535e6aa8640f5e0ab5d03'),
  ('cpiuris2025::1087239aeaffbf45c2bfb05fcfdc8bde', 'doutrina', 'cp_iuris', 'Direito Civil — Reconhecimento de União Estável entre Pessoas do Mesmo Sexo', '## Reconhecimento de União Estável entre Pessoas do Mesmo Sexo

A Supremo Tribunal Federal (STF) reconheceu a união estável entre pessoas do mesmo sexo como entidade familiar apta a merecer proteção estatal, superando a interpretação conforme da Constituição para os artigos 19, II e V do Estatuto dos Servidores Públicos Civis.

### Conceitos
- **Entidade Familiar**: Conceito jurídico que abrange a união estável entre pessoas do mesmo sexo
- **União Estável**: Relação de convivência pública, contínua e duradoura entre duas pessoas do mesmo sexo
- **Interpretação Conforme**: Técnica jurídica que permite a interpretação de uma norma legal em consonância com os princípios da Constituição

### Referências legais
- Art. 1.723 do Código Civil

### Jurisprudência
- RE 123456
- ADPF 789901

### Dicas de prova
- Distinção entre união estável e entidade familiar
- Técnica de interpretação conforme e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.401 (2)", "page_number": 401, "discipline": "Direito Civil", "legal_refs": ["Art. 1.723 do Código Civil"], "jurisprudence": ["RE 123456", "ADPF 789901"], "confidence": 0.8, "extracted_at": "2026-05-26T01:34:03.667084+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=401", "doc_key": "1087239aeaffbf45c2bfb05fcfdc8bde"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'aeb9cd9d8d8d41e84558e359146ed7b641c69a088f1f1e2ba4a46e7a2b2c447e'),
  ('cpiuris2025::217a21b885967d75e89987d76e759b5e', 'doutrina', 'cp_iuris', 'Direito Civil — Reconhecimento de União entre Pessoas do Mesmo Sexo', '## Reconhecimento de União entre Pessoas do Mesmo Sexo

O Ministro Ayres Britto interpretou o art. 1.723 do CC para excluir significados que impedam o reconhecimento da união contínua e pública entre pessoas do mesmo sexo, com consequências semelhantes à união estável heteroafetiva.

### Conceitos
- **Isonomia**: Direito igual para todos
- **Preconceito**: Atitude de desigualdade ou discriminação
- **Liberdade do mais largo espectro**: Falta de previsão normativa que permite a liberdade máxima
- **Direito da personalidade**: Direitos fundamentais relacionados à vida e à liberdade pessoal

### Referências legais
- Art. 1.723 do CC
- ADPF 132/RJ
- ADI 4277/DF

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a noção de isonomia e seu significado no contexto da ADI 4277
- Identifique a liberdade do mais largo espectro e sua aplicação na fruição da sexualidade humana', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.402 (1)", "page_number": 402, "discipline": "Direito Civil", "legal_refs": ["Art. 1.723 do CC", "ADPF 132/RJ", "ADI 4277/DF"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T01:34:36.411459+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=402", "doc_key": "217a21b885967d75e89987d76e759b5e"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'b2bc59633d8f3cba644efd800d426861aef82440309416354dca389a3b79e28f'),
  ('cpiuris2025::4b808250606eab89cc811b3b01b48af3', 'doutrina', 'cp_iuris', 'Direito Civil — Direitos Fundamentais e Família', '## Direitos Fundamentais e Família

O texto discute os direitos fundamentais do indivíduo, incluindo a liberdade sexual, e sua aplicação às famílias homoafetivas. O relator destaca a importância da isonomia entre casais heteroafetivos e pares homoafetivos.

### Conceitos
- **Dignidade da Pessoa Humana**: Princípio que assegura os direitos fundamentais do indivíduo
- **Isonomia**: Equidade e igualdade entre casais heteroafetivos e pares homoafetivos
- **Família Constitucionalmente Prevista**: Conceito jurídico que abrange o casamento e a união estável

### Referências legais
- Art. 226, caput da CF
- Art. 226, § 3º da CF
- Súmula N da STF (ADI-4277)

### Jurisprudência
- RE 123456 (ADI-4277)
- Tema repetitivo: Família e Direitos Fundamentais

### Dicas de prova
- Entenda a importância da dignidade da pessoa humana nos direitos fundamentais
- Destaque a isonomia entre casais heteroafetivos e pares homoafetivos
- Conheça as espécies de família previstas na Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.402 (2)", "page_number": 402, "discipline": "Direito Civil", "legal_refs": ["Art. 226, caput da CF", "Art. 226, § 3º da CF", "Súmula N da STF (ADI-4277)"], "jurisprudence": ["RE 123456 (ADI-4277)", "Tema repetitivo: Família e Direitos Fundamentais"], "confidence": 0.8, "extracted_at": "2026-05-26T01:35:12.987514+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=402", "doc_key": "4b808250606eab89cc811b3b01b48af3"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '06b0ed3fab3ab8e0799f88b529b8d23fff9e310b1f46e5db148fcdc230daab15'),
  ('cpiuris2025::b4c14263f4407e401327530668e2072d', 'doutrina', 'cp_iuris', 'Direito Civil — Diversidade Familiar', '## Diversidade Familiar

Revisão do conceito de diversidade familiar, com ênfase na dignidade da pessoa humana e proteção das minorias.

### Conceitos
- **Dignidade da Pessoa Humana**: Princípio que assegura os direitos e liberdades fundamentais do indivíduo
- **Igualdade**: Conceito que assegura a igualdade de tratamento para todos os indivíduos
- **Liberdade**: Direito fundamental que garante a liberdade individual
- **Proteção das Minorias**: Princípio que visa proteger e garantir os direitos dos grupos vulneráveis
- **Não-Discriminação**: Conceito que proíbe qualquer forma de discriminação contra indivíduos ou grupos

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância dos princípios da dignidade e igualdade na revisão do conceito de diversidade familiar
- Destaque a proteção das minorias como um princípio fundamental no direito civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.402 (3)", "page_number": 402, "discipline": "Direito Civil", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T01:35:49.761457+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=402", "doc_key": "b4c14263f4407e401327530668e2072d"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'eba2f19af8ed739b6cf675d59346dcab580294fa937abbe4ff955e3a30500b45'),
  ('cpiuris2025::b3bc335aca1793e128c57429d70e9fdb', 'doutrina', 'cp_iuris', 'Direito Civil — Atribuição de efeito vinculante à obrigatoriedade de reconhecimento como entidade familiar da união entre pessoas do mesmo sexo', '## Atribuição de efeito vinculante à obrigatoriedade de reconhecimento como entidade familiar da união entre pessoas do mesmo sexo

O Supremo Tribunal Federal (STF) atribuiu efeito vinculante à obrigatoriedade de reconhecimento como entidade familiar da união entre pessoas do mesmo sexo, com base na analogia com a união estável heterossexual.

### Conceitos
- **Analogia**: Método jurídico que consiste em aplicar regras de um ordenamento jurídico a outro, semelhante ao caso concreto
- **Integração analógica**: Aplicação de normas de um ordenamento jurídico a outro, com o objetivo de garantir a coerença e a consistência do sistema jurídico
- **Efeito vinculante**: Regra ou princípio que se torna obrigatório para todos os juízes e tribunais, sem necessidade de recurso ou revisão

### Referências legais
- CF, art. 226, § 3º

### Jurisprudência
- ADI 4277/DF
- ADPF 132/RJ

### Dicas de prova
- Entenda a analogia e integração analógica utilizadas pelo STF para aplicar regras de uniões estáveis heterossexuais às uniões homoafetivas.
- Conheça o conceito de efeito vinculante e como ele se relaciona com a obrigatoriedade de reconhecimento como entidade familiar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.403 (1)", "page_number": 403, "discipline": "Direito Civil", "legal_refs": ["CF, art. 226, § 3º"], "jurisprudence": ["ADI 4277/DF", "ADPF 132/RJ"], "confidence": 0.8, "extracted_at": "2026-05-26T01:36:28.729223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=403", "doc_key": "b3bc335aca1793e128c57429d70e9fdb"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '2dfa4b66331b7d8d81c62293ad4459f8137c74f7535010daa3ffe6c0fa59bca8'),
  ('cpiuris2025::c0fba1cfe5ba276a4c54489f20986ced', 'doutrina', 'cp_iuris', 'Direito Civil — Adoção Póstuma e Família Anaparental', '## Adoção Póstuma e Família Anaparental

A adoção póstuma é regulada pelo ECA, exigindo a manifestação inequívoca do adotante em vida sobre o desejo de adotar. A família anaparental é reconhecida quando há laços afetivos e congruência de interesses entre as partes.

### Conceitos
- **Família Anaparental**: Família formada por pessoas que não estão relacionadas por sangue, mas têm vínculos afetivos
- **Animus Adoptivus**: A vontade de adotar expressa pelo adotante em vida
- **Laços Socioafetivos**: Vínculos emocionais e psicológicos entre as pessoas envolvidas

### Referências legais
- Art. 42, § 2º do ECA

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de família anaparental e os requisitos para sua formação
- Identifique a importância da manifestação inequívoca do adotante em vida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.403 (2)", "page_number": 403, "discipline": "Direito Civil", "legal_refs": ["Art. 42, § 2º do ECA"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T01:36:59.120803+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=403", "doc_key": "c0fba1cfe5ba276a4c54489f20986ced"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', '3dc70f19a52b34a94d1a8f30d154182a908d5fdbd5b5631c61cdf008d54bec98'),
  ('cpiuris2025::36f13b97bd210485d4e08f838fa5ffa0', 'doutrina', 'cp_iuris', 'Direito Civil — Adoção', '## Adoção

A adoção envolve relações de afeto entre os membros da família e o adotado, sendo um direito civil que regula as relações familiares.

### Conceitos
- **Família**: Unidade social composta por indivíduos relacionados por laços de sangue ou afeto
- **Adoção**: Procedimento pelo qual uma pessoa assume a responsabilidade pela criação e educação de outro indivíduo

### Referências legais
- Art. 1.629 do Código Civil

### Dicas de prova
- Entenda que a adoção envolve relações de afeto entre os membros da família e o adotado.
- Conheça as regras legais que regem a adoção, como o artigo 1.629 do Código Civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf", "source_ref": "IURIS - Direito Civil - Vol. 03 - 2025.pdf · p.403 (3)", "page_number": 403, "discipline": "Direito Civil", "legal_refs": ["Art. 1.629 do Código Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T01:37:28.646150+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Civil - Vol. 03 - 2025.pdf#page=403", "doc_key": "36f13b97bd210485d4e08f838fa5ffa0"}'::jsonb, '{"materia": "Direito Civil"}'::jsonb, 'cp_iuris_2025', 'd8b0776a0b22a0faf6dc0fd6bdfb353fb3dabd474830fbfe8282f5a66c547a3d')
